INSERT INTO `centers` VALUES (5,'Photos_ScientificResearchInnovationCenters/luPZsgQINXxAlhr0tY2ZlClHQ5MtJBvs26RhUTyl.jpg','المؤسسة المغربية للعلوم المتقدمة والابتكار والبحث العلمي','Moroccan Foundation for Advanced Science, Innovation and Research','تُعدّ المؤسسة المغربية للعلوم المتقدمة والابتكار والبحث (MAScIR) مؤسسة بحثية مغربية غير ربحية تأسست سنة 2007، وتهدف إلى تعزيز البحث العلمي والتطوير التكنولوجي من أجل دعم الاقتصاد القائم على المعرفة بالمملكة المغربية. وترتبط المؤسسة بـ جامعة محمد السادس متعددة التخصصات التقنية، فيما توجد مقراتها الرئيسية بمدينة العرفان بالعاصمة الرباط.',NULL,'http://www.mascir.com/',5,19,1,'2026-06-04 09:17:06','2026-06-04 09:22:26'),(6,'Photos_ScientificResearchInnovationCenters/3BCyTKacUTsZh29JDAu6ao8TopueAzbRKyalo9FI.png','المركز الوطني للبحث العلمي والتقني','null','يُعدّ المركز الوطني للبحث العلمي والتقني مؤسسة عمومية رسمية تابعة للدولة المغربية، يقع مقرها في مدينة الرباط. تم إحداثه في إطار قانوني لتنظيم وتطوير البحث العلمي والتقني بالمغرب، خاصة بموجب القانون رقم 80.00.',NULL,'https://www.cnrst.ma/ar/cnrst/a-propos/presentation',5,19,1,'2026-06-04 09:21:08','2026-06-04 09:46:56'),(7,'Photos_ScientificResearchInnovationCenters/Zt8cUIKzWEwFHy7hgiwwB0DRzKqIeePJShI7HJVp.png','معهد أبحاث الطاقة الشمسية والطاقات الجديدة','null','معهد البحث في الطاقة الشمسية والطاقات الجديدة (ويعرف اختصاراً بـ IRESEN) هو مؤسسة مغربية مكرسة للبحث والتطوير والابتكار في مجال الطاقة المتجددة وكفاءة الطاقة. \r\nتأسس المعهد في عام 2011، ويعد جزءاً من الاستراتيجية الوطنية للطاقة في المغرب التي تهدف إلى تعزيز مصادر الطاقة المستدامة.',NULL,'https://iresen.org/',5,19,1,'2026-06-04 09:27:40','2026-06-04 09:30:33'),(8,'Photos_ScientificResearchInnovationCenters/ZxG77ZabvXNODtOWLntC24RlwVFom7nbWzxoweMH.png','المركز الوطني للدراسات والبحث في الماء والطاقة','CNEREE','المركز الوطني للدراسات والأبحاث حول الماء والطاقة هو مؤسسة بحثية رائدة في المغرب، يقع مقره الرئيسي في جامعة القاضي عياض بمراكش. \r\n\r\nويهدف المركز إلى دراسة أزمة الإجهاد المائي وتطوير حلول مستدامة تدمج بين ترشيد استهلاك المياه، معالجة المياه العادمة، والطاقات المتجددة.',NULL,'https://cneree.uca.ma/',5,19,1,'2026-06-04 09:40:00','2026-06-10 12:03:42'),(9,'Photos_ScientificResearchInnovationCenters/TkedOee11QBJmrf0i4ASmr1uDvX7Wguu6ytsJpWV.jpg','قطب تكنولوجي وصناعي','Technopolis Rabat','تكنوبوليس الرباط (Technopolis Rabat) هو قطب تكنولوجي وصناعي متكامل يقع قرب مدينة سلا بالمغرب، ويهدف إلى تجميع الشركات التكنولوجية ومراكز البحث والابتكار في فضاء واحد لتعزيز التنمية الصناعية والاقتصاد الرقمي وربط البحث العلمي بالصناعة.\r\n: 2007 سنة التأسيس\r\n (وتم إطلاق أولى مراحله سنة 2008)',NULL,'https://www.medz.ma/fr/zones-industrielles',5,19,1,'2026-06-04 09:44:31','2026-06-04 09:44:31'),(10,'Photos_ScientificResearchInnovationCenters/Yw6FzCXzlGe9PTzkfiMO8T25ApODYLC86d7fIhOF.jpg','مركز الابتكار والأبحاث المتقدمة','Aerospace Research And Innovation Center','تم تأسيس مركز الابتكار والأبحاث \r\n المتقدمة في جامعة خليفة سنة 2012 كمبادرة مشتركة بين شركة مبادلة وجامعة خليفة.\r\nيقوم المركز بإجراء أبحاث متقدمة في مجالات المواد المتطورة، والتقنيات الرقمية التطبيقية، والتقنيات التطبيقية في مجال الصحة، إضافة إلى تقنيات الاستدامة.\r\nويُعدّ المركز منصة بحثية عالمية، حيث يتعاون مع جامعات رائدة حول العالم، ويطوّر فرصًا بحثية في مجالات متعددة، ويساهم في نقل التكنولوجيا ودعم الابتكار في مختلف القطاعات الصناعية.',NULL,'https://www.aric.ae/',5,2,1,'2026-06-04 09:59:31','2026-06-04 10:01:24'),(11,'Photos_ScientificResearchInnovationCenters/rbRJsFUN2MzbK33z5x37m3FeY4DV2Pj6AfWbQbiG.jpg','جامعة خليفة للعلوم والتكنولوجيا','null','جامعة خليفة للعلوم والتكنولوجيا هي جامعة بحثية رائدة في دولة الإمارات العربية المتحدة، تأسست سنة 2007، وتضم مراكز بحثية متخصصة في مجالات الطاقة، الفضاء، الهندسة، الذكاء الاصطناعي، والعلوم الطبية.\r\nتتميز الجامعة بتركيزها على البحث التطبيقي وربط الابتكار بالصناعة، حيث تسهم في تطوير حلول تكنولوجية متقدمة تدعم احتياجات الدولة. كما تلعب دوراً محورياً في دعم التنمية التكنولوجية وبناء اقتصاد معرفي قائم على البحث والابتكار في الإمارات.',NULL,'https://www.ku.ac.ae/',5,2,1,'2026-06-04 10:04:48','2026-06-04 10:06:13'),(12,'Photos_ScientificResearchInnovationCenters/QJecj4nYdRNOXwXCY1uN5dBhKWys05ao8bt158Fa.jpg','مجمع الشارقة للبحث والتكنولوجيا والابتكار','Sharjah Research Technology & Innovation Park','تأسست مجمع الشارقة للبحوث والتكنولوجيا والابتكار بأمر صاحب السمو الشيخ الدكتور سلطان بن محمد القاسمي، عضو المجلس الأعلى، حاكم الشارقة في 2016م. إذ صمم هذا المشروع وفق أفضل الممارسات وأعلى المعايير العالمية المتبعة في بناء مجمعات التكنولوجيا، ويركز على محاور عدة من بينها تكنولوجيا المياه، تكنولوجيا البيئة، الطاقة المتجددة، تكنولوجيا المواصلات، تكنولوجيا المعلومات، والتصميم الصناعي والعمارة، كما يعمل على دعم الصناعات الوطنية التي تندرج تحت هذه المحاور، وتكمن أهمية المجمع في ترجمته رؤية صاحب السمو حاكم الشارقة وقادة دولة الامارات بتفعيل دور التعليم والجامعات في البحث العلمي.',NULL,'https://srtip.ae/',5,2,1,'2026-06-04 10:10:54','2026-06-04 10:17:29'),(13,'Photos_ScientificResearchInnovationCenters/pn9xCW5FP5HGvZwpS1PvjVUbTTpNgx0G8N6ZXUAG.webp','جامعة محمد بن زايد للذكاء الاصطناعي',NULL,'تأسست جامعة محمد بن زايد للذكاء الاصطناعي على يد قادة دولة الإمارات العربية المتحدة الذين يتمتعون برؤية مدروسة للمستقبل. وهي تهدف إلى تعليم طلاب من أصحاب المواهب وتطوير قدراتهم، فضلاً عن تعزيز بيئة تشجع الابتكار، وتوفير مؤسسة بحثية استراتيجية داعمة للقطاعين الحكومي والخاص.\r\n\r\nوقد سُميت الجامعة تيمناً بصاحب السمو الشيخ محمد بن زايد آلِ نهيان، رئيس دولة الإمارات العربية المتحدة.\r\n\r\nتؤدي الجامعة دوراً جوهرياً في تحقيق العديد من الأهداف الاستراتيجية لدولة الإمارات العربية المتحدة، لاسيما وأن الذكاء الاصطناعي يشكل عنصراً بالغ الأهمية لتحقيق النمو والازدهار مستقبلاً. وتسعى رؤية الجامعة ورسالتها الاستراتيجيتان في آنٍ لترسيخ مكانة أبوظبي كقطب من أقطاب مجتمع الذكاء الاصطناعي الدولي.\r\n\r\nولا بد من الإشارة إلى أن الجامعة تجذب أهم الخبراء العالميين على الصعيدين الأكاديمي والعملي في مجالات الرؤية الحاسوبية، وتعلم الآلة، ومعالجة اللغات الطبيعية، وغيرها من المجالات.',NULL,'https://mbzuai.ac.ae/ar/',5,2,1,'2026-06-04 10:25:57','2026-06-04 10:25:57'),(14,'Photos_ScientificResearchInnovationCenters/NFhIrXVysNNhVmgA07NwRjtSEmTnkYZssoCtEcCf.png','معهد الابتكار التكنولوجي','Technology Innovation Institute (TII)','يعد معهد الابتكار التكنولوجي مؤسسةً بحثية رائدة عالمياً تهدف إلى توسيع آفاق المعرفة والبحوث العملية المتقدمة. حيث تعمل فرقنا المتنوعة والمكونة من أمهر العلماء والباحثين والمهندسين ضمن بيئة مرنة تحث على الابتكار والإبداع للمساهمة في إيجاد أحدث الاكتشافات العملية والتقنيات المبتكرة. ويركز عملنا على الوصول إلى الاكتشافات التي ستجهز مجتمعاتنا للمستقبل، كما أننا ملتزمون معاً بمواصلة الابتكار والإلهام من أجل مستقبل أفضل.',NULL,'https://www.tii.ae/ar',5,2,1,'2026-06-04 10:31:53','2026-06-04 10:34:11'),(15,'Photos_ScientificResearchInnovationCenters/GT6q7Ydyv7SDpI8by42hVaFICV2qbk8wRIAYc1oZ.jpg','مدينة مصدر','Masdar city','تُعد مدينة مصدر في أبوظبي نموذجاً عالمياً رائداً للاستدامة. تحتضن المدينة منظومة متكاملة للتقنيات النظيفة وتضم منطقة حرة تحتضن أكثر من 900 شركة. وهي بمثابة \"مركز ابتكار\" (Hub) يهدف لتطوير حلول تغير المناخ، وتشتهر بتصميم \"مبنى حاضنة قطر الأعمال\" (Incubator Building) الذي يتميز بواجهات منحنية مصممة لتوفير الظل للشوارع.\r\nوباعتبارها مجتمعًا حضريًا مستدامًا رائدًا، تقف مدينة مصدر في طليعة تغيير الطريقة التي يعيش بها الناس ويعملون ويتعلمون ويقضون أوقاتهم. وبصفتها مركزًا عالميًا للأعمال والتكنولوجيا، طوّرت مدينة مصدر منظومة مزدهرة من المؤسسات العالمية الرائدة التي تعمل معًا من أجل بناء مستقبل أكثر خضرة واستدامة.\r\nتوفر منطقة مدينة مصدر الحرة بيئة سلسة لمختلف الأنشطة التجارية، كما تعزز تجمعاتها الصناعية ذات التأثير الكبير التعاون والابتكار عبر قطاعات متعددة.',NULL,'https://masdarcity.ae/',5,2,1,'2026-06-04 10:39:21','2026-06-04 10:39:21'),(16,'Photos_ScientificResearchInnovationCenters/9CvAN7qEjdAV9vWXGxktqiqNW6LWGYdFMN9ePMn7.png','المركز الوطني للبحث والتطوير','National Center for Research and Development (NCRD)','تم تأسيس المركز الوطني للبحث والتطوير في أواخر عام 2010 بهدف   تطوير القدرات العلمية في مجالات التكنولوجيا النانوية والطاقة والتكنولوجيا الحيوية وبحوث البادية وأية مجالات بحثية أخرى. ولقد أتبعت للمركز برامج التكنولوجيا النانوية والتكنولوجيا الحيوية والمياه والغذاء بالإضافة إلى مركزي بحوث الطاقة والبادية اللذيْن كانا مركزين مستقلين في السابق.',NULL,'https://www.ncrd.gov.jo/',5,1,1,'2026-06-04 10:57:56','2026-06-04 10:57:56'),(17,'Photos_ScientificResearchInnovationCenters/Kv3NcZLTjpYkvG6ZYI0vAuNoqL3BL0dnTtr3rbnw.jpg','مركز المعلومات الوطني للعلوم والتكنولوجيا','National Information Center for Science & Technology','أنشئ مركز المعلومات الوطني للعلوم والتكنولوجيا كأول مركز للمعلومات في المملكة، وهو أحد المراكز التابعة للمجلس الاعلى للعلوم والتكنلوجيا برئاسة سمو الأمير الحسن بن طلال المعظم  رئيس المجلس الأعلى للعلوم والتكنولوجيا.\r\nوجاء انشاء المركز بهدف تطوير نظام متكامل للمعلومات الوطنية وبالتعاون مع الجهات الرسمية ومؤسسات القطاع الخاص وكذلك المساعدة في بناء قاعدة معلومات علمية وبحثية بما يلبي أهداف المجلس الأعلى.',NULL,'https://www.hcst.gov.jo/ar/node/1398',5,1,1,'2026-06-04 11:14:06','2026-06-04 11:16:05'),(18,'Photos_ScientificResearchInnovationCenters/6tbucZd1NwCeUzHWkzMiEi9fF8PpsVAf2ttiopvo.png','المركز الوطني للإبداع','National Center for Innovation ( NCI )','تم إنشاء المركز الوطني للإبداع في عام 2019، كمظلة وطنية تهدف إلى خلق بيئة ريادية تنافسية من خلال تنظيم وتنسيق كافة الجهود ضمن إطار شمولي تكاملي يرفد بيئة الأعمال باتجاهات واضحة للفرص الاقتصادية واستغلالها لتعزيز المشاركة الاقتصادية ضمن معايير تتوافق مع السوق مما يؤدي إلى تحسين مستوى التنظيم في مجالات الابداع ويكفل التنسيق وضبط المدخلات والمخرجات للارتقاء ببيئة الأعمال الابداعية للوصول إلى أفضل الممارسات العالمية.',NULL,'https://www.hcst.gov.jo/ar/nci2',5,1,1,'2026-06-04 12:39:16','2026-06-04 12:39:16'),(19,'Photos_ScientificResearchInnovationCenters/xvyMBnrtmmg4XTIS0xUJw3AGtRF8avxvvzS7mouf.png','مركز الروبوتات والأنظمة الذاتية',NULL,'يمثل مركز الروبوتات والأنظمة الذاتية في الجامعة الألمانية الأردنية، التي تأسست سنة 2005، فضاءً بحثياً وتعليمياً متخصصاً في تطوير الابتكار بمجالات الروبوتات والأنظمة الذكية والمستقلة. ويسهم المركز في دعم البحوث التطبيقية وتحفيز ريادة الأعمال التقنية، فضلاً عن تعزيز حضور الأردن في مجالات الذكاء الاصطناعي والتقنيات الحديثة على المستوى الإقليمي',NULL,'https://www.gju.edu.jo',5,1,1,'2026-06-04 12:43:29','2026-06-04 12:43:29'),(20,'Photos_ScientificResearchInnovationCenters/1CWGpw8zIF50o80Yc3QFdZnRAiwbZH16Y1C1BVMo.png','المجلس الأعلى للعلوم والتكنولوجيا صندوق دعم البحث العلمي والتطوير في الصناعة',NULL,'أنشئ “المجلس الأعلى للعلوم والتكنولوجيا” في عام 1987 بهدف بناء قاعدة علمية وتكنولوجية وطنية تسهم في تحقيق الأهداف التنموية، وذلك من خلال زيادة الوعي بأهمية البحث العلمي والتطوير، وتقديم الدعم المالي المناسب له، وتوجيه النشاط العلمي والبحثي ضمن أولويات وطنية تنسجم مع التوجهات التنموية، وإنشاء مراكز متخصصة في البحث والتطوير كلما دعت الحاجة إلى ذلك ودعم الإبداع والريادة للإسهام في ترجمة الأفكار العلمية والتكنولوجية إلى منتجات وأعمال تجارية، وعقد الاتفاقيات المتعلقة بالتعاون العلمي والتكنولوجي مع الجهات المحلية والعربية والدولية، وتمثيل المملكة في الانشطة العلمية والتكنولوجية عربياً وإقليمياً ودولياً.',NULL,'https://www.irdf.jo/',5,1,1,'2026-06-04 12:49:07','2026-06-04 12:49:07'),(21,'Photos_ScientificResearchInnovationCenters/xzUb2JpdVWfRr6dx5MSc4X0uFqvPF1LaPERYWcuY.png','مركز البحرين للابتكار ونقل التكنولوجيا',NULL,'يُعدّ مركز البحرين للابتكار ونقل التكنولوجيا التابع لـ جامعة البحرين وحدة بحثية وتنموية متخصصة أُسست سنة 2010، بهدف دعم منظومة الابتكار وريادة الأعمال وتعزيز نقل المعرفة والتكنولوجيا داخل مملكة البحرين. ويعمل المركز على تحويل مخرجات البحث العلمي والأفكار الابتكارية إلى تطبيقات ومشاريع عملية تساهم في التنمية الاقتصادية والاجتماعية المستدامة، إضافة إلى تشجيع التعاون بين الجامعة والقطاعين الصناعي والتكنولوجي.',NULL,'https://www.uob.edu.bh',5,3,1,'2026-06-04 12:53:01','2026-06-04 12:53:01'),(22,'Photos_ScientificResearchInnovationCenters/1JbAjEVZdofy5Qt2HSiHBEffI5qq0lOqErB5Ei8o.png','مركز ناصر العلمي والتقني',NULL,'تُعتبر مؤسسة ناصر العلمي والتقني مؤسسة تعليمية وتدريبية متخصصة أُسست سنة 2008 في مملكة البحرين، وتهدف إلى تأهيل الشباب في المجالات التقنية والمهنية وفق أحدث المعايير التعليمية والتطبيقية. ويساهم المركز في تطوير الكفاءات الوطنية وتزويدها بالمهارات اللازمة لتلبية احتياجات سوق العمل الصناعي والتكنولوجي، بما ينسجم مع رؤية البحرين 2030 الرامية إلى تنويع الاقتصاد وتعزيز قدرات الشباب في مجالات الابتكار والتكنولوجيا.',NULL,'https://www.ncst.edu.bh/',5,3,1,'2026-06-04 12:55:31','2026-06-04 12:55:31'),(23,'Photos_ScientificResearchInnovationCenters/fw3oLHXmZjzrf4x5SaeHIna8JZtLI6r5U546huNL.png','المركز العلمي البحريني لأهداف التنمية المستدامة','null','تم افتتاح المركز العلمي البحريني لأهداف التنمية المستدامة في أغسطس من العام 2018، ويعمل المركز تحت إشراف وزارة شؤون الشباب كأول مركز علمي من نوعه على مستوى العالم لرفع مستوى الوعي حول أهداف التنمية المستدامة الـ 17 وتمكين الشباب من لعب دور فعال في إحداث تأثير إيجابي على مجتمعاتهم المحلية وبلدهم والعالم.',NULL,'https://www.mya.gov.bh/ar/bscsgds',5,3,1,'2026-06-04 12:58:04','2026-06-04 12:59:20'),(24,'Photos_ScientificResearchInnovationCenters/oOq6VfxsmMsQvwbBwhmtu59xd8WVoQy4uE1I8K9u.png','مركز الابتكار الحكومي تابع لـ هيئة المعلومات والحكومة الإلكترونية',NULL,'يعد مختبر الابتكار إحدى المبادرات المبتكرة التي أطلقتها هيئة المعلومات والحكومة الإلكترونية، والتي تهدف إلى تعزيز ثقافة الابتكار بالقطاع العام في مملكة البحرين عبر تشجيع تبني التقنيات الحديثة، تشمل ولا تقتصر على تقنيات الذكاء الاصطناعي، الرؤية الحاسوبية، سلسلة الكتل، الواقع المعزز.\r\n يهدف المركز إلى تأسيس مختبر لتحفيز وإثراء ثقافة الابتكار في القطاع الحكومي من خلال وضع منظومة متكاملة لتعزيز أنشــطة التطويــر والبحــث والابتكار واســتخدام التكنولوجيــا الحديثــة لدعــم جهــود تنميــة القطاعــات الواعــدة بالشــراكة مــع القطــاع الخــاص. يقع المركز الوطني في هيئة المعلومات والحكومة الإلكترونية.',NULL,'https://www.iga.gov.bh/category/innovation-hub',5,3,1,'2026-06-04 13:01:14','2026-06-04 13:01:14'),(25,'Photos_ScientificResearchInnovationCenters/LDFF6jxLUqnmMazbB6jykB84uWmrYnaEgFuYEAnZ.png','مختبر الابتكار  تابع لـ الجامعة الأمريكية في البحرين','Investcorp Innovation Lab','مختبر إنفستكورب للابتكار (IIL AUBH) المدعوم من American University of Bahrain هو أول مركز ابتكار جامعي في Bahrain يهدف إلى ربط الأوساط الأكاديمية بقطاع الأعمال والصناعة. ويعمل المختبر على تمكين الشركات الناشئة والمؤسسات ورواد الابتكار من خلال توفير حاضنات أعمال متقدمة، وبرامج للابتكار المؤسسي، وإتاحة الوصول إلى شبكات وخبرات عالمية.\r\n\r\nوبصفته المقر الحصري لبرنامج MIT Venture Mentoring Service في البحرين، يوفر المختبر نظامًا متكاملًا للإرشاد والتوجيه يعتمد على منهجيات مجربة عالميًا، لمساعدة المشاريع الريادية على التحقق من جدوى أفكارها، وتعزيز نموها، وتوسيع نطاق أعمالها. كما تجمع برامجه بين الرؤى المستندة إلى البحث العلمي، والتوجيه العملي، والشراكات الاستراتيجية، بما يسهم في تسريع نمو منظومة الابتكار وريادة الأعمال في المملكة والمنطقة.',NULL,'https://bh.linkedin.com/company/investcorp-innovation-lab',5,3,1,'2026-06-04 13:03:54','2026-06-04 13:03:54'),(26,'Photos_ScientificResearchInnovationCenters/PFB3igmt2zNq0Rs08X9dtYwlEQZSf0OlBzmq3zi6.png','المركز الإقليمي لتكنولوجيا المعلومات والاتصال بمملكة البحرين',NULL,'يعمل المركز الإقليمي لتكنولوجيا المعلومات والاتصال بمملكة البحرين تحت إشراف منظمة اليونسكو، وهو مركز معتمد من الفئة الثانية، إذ يستكمل الجهود التي تقوم بها منظمة اليونسكو لتحقيق أهدافها الاستراتيجية وبناء مجتمعات المعرفة.',NULL,'https://regcict.com/',5,3,1,'2026-06-04 13:33:50','2026-06-04 13:33:50'),(27,'Photos_ScientificResearchInnovationCenters/CfXtpTh4F2lV54KC90YKJQbcAAzxOsKPoQ5sYlbe.png','القطب التكنولوجي بسيدي ثابت',NULL,'يُعدّ القطب التكنولوجي بسيدي ثابت فضاءً علمياً وتكنولوجياً مخصصاً لتعزيز البحث والابتكار في مجال البيوتكنولوجيا والصناعات الحيوية. يهدف إلى ربط البحث العلمي بالقطاع الصناعي من خلال دعم المشاريع المبتكرة، وتشجيع نقل التكنولوجيا، واحتضان المؤسسات الناشئة في مجالات الصحة، الفلاحة، والصناعات الدوائية. كما يساهم في تطوير اقتصاد المعرفة وتعزيز القدرة التنافسية للقطاع الصناعي في تونس.\r\nسنة التأسيس: 1990',NULL,'https://www.biotechpole.tn/ar/',5,4,1,'2026-06-04 13:35:15','2026-06-04 13:35:15'),(28,'Photos_ScientificResearchInnovationCenters/EEQEPqlLzZHLBjJlcDIF2hvoLzDlGkuAAvSQQDF5.png','مركز البيوتكنولوجيا بصفاقس',NULL,'يُمثلّ مركز البيو تكنولوجيا بصفاقس مؤسسة عمومية للبحث العلمي والتطوير التكنولوجي أُسست سنة 1983، وتخضع لإشراف وزارة التعليم العالي والبحث العلمي بالجمهورية التونسية. يختص المركز في مجالات البيو تكنولوجيا والابتكار العلمي، ويعمل على تطوير الأبحاث التطبيقية وربطها بالقطاعين الصناعي والاقتصادي، خاصة في مجالات الصحة، الفلاحة، البيئة، والصناعات الحيوية. كما يساهم المركز في نقل التكنولوجيا، دعم الابتكار، وتكوين الباحثين والكفاءات العلمية المتخصصة.',NULL,'http://www.cbs.rnrt.tn/',5,4,1,'2026-06-04 13:36:22','2026-06-04 13:36:22'),(29,'Photos_ScientificResearchInnovationCenters/SIEfg3uWdggV5lEalzjYD5LPzirnBSNMPaOfWY2m.jpg','مركز بحوث وتكنولوجيات المياه','CERTE','يعتبر مركز بحوث وتكنولوجيات المياه مؤسسة عمومية للبحث العلمي والتطوير التكنولوجي أُسست سنة 2005 بالجمهورية التونسية، وتخضع لإشراف وزارة التعليم العالي والبحث العلمي. يختص المركز بتطوير الأبحاث والتقنيات المرتبطة بقطاع المياه، خاصة في مجالات معالجة المياه، تحلية المياه، إعادة التدوير، والابتكار البيئي، كما يساهم في دعم التنمية المستدامة وتطوير الحلول التكنولوجية لفائدة القطاعين الصناعي والاقتصادي.',NULL,'http://www.certe.rnrt.tn/',5,4,1,'2026-06-04 13:37:17','2026-06-11 13:59:05'),(30,'Photos_ScientificResearchInnovationCenters/IkEWuMKZy8FW4WOqngpnP3anFla67FO97GQ31RU4.png','القطب التكنولوجي بصفاقس',NULL,'يُمثل القطب التكنولوجي بصفاقس فضاءً علمياً وتكنولوجياً يهدف إلى تعزيز الابتكار وربط البحث العلمي بالقطاع الصناعي والاقتصادي. أُسس سنة 2006، ويهتم بدعم المشاريع التكنولوجية والبحثية، وتشجيع ريادة الأعمال، وتطوير مجالات التكنولوجيا الحديثة والصناعة الرقمية، بما يساهم في دعم التنمية الصناعية والاقتصاد القائم على المعرفة في تونس.',NULL,'https://www.tpsfaxe.tn/?utm_source=chatgpt.com',5,4,1,'2026-06-04 13:38:21','2026-06-04 13:38:21'),(31,'Photos_ScientificResearchInnovationCenters/W5nJgRzp5usBtQR6mnXtFdNBNwjN1WgAqTMlq70B.png','مركز البحث في الرقميات بصفاقس','Digital Research Center of Sfax','يمثل مركز البحث الرقمي بصفاقس مؤسسة بحثية متخصصة في مجالات التكنولوجيا الرقمية والابتكار بالجمهورية التونسية. أُسس سنة 2012، ويهتم بتطوير الأبحاث التطبيقية في الذكاء الاصطناعي، إنترنت الأشياء، الأمن السيبراني، وتحليل البيانات. ويساهم المركز في دعم التحول الرقمي وربط البحث العلمي بالقطاع الصناعي والتكنولوجي من خلال تطوير حلول رقمية مبتكرة تخدم التنمية الاقتصادية والصناعية.',NULL,'https://www.crns.rnrt.tn/',5,4,1,'2026-06-04 13:40:21','2026-06-04 13:40:21'),(32,'Photos_ScientificResearchInnovationCenters/rbXjVoXQOIAsXTAWArqGbaS8o9lIhYmcFpg8M4jY.png','المعهد الوطني للبحث الزراعي (في التكنولوجيا الزراعية',NULL,'المعهد الوطني للبحث الزراعي بتونس\r\n\r\nيُعدّ من أقدم المؤسسات البحثية في تونس، ويختص في البحث الزراعي وتطوير التقنيات الفلاحية وتحسين الإنتاج الزراعي. كما يعمل على دعم الابتكار في مجالات الزراعة الذكية والصناعات الغذائية، بما يساهم في تعزيز الأمن الغذائي والتنمية المستدامة.\r\nسنة التأسيس: 1911.',NULL,'http://www.inrat.agrinet.tn/',5,4,1,'2026-06-04 13:42:37','2026-06-04 13:42:37'),(33,'Photos_ScientificResearchInnovationCenters/mAQdZx8QxgtscfRY0al2hwBLEfIYNNFmnHbcx39R.png','القطب التكنولوجي ببرج السدرية','Technopole Borj Cédria','القطب التكنولوجي ببرج السدرية\r\n\r\nفضاء بحث وتطوير يجمع بين مراكز علمية ومخابر متخصصة في مجالات الطاقة والبيئة والمواد. يهدف إلى ربط البحث العلمي بالصناعة ودعم الابتكار التكنولوجي وتطوير حلول مستدامة في مجالات الطاقة النظيفة والصناعة الخضراء.\r\nسنة التأسيس: 2000',NULL,'https://www.tbs.rnrt.tn/',5,4,1,'2026-06-04 13:44:31','2026-06-04 13:44:31'),(34,'Photos_ScientificResearchInnovationCenters/yDAyQybB5eOQSlz2ohC993YcqNNKgAgs5Rdhjns8.png','مركز البحوث وتكنولوجيات الطاقة',NULL,'مركز البحوث وتكنولوجيات الطاقة\r\nمركز بحثي يختص في الطاقات المتجددة وكفاءة الطاقة والتقنيات الطاقية الحديثة.\r\n يساهم في تطوير حلول تكنولوجية تدعم الصناعة وتقلل من استهلاك الطاقة، مع تعزيز الابتكار في مجال التحول الطاقي والتنمية المستدامة.\r\nسنة التأسيس: 1989',NULL,'http://www.crten.rnrt.tn/',5,4,1,'2026-06-04 13:45:40','2026-06-04 13:45:40'),(35,'Photos_ScientificResearchInnovationCenters/bH5LORKSFMQ5es2A8hNrGWy1NVgkAouzGvXfwBPa.jpg','المركز الوطني للبحوث في علوم المواد',NULL,'المركز الوطني للبحوث في علوم المواد هو مؤسسة بحثية تونسية تُعنى بتطوير علوم المواد وهندستها لخدمة قطاعات الصناعة والطاقة والبيئة.\r\n يشكّل أحد المراكز الوطنية المتخصصة التابعة لوزارة التعليم العالي والبحث العلمي، ويُعدّ منصة أساسية للتعاون بين الجامعات والقطاع الصناعي في مجال تطوير المواد المتقدمة',NULL,'http://www.cnrsm.rnrt.tn/',5,4,1,'2026-06-04 13:47:01','2026-06-04 13:47:01'),(36,'Photos_ScientificResearchInnovationCenters/1w3gsy6I0pZdXhdtZMgd02V8JT8VzxPGyA1bOVzi.png','المركز الوطني الجامعي للتوثيق العلمي والتقني',NULL,'المركز الوطني الجامعي للتوثيق العلمي والتقني في تونس هو مؤسسة عمومية تابعة لوزارة التعليم العالي والبحث العلمي، تأسس سنة 1978، ويهتم بجمع وتنظيم وتوفير المعلومات والوثائق العلمية والتقنية لفائدة الباحثين والجامعات ومراكز البحث، كما يتيح قواعد بيانات ومصادر علمية ويساعد على نشر المعرفة وتسهيل الوصول إلى الأبحاث والدراسات لدعم البحث العلمي في البلاد.',NULL,'https://www.cnudst.rnrt.tn/',5,4,1,'2026-06-04 13:48:04','2026-06-04 13:48:04'),(37,'Photos_ScientificResearchInnovationCenters/4IpkVtU0JleHElLGDyl86i3o3XeY09s1sN4wSPXt.jpg','المجلس الوطني للبحث العلمي والتكنولوجيات',NULL,'يُعدّ المجلس الوطني للبحث العلمي والتكنولوجيات الهيئة الوطنية العليا المشرفة على منظومة البحث العلمي والتطوير التكنولوجي في الجزائر، وقد تأسس سنة 1998 بهدف وضع سياسات البحث العلمي، وتنسيق وتمويل المشاريع البحثية، ودعم الابتكار وربط البحث العلمي بالتنمية الصناعية والاقتصادية.',NULL,'https://www.cnrst.dz/',5,5,1,'2026-06-04 13:49:02','2026-06-04 13:49:02'),(38,'Photos_ScientificResearchInnovationCenters/Mnkuf0w4P0N0b6udvYzuFYIYPjz1lEYuxMkKYIHW.png','مركز تنمية التكنولوجيات المتطورة','cdta','يُعتبر مركز تنمية التكنولوجيات المتطورة مركزاً وطنياً للبحث والتطوير أُسس سنة 1988، ويختص في مجالات التكنولوجيات المتقدمة مثل الإلكترونيات الدقيقة، النانو تكنولوجيا، الأنظمة الذكية، والابتكار الصناعي، كما يساهم في تطوير حلول تكنولوجية تدعم الصناعة الجزائرية والتحول الرقمي',NULL,'https://www.cdta.dz/',5,5,1,'2026-06-04 13:49:59','2026-06-10 12:20:44'),(39,'Photos_ScientificResearchInnovationCenters/Qdg5W0g5LoljXInxiTSAiC5NYvOYkkSzAiRXbM2S.png','مركز البحث العلمي والتقني حول المناطق القاحلة',NULL,'يُعدّ مركز البحث العلمي والتقني حول المناطق القاحلة مؤسسة بحثية وطنية أُسست سنة 1992، وتهتم بالبحث العلمي في المناطق الصحراوية وشبه الجافة، من خلال تطوير الدراسات المتعلقة بالزراعة الصحراوية، وإدارة الموارد الطبيعية، ومكافحة التصحر، ودعم التنمية المستدامة في البيئات القاحلة.',NULL,'https://crstra.dz/ar',5,5,1,'2026-06-04 13:52:01','2026-06-04 13:52:01'),(40,'Photos_ScientificResearchInnovationCenters/0oIhQDsBWnTZerpcyC0qJU2HgndphqVbC3KcXeV3.png','مركز دعم التكنولوجيا والابتكار','Technology and Innovation Support Center','أنشأ مركز دعم التكنولوجيا و الإبتكار بجامعة عبد الحميد مهري قسنطينة 2 في إطار إتفاقية الشراكة و التعاون بين الجامعة و المعهد الوطني الجزائري للملكية الصناعية الموقعة يوم 17 جانفي 2021.\r\n\r\nوتحدد هذه الشراكة الشروط و الأحكام الخاصة بإنشاء المركز من أجل ضمان خدمات تتلاءم مع إحتياجات المستخدمين من أساتذة و  وباحثين و طلبة في مجال المعلومات التكنولوجية مع ضمان حماية ملكيتهم الصناعية.\r\n\r\nومن أهداف المركز:\r\n\r\nتفعيل دور الجامعة في تشجيع وتنمية القدرات الإبداعية والإبتكارية.\r\nالحث على تجسيد نتائج البحث العلمي والعمل الابداعي بالجامعة على أرض الواقع.\r\nتهيئة بيئة تدعم الابتكار والتطور التكنولوجي.',NULL,'https://www.univ-constantine2.dz/cati/?lang=ar',5,5,1,'2026-06-04 13:56:41','2026-06-10 12:06:03'),(41,'Photos_ScientificResearchInnovationCenters/kkDDgTSUy7CH3TGzhOtATsTLkSRRvt9YFxxAzHYN.png','المديرية العامة للبحث العلمي والتطوير التكنولوجي',NULL,'تُعتبر المديرية العامة للبحث العلمي والتطوير التكنولوجي الجهة الحكومية المشرفة على تنظيم وتطوير منظومة البحث العلمي في الجزائر، وقد أُنشئت سنة 2008 بهدف تنسيق برامج البحث، والإشراف على المراكز البحثية الوطنية، وتمويل المشاريع العلمية والتكنولوجية الكبرى.',NULL,'https://www.dgrsdt.dz/',5,5,1,'2026-06-04 13:58:22','2026-06-04 13:58:22'),(42,'Photos_ScientificResearchInnovationCenters/xbUiYMogDyoRlKJ0xwHiisdBqkBIfZzJbBkWxws4.jpg','مركز البحث في التكنولوجيات الصناعية',NULL,'يُعتبر مركزاً وطنياً متخصصاً في البحث والتطوير في مجال التكنولوجيات الصناعية، ويعمل على تطوير الحلول التقنية المرتبطة بالتصنيع، المواد، الروبوتات، الأنظمة الذكية، واللحام الصناعي. كما يساهم في نقل التكنولوجيا نحو المؤسسات الصناعية الجزائرية ودعم الابتكار الصناعي',NULL,'https://www.crti.dz/',5,5,1,'2026-06-04 14:01:38','2026-06-04 14:01:38'),(43,'Photos_ScientificResearchInnovationCenters/bk6ACyAgBPZcdDpBQAoex8gvQ4Lfh1aQRAj9iPYk.png','مركز البحث في تكنولوجيا نصف النواقل الطاقوية','crtse','يُعتبر مركز البحث في تكنولوجيا نصف النواقل الطاقوية مركزاً بحثياً وطنياً تأسس سنة 1992، ويعمل على تطوير تكنولوجيا أشباه الموصلات والخلايا الشمسية والمواد الإلكترونية لدعم الابتكار والصناعة الطاقوية في الجزائر.',NULL,'https://crtse.dz/',5,5,1,'2026-06-04 14:02:51','2026-06-10 12:16:13'),(44,'Photos_ScientificResearchInnovationCenters/BQnMg9N35pSaLmGCd6TJc2berqrvRQEYyyjZ1FBk.png','مركز الدراسات والبحوث العلمية',NULL,'يُعدّ مركز الدراسات والبحوث العلمية بجيبوتي المؤسسة الوطنية الرئيسية للبحث العلمي والتكنولوجي في جمهورية جيبوتي، وقد تأسس سنة 1979 بهدف تطوير البحث العلمي، وتعزيز الابتكار، ودعم الدراسات المرتبطة بالتنمية المستدامة والموارد الطبيعية والتكنولوجيا الحديثة.',NULL,'https://www.cerd.dj/',5,6,1,'2026-06-04 14:04:45','2026-06-04 14:04:45'),(46,'Photos_ScientificResearchInnovationCenters/wvQnL7AhGFzWfl5Ff8Ypu50K0UiBhiCcuwG1Z73X.png','مركز التكنولوجيا والابتكار من أجل التنمية',NULL,'يُعتبر مركز التكنولوجيا والابتكار من أجل التنمية أول حاضنة ومركز وطني للابتكار التكنولوجي في جيبوتي، وقد أُطلق سنة 2017 بهدف دعم ريادة الأعمال والابتكار في مجالات التكنولوجيا الرقمية، الطاقات المتجددة، والخدمات الذكية، مع تشجيع المشاريع ذات الأثر الاقتصادي والتنموي.',NULL,'https://ctid-djibouti.org/',5,6,1,'2026-06-04 14:09:28','2026-06-04 14:09:28'),(47,'Photos_ScientificResearchInnovationCenters/zHDnEUbGjnu4F4wXqiKxnWkQTrTzdisCMDgyeXVX.png','مرصد البحث والبيئة والمناخ',NULL,'يُعدّ مرصد البحث والبيئة والمناخ منصة علمية وبحثية متخصصة أُنشئت حديثاً لدعم البحث العلمي في مجالات البيئة والمناخ والصحة والموارد الطبيعية، كما يعمل على تطوير الدراسات العلمية المتعلقة بالتغيرات المناخية والتنمية المستدامة في جيبوتي والمنطقة.',NULL,'https://orrec.net/lorrec',5,6,1,'2026-06-04 14:10:44','2026-06-04 14:10:44'),(49,'Photos_ScientificResearchInnovationCenters/icPTuTTbuotQtZEfFeu01CDKKs4euACzokkJnnhO.jpg','مدينة الملك عبد العزيز للعلوم والتقنية','kacst','تُعدّ مدينة الملك عبد العزيز للعلوم والتقنية المؤسسة الوطنية الرئيسية للبحث العلمي والتطوير التكنولوجي في المملكة العربية السعودية، وقد تأسست سنة 1977 بهدف دعم الابتكار، وتطوير التكنولوجيا، وتمويل الأبحاث العلمية، ونقل المعرفة لدعم التنمية الصناعية والاقتصاد المعرفي.',NULL,'https://www.kacst.gov.sa/',5,7,1,'2026-06-04 14:13:02','2026-06-10 12:14:32'),(50,'Photos_ScientificResearchInnovationCenters/UhYAf5AstVW7S2ucBv809f224tpim5LW5TYFR0Z9.png','مدينة الملك عبدا لله للطاقة الذرية والمتجددة',NULL,'تعتبر مدينة الملك عبد الله للطاقة الذرية والمتجددة مركزاً وطنياً أُسس سنة 2010، ويهتم بتطوير أبحاث الطاقة المتجددة والطاقة النووية، ودعم الابتكار في مجال الطاقة المستدامة والتقنيات الحديثة.',NULL,'https://www.energy.gov.sa/',5,7,1,'2026-06-04 14:14:45','2026-06-04 14:14:45'),(51,'Photos_ScientificResearchInnovationCenters/TaXsCfhuB1t7tTWrBbMZtlAWbUkd1REfF0wpzxXq.jpg','مركز الثورة الصناعية الرابعة',NULL,'يُعدّ مركز الثورة الصناعية الرابعة السعودية مركزاً وطنياً أُطلق سنة 2021 بالتعاون مع المنتدى الاقتصادي العالمي، ويعمل على تطوير تقنيات الذكاء الاصطناعي، وإنترنت الأشياء، والتحول الرقمي، ودعم الصناعة 4.0 في المملكة.',NULL,'https://c4irsaudiarabia.org/',5,7,1,'2026-06-04 14:16:09','2026-06-04 14:16:09'),(52,'Photos_ScientificResearchInnovationCenters/cFla2HQTCIhQTCOFKgL1KmJnR29VtwfTRlmrjCBh.png','معهد الابتكار التقني',NULL,'يُعتبر معهد الابتكار التقني مركزاً بحثياً متقدماً في مجالات الذكاء الاصطناعي والروبوتات والتقنيات المستقبلية، وقد أُسس سنة 2020 بهدف دعم الابتكار الصناعي والتكنولوجي في إطار رؤية السعودية 2030.',NULL,'https://tii.sa/',5,7,1,'2026-06-04 14:18:33','2026-06-04 14:18:33'),(53,'Photos_ScientificResearchInnovationCenters/591KmNndylomeJAYmE7KvNjWiiXhLT6gZRsi2BPg.png','معهد بحوث البترول والطاقة',NULL,'يعدّ معهد بحوث البترول والطاقة مركزاً بحثياً متخصصاً في أبحاث النفط والطاقة والبتروكيماويات، ويعمل على تطوير تقنيات صناعية متقدمة لدعم قطاع الطاقة في المملكة، وقد تأسس سنة 1975.',NULL,'https://www.kfupm.edu.sa/',5,7,1,'2026-06-04 14:20:08','2026-06-04 14:20:08'),(54,'Photos_ScientificResearchInnovationCenters/CoaBsjMYAS8UdeQX48kEwNcmEf6wlTTuNKPyb0FS.png','المركز القومي للبحوث','National Centre for Research Sudan','يُعد من أهم المؤسسات البحثية الحكومية في السودان، ويعمل تحت إشراف وزارة التعليم العالي والبحث العلمي. يهتم بإجراء البحوث في مجالات العلوم الأساسية، البيئة، الصحة، والتكنولوجيا، إضافة إلى دعم الابتكار العلمي وخدمة التنمية الوطنية.',NULL,'https://ncr.gov.sd/',5,8,1,'2026-06-04 14:21:26','2026-06-04 14:21:26'),(55,'Photos_ScientificResearchInnovationCenters/AgdFlGdJ8Q40ylwSmyiE2GGHAaadiGGzpGzsh8PJ.jpg','الهيئة السودانية للطاقة الذرية','Sudanese Atomic Energy Commission','مؤسسة وطنية متخصصة في البحث والتطوير في مجال الطاقة النووية وتطبيقاتها السلمية، خاصة في الطب النووي، الزراعة، والصناعة، إضافة إلى الأبحاث المتعلقة بالإشعاع والسلامة النووية.',NULL,'http://www.saec.gov.sd/',5,8,1,'2026-06-04 14:22:39','2026-06-04 14:22:39'),(56,'Photos_ScientificResearchInnovationCenters/W5gDijjD9bciurPIuuE7b7PbyUOpcZ39ZK6hZjUm.jpg','هيئة البحوث الزراعية','Agricultural Research Corporation Sudan','تُعتبر أكبر مؤسسة بحثية زراعية في السودان، وتعمل على تطوير المحاصيل الزراعية، تحسين الإنتاج، مقاومة الجفاف، ودعم الأمن الغذائي من خلال الابتكار في المجال الزراعي.',NULL,'https://arc.gov.sd/',5,8,1,'2026-06-04 14:24:25','2026-06-04 14:24:25'),(57,'Photos_ScientificResearchInnovationCenters/14dYs78oRUclYXkGqWNoOICYiJVJ7dRn7MRR60fA.png','مراكز البحوث والاستشارات الصناعية','Industrial Research and Consultancy Centre Sudan','أنشئ مركز البحوث والاستشارات الصناعية في فبراير من العام 1965م بدعم ومساعدة من منظمة الأمم المتحدة للتنمية الصناعية  (يونيدو) كمؤسسة قُطريّة بنيت على أسس غير تجارية، ليقدم خدماته الاستشاريــــة والبحثية والتطبيقية في استغلال المواد والموارد للقطاع الصناعي والقطاع الخدمي، بشقيه العام والخاص، تحت مسمى هيئة البحوث الصناعية، ثم معهد البحوث والاستشارات الصناعية.',NULL,'https://ircc.gov.sd/',5,8,1,'2026-06-04 14:28:50','2026-06-04 14:28:50'),(58,'Photos_ScientificResearchInnovationCenters/aJLp7HPbSkVVcbsjc1FvNFC5Ql5pbjd2Nr6flMWW.png','الهيئة العامة للطاقة الذرية السورية','Atomic Energy Commission of Syria','أحدثت هيئة الطاقة الذرية في الجمهورية العربية السورية في عام 1976 وبدأت ممارسة نشاطها المؤسساتي منذ عام 1979 وهي جهة حكومية مسؤولة عن شؤون الطاقة الذرية وتطبيقاتها في المجالات السلمية. \r\nوتعمل على وضع الأسس والقواعد الناظمة لشؤون هذه الاستخدامات في الأراضي السورية، وتعد هيئة الطاقة الذرية السورية السلطة الرقابية المتخصصة التي أنيطت بها مهام الإحاطة بالأنشطة الإشعاعية وتتولى مسؤولية مراقبة كافة الممارسات الإشعاعية في القطر ومراقبة واردات وصادرات القطر في المنافذ الحدودية للتأكد من خلوها من الإشعاع.',NULL,'http://www.aec.org.sy/',5,9,1,'2026-06-04 14:31:48','2026-06-04 14:31:48'),(59,'Photos_ScientificResearchInnovationCenters/RaInXAGz5kXOOJnCHPGQNJcvZzmGlWS7HAFoAxxG.jpg','الهيئة العامة للبحوث العلمية الزراعية','General Commission for Scientific Agricultural Research Syria','أُحدثت الهيئة عام 2000 كهيئة عامة ذات طابع علمي، وتتبع لوزارة الزراعة والإصلاح الزراعي، ومقرها الرئيسي في دمشق. وفي عام 2012 أعيد تنظيمها وإحداثها بموجب المرسوم التشريعي رقم 24 لعام 2012.\r\nوتُعد الهيئة الجهة الوطنية الرئيسية المسؤولة عن البحث العلمي الزراعي في سوريا، وتهدف إلى تطوير القطاع الزراعي من خلال إجراء البحوث والدراسات العلمية في مجالات الإنتاج النباتي والحيواني، والموارد الطبيعية، والتقانات الحيوية، وتحسين الأصناف الزراعية، ومكافحة الآفات والأمراض الزراعية. كما تعمل على نقل نتائج البحوث إلى المزارعين والجهات المعنية للمساهمة في تحقيق التنمية الزراعية المستدامة وتعزيز الأمن الغذائي',NULL,'https://gcsar.gov.sy/',5,9,1,'2026-06-04 14:36:34','2026-06-04 14:36:34'),(61,'Photos_ScientificResearchInnovationCenters/HMiuAogdjVJer6ZH8k7ifCuWiODrgrnKVzLJTZnn.png','المركز الوطني الصومالي للذكاء الاصطناعي',NULL,'تُعدّ المركز الوطني الصومالي للذكاء الاصطناعي مؤسسة حكومية حديثة \r\n التأسيس أُنشئت في أكتوبر 2024، وتهدف إلى تطوير وتعزيز البحث العلمي والابتكار في مجال الذكاء الاصطناعي داخل الصومال. ويسعى المركز إلى ترسيخ مكانة الصومال كمركز إقليمي رائد في مجال الذكاء الاصطناعي المسؤول والأخلاقي، من خلال دعم التعليم والبحث العلمي والتطبيقات الصناعية المرتبطة بالتقنيات الذكية.\r\nويعمل المركز على تشجيع تطوير حلول مبتكرة تعتمد على الذكاء الاصطناعي للمساهمة في مواجهة التحديات الوطنية وتحقيق التنمية الاجتماعية والاقتصادية، إضافة إلى دعم بناء القدرات الوطنية في المجالات الرقمية والتكنولوجية الحديثة، وتعزيز التعاون بين المؤسسات الحكومية والجامعات والقطاع الخاص في مجالات التحول الرقمي والابتكار التقني.',NULL,'https://snaic.gov.so/',5,10,1,'2026-06-04 14:43:14','2026-06-04 14:43:14'),(62,'Photos_ScientificResearchInnovationCenters/qzwVZjquCcQwzskr4NL2Id5VJM8hNMVjZyf8izzb.jpg','مركز البحوث والتنمية الصومالي',NULL,'يُعد مركز البحوث والتنمية الصومالي من المؤسسات العلمية التي تهدف إلى دعم الدراسات والبحوث المتعلقة بالتنمية والابتكار وبناء القدرات العلمية في الصومال، مع التركيز على قضايا التعليم والتنمية المستدامة والتكنولوجيا.',NULL,'https://www.srdi.so/',5,10,1,'2026-06-04 14:44:24','2026-06-04 14:44:24'),(63,'Photos_ScientificResearchInnovationCenters/Ri241y5zpwh6SwkAHg7Q9gcmbkR2Ry4ltFPSIOE6.png','مركز حديد للابتكار',NULL,'يُعدّ مركز حديد للابتكارمبادرة حديثة أُطلقت في الصومال خلال يناير 2024 بهدف تمكين الشباب الصومالي من خلال الابتكار والتكنولوجيا وريادة الأعمال. وقد أسسه مجموعة من رواد الأعمال الصوماليين سعياً إلى تعزيز المهارات التقنية والإبداعية وربط الشباب بمتطلبات الاقتصاد الرقمي العالمي.\r\nويركز المركز على توفير برامج التدريب والبحث والتوعية في مجالات التكنولوجيا والابتكار الاجتماعي وريادة الأعمال، مع العمل على تطوير بيئة تعليمية حديثة مجهزة بالبنية التحتية والتقنيات المتقدمة.\r\n كما يسعى المركز إلى إعداد كفاءات تقنية قادرة على الاندماج في سوق العمل العالمي والمساهمة في التنمية الاقتصادية والاجتماعية داخل الصومال، إضافة إلى دعم الحلول المبتكرة لمعالجة التحديات المجتمعية والتنموية.',NULL,'https://hadiid.so/hadiid-innovation-center/',5,10,1,'2026-06-04 14:46:01','2026-06-04 14:46:01'),(64,'Photos_ScientificResearchInnovationCenters/pfkkjSG2V6QHaXvL9dm7OFgtLSMPh1yWrZ07OKr3.png','مركز تكنولوجيا الطاقة والطاقات المتجددة',NULL,'يعتبر مركز تكنولوجيا الطاقة والطاقات المتجددة أحد الصروح العلمية في الجامعة التكنولوجية، وهو يهدف إلى المساهمة في دعم النهضة العلمية والتنموية في البلد وذلك من خلال إقامة وانجاز البحوث والمشاريع الريادية في مجال الطاقة المتجددة التي تصب في مصلحة الاقتصاد الوطني وبما يحقق أهداف خطط التنمية، كما يهدف المركز إلى المساهمة في نشر ثقافة استخدام الطاقة المتجددة للحصول على طاقة نظيفة وصديقة للبيئة من خلال التوعية بمدى فائدة منظومات الطاقة الشمسية ومنظومات طاقة الرياح في الحفاظ على البيئة من التلوث.',NULL,'https://www.uotechnology.edu.iq/eretc/',5,11,1,'2026-06-05 10:04:53','2026-06-05 10:04:53'),(65,'Photos_ScientificResearchInnovationCenters/fbswWpTCdhI4nP7U13psUBeqzyK890T07aEnBzPB.png','مركز بحوث الطاقة المتجددة',NULL,'تأسس مركز بحوث الطاقة المتجددة سنة 2012، بموجب موافقة وزارة التعليم العالي والبحث العلمي (العدد ب ت 3/6396 في 19/6/2012) والأمر الجامعي المرقم (7647 في 8/7/2012) والصادر عن جامعة الانبار. ويتكون المركز من ثلاثة أقسام هندسية رئيسية وهي: قسم تكنولوجيا الطاقة المتجددة، قسم أنظمة السيطرة والاتصالات، وقسم أنظمة القدرة الكهربائية. ومنذ إنشائه حددت للمركز مجموعة من الأهداف والتي تمثل الرؤية الأساسية والهدف من وجوده وهي على النحو التالي:\r\n* رفد مشاريع توليد الطاقة بالبحوث والدراسات التطبيقية وبناء النماذج العملية في مجال الطاقة التقليدية والمتجددة بمختلف انواعها.\r\n* الاشتراك الفعلي والإشراف الفني والاستشاري في تنفيذ المشاريع العملية الخاصة بتوليد الطاقة.\r\n* التواصل العلمي مع المراكز البحثية المحلية والدولية خدمة للعمل البحثي بمجال تخصصات المركز.',NULL,'https://rercenter.uoanbar.edu.iq/',5,11,1,'2026-06-05 10:05:50','2026-06-05 10:05:50'),(66,'Photos_ScientificResearchInnovationCenters/Phupqcb3MUVViYYfWUK1UGF9wETDe6TPxQLrxXMU.png','مركز ابحاث البيئة والطاقة المتجددة',NULL,'تأسس مركز كربلاء للدراسات والبحوث في العام 2013م، وهو من المؤسسات العلمية الرائدة في العتبة الحسينية المقدسة.\r\n    وجاءت فكرة تأسيسه من قبل الأمانة العامة للعتبة الحسينية ولفيف من السادة الأكاديميين في مدينة كربلاء المقدسة.',NULL,'https://www.c-karbala.com/',5,11,1,'2026-06-05 10:06:36','2026-06-05 10:06:36'),(67,'Photos_ScientificResearchInnovationCenters/QY2bSrfToU6G6TEDXjfl90JreuASzaceardZ2yMv.png','مركز بحوث النهرين للطاقة المتجددة',NULL,'ُسس مركز الطاقة المتجددة في جامعة النهرين ليكون مؤسسة أكاديمية وبحثية متخصصة في مجال الطاقات البديلة، ويُعد مرجعًا علميًا في تطوير وتطبيق تقنيات الطاقة النظيفة والمستدامة ويتضمن المركز ثلاث اقسام رئيسية هي:\r\nقسم طاقة الكتلة الحيوية  \r\n قسم طاقة البحوث الشمسية\r\nقسم طاقة الرياح',NULL,'https://ner.c.nahrainuniv.edu.iq/',5,11,1,'2026-06-05 10:07:29','2026-06-05 10:07:29'),(68,'Photos_ScientificResearchInnovationCenters/9tcABWyZsRjJiGODFhuPqQ2STLdqAVj3JAugHyFO.png','مركز البحث والتاهيل المعلوماتي',NULL,'تعد تقنيات المعلومات عاملا رئيسا في تشكيل مستقبل دول العالم المعاصر واحد اهم ركائز التطور والتقدم العلمي ونقل المجتمعات النامية الى مجتمعات متقدمة.\r\nمن هذا المنطلق فان جامعة الكوفة تولي مجال تقنيات المعلومات اهتماما ودعما كبيرا. تأسس مركز الحاسبة الالكترونية في عام 1989م واستمر في عطائه ورفده للجامعة بكافة الخدمات الالكترونية لمدة اكثر من عقدين من الزمان لتتوج جهود الجامعة بتأسيس مركز البحث والتأهيل المعلوماتي في عام 2010م الذي ضم خدمات مركز الحاسبة الالكترونية ضمن عمله واضاف البعد الاكاديمي اليه، ليساهم في دعم مسار الجامعة المتصاعد في خدمة الطالب والمجتمع.\r\nتاريخ التأسيس:\r\nاستحصلت موافقة وزارة التعليم العالي والبحث العلمي بتأسيس مركز البحث والتأهيل المعلوماتي وفقا لكتاب دائرة البحث والتطوير في الوزارة ذي العدد ب ت /580 والمؤرخ في 24 كانون الثاني 2010.',NULL,'https://itrdc.uokufa.edu.iq/',5,11,1,'2026-06-05 10:08:27','2026-06-05 10:08:27'),(69,'Photos_ScientificResearchInnovationCenters/C8i6HNPvhlxlRg67tv9Ez0Quqd8kPIaZTarudboQ.png','مركز ابحاث النانو تكنولوجي والمواد المتقدمة',NULL,'يُعد مركز أبحاث النانو تكنولوجي والمواد المتقدمة أحد المراكز البحثية المتخصصة داخل الجامعة التكنولوجية في بغداد، ويهتم بإجراء البحوث التطبيقية في مجالات تقنية النانو، وعلوم المواد المتقدمة، والليزر، والتطبيقات الهندسية الحديثة.\r\nتم تأسيس المركز بشكل رسمي عام2009 ضمن هيكل الجامعة التكنولوجية.',NULL,'https://uotechnology.edu.iq/NTRC/',5,11,1,'2026-06-05 10:10:31','2026-06-05 10:10:31'),(70,'Photos_ScientificResearchInnovationCenters/zZrXUjYv0rlYmi1gOL7XAN0gBHuhzgK2KJh8TZFW.png','مركز أبحاث الطاقة المستدامة','Sustainable Energy Research Center','تأسس مركز أبحاث الطاقة المستدامة في أغسطس 2017، ويُعنى بإجراء البحوث والدراسات في المجالات المرتبطة بالطاقة المستدامة، بما في ذلك إنتاج الطاقة، ومصادر الطاقة المتجددة، وسياسات الطاقة، وكفاءة الطاقة وإدارتها، وتحويل الطاقة. كما يعمل المركز كحلقة وصل بين الباحثين في مختلف التخصصات المتعلقة بالطاقة المستدامة والقطاع الصناعي، بما يسهم في تعزيز التعاون بين البحث العلمي والتطبيقات العملية.',NULL,'https://www.squ.edu.om/',5,12,1,'2026-06-05 10:16:32','2026-06-05 10:16:32'),(71,'Photos_ScientificResearchInnovationCenters/AtrjS6EmrBrbbvwKqk17TyXHCN1K5zCyLTsVIl1v.jpg','مركز الابتكار ونقل التكنولوجيا والاستشارات','Center for Innovation, Technology Transfer and Consulting','يهدف مركز الابتكار ونقل التكنولوجيا والاستشارات إلى تعزيز مكانة الجامعة العربية المفتوحة كجامعة رائدة في مجالات الابتكار ​والاستدامة البيئية وريادة الأعمال من خلال نقل التكنولوجيا وتطوير الأبحاث إلى حلول قابلة للتطبيق. يعتمد المركز على تعزيز القدرات الابتكارية وتنمية المهارات العملية للطلبة وأعضاء هيئة التدريس والباحثين والمجتمع، بالإضافة إلى دعم ريادة الأعمال وتحويل الابتكارات إلى مشاريع ذات جدوى اقتصادية تخدم السوق المحلي والإقليمي. وتوفير منصة لنقل الخبرات الاكاديمية لقطاع الاعمال والمجتمع من خلال تقديم الاستشارات.',NULL,'https://www.aou.edu.om/',5,12,1,'2026-06-05 10:17:22','2026-06-09 11:33:06'),(72,'Photos_ScientificResearchInnovationCenters/LhRi0rA10081C2AjroQJwt4uzeYVHEMFxE8n0XvT.png','أكاديمية الابتكار الصناعي','Industrial Innovation Academy','تعمل أكاديمية الابتكار الصناعي على تطوير وتنفيذ برامج مبتكرة تسهم في تعزيز نسبة المحتوى المحلي والابتكار الصناعي وبناء القدرات الوطنية. تعمل هذه البرامج من خلال تقديم خدمات استشارية وإعداد الدراسات والبحوث والخطط لعددٍ من القطاعات الاقتصادية بما يُسهم في تطويرها، وتحليل سلاسل القيمة لهذه القطاعات وإيجاد الفرص الاستثمارية المرتبطة بها، والعمل على تطويرها لتصبح ذات قيمة مضافة، إضافة إلى تدريب وتأهيل القدرات الوطنية، وتبني تقنيات الأتمتة والثورة الصناعية الرابعة ضمن سلاسل القيمة المرتبطة بها.',NULL,'https://iia.om/',5,12,1,'2026-06-05 10:18:24','2026-06-10 11:47:51'),(73,'Photos_ScientificResearchInnovationCenters/1buy9hck6Q6VTtx8tHObNsTjnj8ztRLPX9ITJgTo.png','مركز البحوث في علوم البيئة والتكنولوجيا','Environmental Science  & Technology Center','يُعتبرّ مركز البحوث في علوم البيئة والتكنولوجيا، بكلية الهندسة بالجامعة الوطنية للعلوم والتكنولوجيا في سلطنة عُمان، مركزًا رياديًا في مجال البحث العلمي والاستشارات المتقدمة، مع تركيز خاص على دراسات النفايات وتطبيقات تقنية النانو ضمن الأنظمة البيئية.\r\nسنة التأسيس: 2018',NULL,'https://nu.edu.om/research/environmental-science-technology-center/',5,12,1,'2026-06-05 10:26:51','2026-06-05 10:26:51'),(74,'Photos_ScientificResearchInnovationCenters/ucjjksQGoFdKE2adDCm0Puyyfwg4b8ASxTz7UNRD.png','مركز أبحاث تحلية المياه للشرق الأوسط',NULL,'مركز أبحاث تحلية المياه للشرق الأوسط مركز هو إقليمي متخصص في أبحاث تحلية المياه والتقنيات البيئية وإدارة الموارد المائية المستدامة.\r\nأنشئ المركز عام 1996 ضمن مبادرة السلام في الشرق الأوسط كمنصة علمية لتعزيز التعاون الإقليمي في قضايا المياه. تم دعمه من قبل دول عدة، منها عُمان، الولايات المتحدة، اليابان، والاتحاد الأوروبي. هدفه الأساسي كان بناء الثقة بين بلدان المنطقة من خلال مشاريع علمية مشتركة ذات منفعة إنسانية.',NULL,'https://www.medrc.org/',5,12,1,'2026-06-05 10:27:51','2026-06-05 10:27:51'),(75,'Photos_ScientificResearchInnovationCenters/UjBdy5aAfYqIO9FodPfhSSBtVziDPawXHL829Le4.jpg','أكاديمية فلسطين للعلوم والتكنولوجيا','Palestine Academy for Science and Technology','أنشئت المؤسسة بقرار رئاسي وفق القرار رقم 114 في عام 1997 والقرار رقم 13 في عام 2004، لتكون مؤسسة وطنية مستقلة ذاتية الإدارة، وتُعنى أكاديمية فلسطين للعلوم والتكنولوجيا بتحفيز سير العلوم والتقدم التكنولوجي والابتكار والإبداع في فلسطين، كما وتُعنى بحسن توظيف هذه المجالات نحو التنمية الاقتصادية والاجتماعية والإنسانية في المجتمع الفلسطيني.',NULL,'https://www.palast.ps/ar',5,13,1,'2026-06-05 10:28:58','2026-06-05 10:32:22'),(76,'Photos_ScientificResearchInnovationCenters/anrCX4JurOVD1BomnJDIToP4pVCBD93auwoFJ9Dv.png','المركز الفلسطيني الكوري للتكنولوجيا الحيوية',NULL,'مركز التكنولوجيا الحيوية للأبحاث هو أحد المراكز البحثية التابعة لعمادة الدراسات العليا والبحث العلمي في جامعة بوليتكنك فلسطين، ولقد بدأ المركز كوحدة بحثية وتدريبية أنشأت عبر صندوق تطوير الجودة / وزارة التربية والتعليم والممول من الاتحاد الأوروبي والبنك الدولي، وتم الافتتاح الرسمي للمركز عام 2009 بعد اكتمال البنية التحتية للمختبرات وذلك تزامناً مع اطلاق برنامج ماجستير التكنولوجيا الحيوية المشترك مع جامعة بيت لحم.',NULL,'https://biotech.ppu.edu/ar',5,13,1,'2026-06-05 10:30:59','2026-06-05 10:30:59'),(77,'Photos_ScientificResearchInnovationCenters/ozqGmoWLkDVNCliBxdEzKDzGs66ndUprdAbX9cKE.png','مركز الابتكار والشراكات الصناعية',NULL,'تم إنشاء \"مركز الابتكار والشراكات الصناعية\" في جامعة بوليتكنك فلسطين كجزء من رؤية الجامعة الاستراتيجية لتعزيز ارتباطها بالمجتمع الصناعي الوطني وخدمته بشكل فعال. يأتي هذا المركز كمحور أساسي للتعاون بين الجامعة والقطاع الصناعي، بهدف تعزيز الابتكار ونقل التكنولوجيا، وتقديم الدعم الفني والاستشاري، وتطوير الأعمال الرقمية والاقتصاد الأخضر.',NULL,'https://ppu.edu/p/ar/administrative-departments/ciip',5,13,1,'2026-06-05 10:33:29','2026-06-05 10:33:29'),(79,'Photos_ScientificResearchInnovationCenters/clBh3M0u8VRM49jcrBT9ie5mCQOmMx04XZJYanl3.png','معهد قطر لبحوث البيئة والطاقة',NULL,'يُعنى معهد قطر لبحوث البيئة والطاقة، التابع لجامعة حمد بن خليفة، بمواجهة التحديات المعقّدة المتعلّقة بالطاقة والمياه والبيئة، مع التركيز بشكل خاص على حالة دولة قطر والمناطق الجافة.\r\nفيعتمد على نهجٍ متعدد التخصصات في تطوير حلول مبتكرة، تعزّز الاستدامة والتكيّف، سعيًا لتحقيق التقدّم في هذه القطاعات عبر تطبيق أحدث الأبحاث وتشجيع التعاون، وضمان مستقبل مستدام وقابل على التكيّف للمنطقة والعالم أجمع.',NULL,'https://www.hbku.edu.qa/en/qeeri',5,14,1,'2026-06-05 10:36:05','2026-06-05 10:36:05'),(80,'Photos_ScientificResearchInnovationCenters/2ZJF8hZHhsppjfIDu2o4OYPTvnspz3iAKGBrkCSH.png','معهد قطر لبحوث الحوسبة',NULL,'يعد معهد قطر لبحوث الحوسبة معهًدا قوميًا للبحوث.\r\n تأسس المعهد عام 2010 بصفته أحد الكيانات التابعة لمؤسسة قطر للتربية والعلوم وتنمية المجتمع، وهي مؤسسة مستقلة غير ربحية تدعم تحول قطر من اقتصاد الكربون إلى الاقتصاد المعرفي.\r\n ويعمل معهد قطر لبحوث الحوسبة تحت مظلة جامعة حمد بن خليفة.',NULL,'https://www.hbku.edu.qa/ar/qcri',5,14,1,'2026-06-05 10:36:52','2026-06-05 10:36:52'),(81,'Photos_ScientificResearchInnovationCenters/dFMgVGvbIzrAwQrRlOEQ2qC0Z637ca0UFhIGTIld.png','واحة قطر للعلوم والتكنولوجيا',NULL,'واحة قطر للعلوم والتكنولوجيا هي مجمع بحثي وابتكاري تابع لـمؤسسة قطر، تأسست سنة 2009 وتقع في المدينة التعليمية بالدوحة. \r\nوتُعد مركزًا وطنيًا للبحث والتطوير يهدف إلى دعم الابتكار وريادة الأعمال التكنولوجية وتعزيز التحول نحو اقتصاد قائم على المعرفة في قطر. توفر الواحة بنية تحتية متقدمة ومختبرات متخصصة، وتستقطب شركات عالمية مثل مايكروسوفت وشل وجنرال إلكتريك، مع التركيز على تطوير حلول في مجالات الطاقة والبيئة والصحة وتكنولوجيا المعلومات.',NULL,'https://qstp.qa/joinus/',5,14,1,'2026-06-05 10:37:55','2026-06-05 10:37:55'),(82,'Photos_ScientificResearchInnovationCenters/XseJEKYrKw9McXZgfNEFm38jHhPowQy7IeHEJLvJ.png','مركز قطر للابتكار  وريادة الأعمال',NULL,'يُعد مركز قطر للابتكار وريادة الأعمال مؤسسة قطرية تهدف إلى دعم بيئة الابتكار، وتمكين رواد الأعمال، وتعزيز اقتصاد المعرفة في الدولة. يعمل المركز على تطوير منظومة متكاملة لاحتضان المشاريع الناشئة وتسهيل نقل المعرفة والتقنيات الحديثة إلى السوق المحلي.',NULL,'https://www.qdb.qa/',5,14,1,'2026-06-05 10:38:38','2026-06-05 10:38:38'),(83,'Photos_ScientificResearchInnovationCenters/T6YJeYoMu9Y1BGCMLyhYAjUX1sOVkNa2v9Tsghyp.png','مركز حاضنة الأعمال',NULL,'يركز مركز حاضنة الأعمال في واحة قطر للعلوم والتكنولوجيا على تسريع إنشاء ونمو الشركات الناشئة الواعدة في مجال التكنولوجيا من خلال التأسيس السريع لهذه الشركات في المنطقة الحرة بواحة قطر للعلوم والتكنولوجيا، وتوفير مساحة العمل المشترك التعاوني، وتسهيل الأعمال وخدمات الدعم التي تشمل الوصول إلى شبكة من المرشدين، وبرامج التمويل، ومرافق التدريب والنمذجة الأولية.',NULL,'https://qstp.qa/ar/incubation-center',5,14,1,'2026-06-05 10:39:27','2026-06-05 10:39:27'),(84,'Photos_ScientificResearchInnovationCenters/pOF9RKw2lbZO9rzgInxGF2aSHttbuX5WcMfaThiV.png','مركز قطر للابتكارات في التنقل',NULL,'هو مركز وطني للبحث والتطوير والابتكار، تأسس سنة 2009 بهدف تطوير حلول التنقل الذكي والمدن الذكية والأنظمة الرقمية المتقدمة في دولة قطر. \r\nمن أبرز مجالات عمله:\r\nأنظمة النقل الذكي \r\nالمدن الذكية \r\nالذكاء الاصطناعي وإنترنت الأشياء \r\nإدارة المواقف الذكية \r\nتحليل البيانات الجغرافية \r\nحلول السلامة والتنقل الحضري \r\nومن أشهر مشاريعه:\r\nتطبيق «وين» للمواصلات والمواقف \r\nأنظمة إدارة مواقف السيارات الذكية \r\nحلول مراقبة الحركة المرورية والتنقل الذكي في الفعاليات الكبرى مثل كأس العالم 2022 وكأس العرب.',NULL,'https://qmic.com/',5,14,1,'2026-06-05 10:40:42','2026-06-05 10:40:42'),(85,'Photos_ScientificResearchInnovationCenters/diCcWSaVG3RiZ3v95gwFgL0tYuqj9yhpbMfxioja.jpg','مركز المواد المتقدمة',NULL,'هو مركز بحثي تابع لـ جامعة قطر، تأسس سنة 2002 بهدف تطوير الأبحاث التطبيقية في علوم وهندسة المواد المتقدمة.\r\nيعمل المركز تحت إشراف مكتب نائب رئيس الجامعة للبحث والدراسات العليا، ويُعتبر من أهم مراكز البحث العلمي في قطر في مجالات المواد الحديثة والتقنيات الصناعية. \r\nمجالات البحث الرئيسية\r\nتقنية النانو \r\nالمواد المستدامة \r\nالتآكل وحماية المعادن \r\nمواد البوليمر \r\nمواد البناء المتقدمة \r\nالطاقة المتجددة \r\nالاختبارات غير الائتلافية \r\nمعالجة وتحلية المياه',NULL,'https://www.qu.edu.qa/ar/research/cam/',5,14,1,'2026-06-05 10:41:59','2026-06-05 10:41:59'),(86,'Photos_ScientificResearchInnovationCenters/xY9mUWlGkuQLTtIomcgeMSeJNTVHgBkPkmW54pVZ.png','مركز الكويت العلمي','TSCK','تأسس المركز العلمي في أبريل 2000 كمبادرة من سمو الأمير الراحل الشيخ جابر الأحمد الجابر الصباح (رحمه الله)، الذي آمن بأهمية نشر العلوم وتحفيز الأجيال على الابتكار. وقد أوكلت مؤسسة الكويت للتقدم العلمي مهمة إنشاء مركز علمي تفاعلي يجمع بين التعليم والترفيه، ويقدم العلوم للجمهور بطريقة ممتعة وهادفة.\r\nمنذ افتتاحه، استقبل المركز أكثر من 11 مليون زائر من داخل الكويت وخارجها. من خلال المعارض التفاعلية، والبرامج التعليمية، والتجارب الغامرة، يواصل المركز العلمي إشعال شرارة الفضول ونشر الثقافة العلمية وتعزيز فهمنا للعالم من حولنا.',NULL,'https://tsck.org.kw/',5,15,1,'2026-06-05 10:42:56','2026-06-05 10:44:52'),(87,'Photos_ScientificResearchInnovationCenters/NfjvIxNetFTUdtUFw5GXY8VA8oWdKEuhJm2LYtlg.png','مركز صباح الأحمد للموهبة والإبداع',NULL,'مركز صباح الأحمد للموهبة والإبداع هو مؤسسة كويتية تعنى باكتشاف ودعم الموهوبين والمبدعين في مجالات العلوم والتكنولوجيا والفنون. يُعد أحد مبادرات مؤسسة الكويت للتقدم العلمي، ويهدف إلى تنمية رأس المال البشري الوطني عبر برامج تأهيلية ومشاريع ابتكارية.\r\nوتأسس سنة 2010.',NULL,'https://sacgc.org/ar/',5,15,1,'2026-06-05 10:44:17','2026-06-05 10:44:17'),(88,'Photos_ScientificResearchInnovationCenters/s2bcVlaUJGUn1sR8ltwqEWkfKeCt4XM6zaOdieIS.png','معهد الكويت للأبحاث العلمية',NULL,'تأسس معهد الكويت للأبحاث العلمية\r\n سنة 1967، وهو أهم مركز بحثي تطبيقي حكومي في الكويت. \r\nيركز على البحث العلمي المرتبط بالصناعة مثل الطاقة، النفط، المياه، البيئة، والأمن الغذائي، ويعمل على تطوير حلول تقنية تخدم التنمية الصناعية في الدولة.',NULL,'https://www.kisr.edu.kw/en/',5,15,1,'2026-06-05 10:46:08','2026-06-05 10:46:08'),(89,'Photos_ScientificResearchInnovationCenters/3w5fgtcXnfEK7OZ47C8m28ekkjmYVRcHR5WGdQdY.png','مؤسسة الكويت للتقدم العلمي','Advancement of Sciences, KFAS','مؤسسة الكويت للتقدم العلمي هي مؤسسة غير ربحية أُسست عام 1976 بمبادرة من أمير الكويت الراحل الشيخ جابر الأحمد الجابر الصباح.\r\n تهدف إلى تعزيز العلوم والتكنولوجيا والابتكار في الكويت عبر تمويل الأبحاث، ودعم التعليم العلمي، وبناء قدرات البحث والتطوير في القطاعين العام والخاص.',NULL,'https://www.kfas.org/ar/',5,15,1,'2026-06-05 10:47:56','2026-06-05 10:47:56'),(90,'Photos_ScientificResearchInnovationCenters/wVTznibGZzOYRQxLJVlZdWGhgb1nKg5PWRjPXLkJ.png','بيريتك',NULL,'بيريتك\r\nهي منظمة لبنانية رائدة في دعم ريادة الأعمال والابتكار، تتخذ من بيروت مقرًا لها.\r\n تأسست لتشجيع تطوير المشاريع الناشئة في مجالات التكنولوجيا والاقتصاد الرقمي، وتعدّ حاضنة ومسرّعة أعمال مركزية في النظام البيئي اللبناني للابتكار.\r\nسنة التأسيس: 2002',NULL,'https://berytech.org/',5,16,1,'2026-06-05 10:49:17','2026-06-05 10:49:17'),(91,'Photos_ScientificResearchInnovationCenters/oWhbmAEBAyE9f1F00JMtkk8iQ7kyOlVh4VdNR4tK.png','المجلس الوطني للبحوث العلمية','CNRS-L','المجلس الوطني للبحوث العلمية هو هيئة حكومية لبنانية تُعنى بتخطيط وتمويل وتنسيق البحث العلمي في لبنان. يُعدّ المرجع الوطني الأساسي في وضع السياسات البحثية وتطوير القدرات العلمية، ويعمل على تعزيز الابتكار وربط البحث بالقطاعات الاقتصادية والاجتماعية.\r\nتاريخ التأسيس: 1962',NULL,'https://cnrs.edu.lb/',5,16,1,'2026-06-05 10:50:36','2026-06-05 10:50:36'),(92,'Photos_ScientificResearchInnovationCenters/TMRAWbZyJj5ZIuHvFtcnxBfY2BVJbLnNuEdL1usB.png','اللجنة اللبنانية للطاقة الذرية   المركز الوطني للبحوث العلمية',NULL,'اللجنة اللبنانية للطاقة الذرية تأسست سنة 1996 تحت إشراف المجلس الوطني للبحوث العلمية وبدعم من الوكالة الدولية للطاقة الذرية، وتُعد الهيئة الوطنية المختصة بالاستخدام السلمي للطاقة والتكنولوجيا النووية في لبنان، حيث تعمل على تطوير السلامة الإشعاعية والحماية النووية ودعم التطبيقات العلمية والتكنولوجية للطاقة الذرية في مجالات الصحة، والبيئة، والزراعة، والصناعة.',NULL,'https://cnrs.edu.lb/lebanese-atomic-energy-commission/',5,16,1,'2026-06-05 10:52:18','2026-06-05 10:52:18'),(93,'Photos_ScientificResearchInnovationCenters/SZmHmxJyqNUrO6TrRvkLLpTFQrA9TRGQxCFoSXWI.jpg','المركز الوطني للاستشعار عن بعد',NULL,'المركز الوطني للاستشعار عن بعد تأسس سنة 1995، وهو الهيئة الوطنية اللبنانية المتخصصة في بيانات الأقمار الصناعية والتقنيات الجغرافية المكانية، ويعمل تحت إشراف المجلس الوطني للبحوث العلمية. يختص المركز بتطوير وتحليل بيانات رصد الأرض ونظم المعلومات الجغرافية لدعم إدارة الموارد الطبيعية والتخطيط العمراني والزراعة والبيئة والتنمية المستدامة، كما يُعد مركزًا وطنيًا وإقليميًا للبحث والابتكار في مجالات الاستشعار عن بعد والتكنولوجيا الجغرافية.',NULL,'https://cnrs.edu.lb/national-center-for-remote-sensing/',5,16,1,'2026-06-05 11:09:05','2026-06-05 11:09:05'),(94,'Photos_ScientificResearchInnovationCenters/r6GysfxburpjWwJt1uIaqjdjwOPNsWG2dGgmLlU8.png','المركز الليبي للمنظومات الإلكترونية والبرمجيات وبحوث الطيران',NULL,'تم تأسيس المركز الليبي للمنظومات الإلكترونية والبرمجيات وبحوث الطيران بموجب قرار رئاسة الوزراء رقم (234) لسنة 2012م ومقره مدينة طرابلس، وذلك بضم أربع مراكز بحثية كما جاء فى القرار وهي مركز المحاكة والواقع الافتراضي ومركز بحوث الضوئيات وتطبيقات الليزر ومركز بحوث البرمجيات ومركز بحوث الطيران. ويهــدف هذا المركز إلى تحقيق نهضة تقنية وعلمية متميزة وتطوير البحث العلمي في مجـال علوم الحاسب الآلي والمنظومات الإلكترونية وتطبيقاتها والحصول على درجة عالية من الجودة حسب المعايير الدولية، كما يساهم في التنمية البشرية للأكاديميين ورواد البحث العلمي من خلال العمل على بناء شراكات محلية ودولية وتبادل الخبرات ونقل المعرفة والذي سينعكس بدوره على الإيفاء باحتياجات التنمية الاقتصادية المستدامة للدولة الليبية.',NULL,'https://epc.ly/',5,17,1,'2026-06-05 11:42:09','2026-06-05 11:42:09'),(95,'Photos_ScientificResearchInnovationCenters/ck5tqaeFJ96NfQXgUaxtpKX68U3SWopddMK3wlJU.jpg','مركز بحوث الطاقة الشمسية',NULL,'تأسس مركز دراسات الطاقة الشمسية بموجب القرار الصادر عن اللجنة الشعبية العامة في منتصف عام 1978.\r\n ولقد حدد ذلك القرار أهداف المركز في نقاط ثلاث، هي:\r\n- القيام بالأبحاث والدراسات العلمية في مجال الطاقة الشمسية.\r\n- وضع واقتراح الخطط الكفيلة بتحقيق الاستغلال الموسع للطاقة الشمسية.\r\n- نشر الوعي العلمي في مجال الطاقة الشمسية.',NULL,'https://csers.ly/ar/about-us',5,17,1,'2026-06-05 11:43:52','2026-06-05 11:43:52'),(96,'Photos_ScientificResearchInnovationCenters/b1HVfWNhCjh4TIOzTT6tbhn6hXfLzYulU4e9edzk.png','مركز البحوث النووية',NULL,'بداء مشروع انشاء المركز سنة 1976 وتم افتتاحه رسميا سنة 1982 ويعتبر مركز البحوث النووية بتاجوراء مركز متقدم للعلوم والتكنولوجيا ومتعدد التخصصات ومن أقدم وأكبر المراكز البحثية في ليبيا، يشمل عشرات من المباني والمنشآت ويشغل مساحة تناهز 300 هكتار.',NULL,'https://aee.gov.ly/tnrc/',5,17,1,'2026-06-05 11:45:00','2026-06-05 11:45:00'),(97,'Photos_ScientificResearchInnovationCenters/dvJiSYiscoPGUInJ3IlHzfVeBDVXbseaSXmcwSKF.png','الهيئة الليبية للبحث العلمي',NULL,'أسست الهيئة سنة 1978م لغرض تنفيذ مخططات الدولة الاستراتيجية من خلال اتّباع منهجية البحث العلمي، وتعبئة جهود العلماء والباحثين والخبراء والمخترعين في مختلف المجالات.\r\nوتقوم الهيئة بمتابعة واجباتها المتمثلة في إدارة ومتابعة البحوث والدراسات في المراكز البحثية التابعة لها ذات الاختصاصات في شتى مجالات البحث العلمي، وذلك من خلال اعتماد الخطط والبرامج البحثية، وتقديم الدعم المادي، وإعداد وتوثيق التقارير العلمية، والمتابعة الدورية للأبحاث والدراسات والتطوير العلمي.',NULL,'https://www.aonsrt.ly/',5,17,1,'2026-06-05 11:46:52','2026-06-05 11:46:52'),(98,'Photos_ScientificResearchInnovationCenters/zpIufSPt7nCwGbkSwMsPciZpwFi7UumJGD8xvdp5.png','مركز البحوث الصناعية',NULL,'يُعد مركز البحوث الصناعية إحدى الجهات التابعة لوزارة الصناعة والمعادن، ويعمل كركيزة أساسية لدعم التطور الصناعي في ليبيا. يركز المركز على تطوير الأبحاث التطبيقية والعملية التي تهدف إلى تحقيق أقصى استفادة من الموارد الطبيعية والخامات المحلية، بما يساهم في تعزيز الإنتاجية وتحقيق التنمية المستدامة.\r\nيقوم المركز بدور محوري في تعزيز القدرات البحثية والتقنية، حيث يقدم مجموعة من الخدمات تشمل إعداد الدراسات الفنية والاقتصادية، وتنفيذ مشاريع بحثية تدعم احتياجات الصناعة، وتقديم الاستشارات الفنية للمؤسسات العامة والخاصة. كما يسهم المركز في تحسين طرق الإنتاج، وتطوير المنتجات الصناعية باستخدام التقنيات الحديثة، فضلاً عن تحسين كفاءة العمليات وتقليل التكاليف.',NULL,'https://irc.ly/',5,17,1,'2026-06-05 11:51:08','2026-06-05 11:51:08'),(99,'Photos_ScientificResearchInnovationCenters/HMlTnoYmPUNlkXnOWr4oy6SMata3VGgtx817ldrI.png','مركز الطاقات المتجددة',NULL,'مركز الطاقات المتجددة هو أحد الجهات التابعة لوزارة الصناعة والمعادن في ليبيا، ويُعد مؤسسة بحثية استشارية وتدريبية رائدة في مجال الطاقات المتجددة وكفاءة الطاقة. يركز المركز على البحث والتطوير في مجالات الطاقات المتجددة، ويعمل على تطبيق تقنيات الطاقة المستدامة بما يتناسب مع البيئة المحلية. يُعتبر المركز منصة هامة للابتكار والبحث العلمي، حيث يسهم في توطين تقنيات الطاقات المتجددة وتطويرها لتلبية احتياجات السوق الليبي والمجتمع، وتحقيق أهداف التنمية المستدامة.',NULL,'http://rec.misuratau.edu.ly/',5,17,1,'2026-06-05 11:52:08','2026-06-05 11:52:08'),(100,'Photos_ScientificResearchInnovationCenters/3bhrA9Qf1F9PeneySP7LOhP2hbzDx58hjifFoZVj.png','أكاديمية البحث العلمي والتكنولوجيا',NULL,'أكاديمية البحث العلمي والتكنولوجيا هي الأكاديمية الوطنية لمصر في مجال العلوم والتكنولوجيا والابتكار وبيت الخبرة ووعاء الفكر الوطني المعني بالتخطيط الاستراتيجي وإعداد خرائط الطريق التكنولوجية والدراسات المستقبلية وتقديم الاستشارات العلمية المجردة للحكومة ولصناع القرار بشأن القضايا المتعلقة بالعلوم والتكنولوجيا في مصر والعالم. وهي الداعم الحكومي للابتكار وريادة الأعمال والحاضنات التكنولوجية والتسويق التكنولوجي وحماية الملكية الفكرية.',NULL,'http://www.asrt.sci.eg/',5,18,1,'2026-06-05 11:53:46','2026-06-05 11:53:46'),(101,'Photos_ScientificResearchInnovationCenters/kceE7YNcI7HjQypuRRcGmNDl6m3JIkxJOL2aButn.jpg','مدينة الأبحاث العلمية والتطبيقات التكنولوجية','SRTA-City','تُعد مدينة الأبحاث العلمية والتطبيقات التكنولوجية واحدة من أبرز المؤسسات البحثية في مصر والمنطقة العربية. تأسست لتكون مركزاً للتميز والإبداع، حيث تعمل كحلقة وصل حيوية بين البحث الأكاديمي والاحتياجات الصناعية. تضم المدينة مجموعة من المعاهد البحثية المتخصصة والمراكز التكنولوجية المجهزة بأحدث التقنيات، مما يجعلها بيئة خصبة لإنتاج المعرفة وتحويلها إلى حلول تطبيقية تخدم الاقتصاد الوطني.',NULL,'https://srtacity.sci.eg/ar',5,18,1,'2026-06-05 11:54:35','2026-06-05 11:54:35'),(102,'Photos_ScientificResearchInnovationCenters/A7C5tkSY1TskZ14vJXHXkmK4t7tq36Yl4nlfiZoI.png','المركز القومي للبحوث',NULL,'تأسس المركز القومي للبحوث كمنظمة عامة مستقلة في عام 1956 ، بهدف \"تعزيز البحث العلمي الأساسي والتطبيقي، لا سيما في الصناعة والزراعة والصحة العامة وقطاعات الاقتصاد الوطني الأخرى\". وهي أكبر المؤسسات التابعة لوزارة البحث العلمي وتوظف حوالي 60٪ من مجموع العلماء العاملين في هذه المؤسسات.',NULL,'https://www.nrc.sci.eg/',5,18,1,'2026-06-05 11:55:28','2026-06-05 11:55:28'),(103,'Photos_ScientificResearchInnovationCenters/mSMw4HjBTOsbmWlGfwy9cXu3gK3y19L5g97VMPUv.png','مركز بحوث الإلكترونيات',NULL,'تأسس بالقرار الجمهوري رقم 38 لسنة 1989 وهو احدى المعاهد المتخصصة التابعة لوزارة البحث العلمي. تشمل أنشطة الابحاث النظرية والتطبيقية في مجالات الاليكترونيات، والاتصالات، وأجهزة الحاسوب، والمعلوماتية. وتقديم خدمات الاستشارات العلمية للقطاع الصناعي من أجل الانتاج والخدمات. ويتكون حاليا من سبعة أقسام تضم أكثر من مائتي عضو باحث ليكون واحد من أكبر كيانات البحث العلمي في مصر.',NULL,'https://eri.sci.eg/ar/about-us',5,18,1,'2026-06-05 11:57:20','2026-06-05 11:57:20'),(104,'Photos_ScientificResearchInnovationCenters/naf4JPpJsclpdUziczC1OWIZlCQ2a8cSorXW3gFy.png','مركز تحديث الصناعة','INDUSTRIAL MODERNISATION CENTER','مركز تحديث الصناعة هو كيان تم تأسيسه في ديسمبر 2000 بقرار جمهوري، بدعم من الاتحاد الأوروبي والحكومة المصرية، بهدف تعزيز الصناعة المصرية وتحقيق نمو اقتصادي مستدام. يعمل المركز على تقديم الدعم لمختلف المنشآت الصناعية في11 قطاعًا متخصصًا، حيث يقوم بدراسة احتياجاتها ووضع استراتيجيات لتحسين الإنتاجية وزيادة التنافسية.',NULL,'https://www.imc-egypt.org/ar',5,18,1,'2026-06-05 11:59:08','2026-06-05 11:59:08'),(105,'Photos_ScientificResearchInnovationCenters/8vdtOT2iMAL0nCsIXzwp0r4fiUuDsOK8Q97XFIJL.png','هيئة الطاقة الذرية المصرية',NULL,'تأسست سنة 1955، وهي المؤسسة الوطنية المختصة بالأبحاث النووية والتكنولوجيا الذرية السلمية، وتعمل في مجالات الطاقة النووية، التطبيقات الصناعية والطبية، والفيزياء الإشعاعية.',NULL,'http://www.eaea.org.eg/',5,18,1,'2026-06-05 11:59:57','2026-06-05 11:59:57'),(107,'Photos_ScientificResearchInnovationCenters/0ZLyk1hkK4HsU43l6zeye4oF89gdKEdtvreJuAQE.jpg','مركز الطاقة المتجددة والتصميم الالكتروني',NULL,'مركز الطاقة المتجددة والتصميم الالكتروني كيان علمي بحثي تطبيقي تأسس في عام 1996 كأول مركز للطاقة الشمسية في الجمهورية اليمنية على يد نخبة من المتخصصين المتميزين في هذا المجال ومن ثم أسس مركز التدريب والتصميم الالكتروني ليعمل على تدريب الكوادر الهندسية في مجال التصاميم الالكترونية والمجالات الفنية الهندسية المختلفة. في عام 2012 تم دمج المركزين كمركز واحد باسم مركز الطاقة المتجددة والتصميم الالكتروني لتحقيق التكامل بين المركزين.',NULL,'https://ust.edu/center-of-renewable-energy-and-electronic-projects/',5,21,1,'2026-06-05 12:03:48','2026-06-05 12:03:48'),(109,'Photos_ScientificResearchInnovationCenters/DJ5BhqY5Qs3JIqx9XBj6rxCvJ9X5JhbSXtibonj9.png','مركز العلوم والتكنولوجيا','Science and Technology Center','تعتبر مراكز العلوم والتكنولوجيا من أهم المراكز العلمية التي تحتويها جامعات العالم المتقدم.. مركز العلوم والتكنولوجيا (جامعة عدن) يشكل حلقة وصل علمية تكنولوجية  فعالة بين الجامعة والمجتمع .. فهو المنسق الوحيد - فيما يخص مجالات فرقه البحثية-  بين جامعة عدن والجامعات والمراكز والمؤسسات العلمية المناظرة المحلية والعربية والأجنبية وكذا المنظمات الداعمة. مركز العلوم والتكنولوجيا يعمل من جهة على تعريف المجتمع بالقدرات البحثية والخبرات العلمية لدى أعضاء هيئة التدريس بالجامعة خاصة منهم أعضاء الفرق البحثية بالمركز لكي يستطيع المجتمع بمؤسساته الإنتاجية والخدمية الاستفادة من تلك الكفاءات والخبرات. ومن جهة أخرى  يقوم المركز بالنزول الميداني للمؤسسات الإنتاجية والخدمية والتعرف عن قرب على التكنولوجيات المتبعة فيها ومواطن النقص ومواطن الحاجة للبحث العلمي لدى تلك المؤسسات، وذلك لغرض توجيه الدراسات والبحوث العلمية بما يخدم حاجة المجتمع حتى يكون لتلك الدراسات والبحوث التطبيق العملي والمردود السريع والملموس وبما يلبي حاجة المجتمع .. فدور المركز دور تنويري تنسيقي بحثي خدماتي.',NULL,'http://www.stcau-ti.net/',5,21,1,'2026-06-05 12:07:02','2026-06-09 11:46:11'),(111,'Photos_ScientificResearchInnovationCenters/PKge6x5fUDue2ziMwTsqsMMHJFYnsrQCX4Fbx7Ee.png','الوكالة الوطنية للبحث العلمي والابتكار',NULL,'تأسست سنة 2021، وهي الهيئة الوطنية المكلفة بتطوير البحث العلمي والابتكار في موريتانيا، وتعمل على دعم المشاريع البحثية والتكنولوجية وربط البحث العلمي بالتنمية الاقتصادية والصناعية.',NULL,'https://anrsi.mr/expert-anrsi',5,20,1,'2026-06-05 12:10:15','2026-06-05 12:10:15'),(112,'Photos_ScientificResearchInnovationCenters/AsgkxQ8Rc3XjseyICeABFBmUfMVfSnVBXkA3fCFP.png','بوابة البحث العلمي الموريتانية',NULL,'منصة وطنية رقمية أطلقتها وزارة التعليم العالي والبحث العلمي بهدف ربط الباحثين الموريتانيين وتسهيل التعاون العلمي وتبادل البيانات والفرص البحثية ودعم الابتكار.\r\nوتسعى بوابة البحث العلمي إلى خلق فضاء عمل تشاركي بين الباحثين الموريتانيين داخل موريتانيا وفي المهجر.',NULL,'https://prs-mesrs.gov.mr/ar',5,20,1,'2026-06-05 12:11:16','2026-06-05 12:11:16'),(114,'Photos_ScientificResearchInnovationCenters/0JcxFAFfG0rQxskNdMFusPxi6ZvGANH0UIjxywk3.jpg','مركز كوزموس للابتكار و ريادة الأعمال','Kosmos Innovation Center','مركز وطني لدعم الابتكار وريادة الأعمال، أُطلق في موريتانيا سنة 2018 بهدف تمكين الشباب ورواد الأعمال من تطوير مشاريع مبتكرة وقابلة للنمو.\r\n يوفر المركز برامج للتدريب والاحتضان والإرشاد والتمويل الأولي، ويساهم في تعزيز منظومة الشركات الناشئة ودعم التنمية الاقتصادية المستدامة  وفي تمويل أفكار المشاريع الصغيرة في أفريقيا، وخاصةً لرواد الأعمال الشباب في غانا والسنغال وموريتانيا. نحن الآن منظمة رائدة تُحقق تغييرًا إيجابيًا من خلال التمكين والابتكار في موريتانيا.',NULL,'https://kosmosinnovationcenter.com/',5,20,1,'2026-06-05 14:18:58','2026-06-05 14:22:57'),(115,'Photos_ScientificResearchInnovationCenters/f2UEIXtz1kca99rWAEANEN0vlmQ9WF9ljI0WZdc8.png','المعهد الموريتاني للبحث العلمي','imrspc','أنشئ المعهد الموريتاني للبحث العلمي بموجب المرسوم رقم: 74/243 الصادر بتاريخ 31/12/1974 الذي ألغاه وحل محله المرسوم رقم: 088/2004 الصادر بتاريخ 14/10/2004 الذي بموجبه أصبح اسمه المعهد الموريتاني للبحث والتكوين في مجال التراث. وهي مؤسسة عمومية ذات طابع إداري علمي ، ثقافي وتقني ومستقلة ماليا وإداريا، خاضعة لوصاية الوزير المكلف بالثقافة. وقد نيطت بالمعهد مهمة النهوض بالبحث العلمي في مختلف ميادين العلوم الإنسانية من مخطوطات وآثار وتراث مروي والقيام بالدراسات والتحقيقات المؤدية إلى معرفة أفضل للتراث الثقافي والعلمي والطبيعي وإثرائه وحمايته وتثمينه ونشره وتشجيع تكوين وتدريب الباحثين الوطنيين والأجانب في مجال العلوم الإنسانية',NULL,'https://www.imrspc.mr/',5,20,1,'2026-06-05 14:31:40','2026-06-09 10:55:34'),(116,'Photos_MinistriesHigherEducationScientificResearch/CN2eKMFwG4wiIPIRziwXzKYlEgxoKK5AwZkJZXHI.png','وزارة التعليم العالي والبحث العلمي والابتكار','enssup','تعود جذور الوزارة إلى سنة 1955 بعد استقلال المغرب، وشهدت عدة إصلاحات وتغييرات هيكلية إلى أن أصبحت تحمل اسم \"وزارة التعليم العالي والبحث العلمي والابتكار\". وتعمل الوزارة على تطوير جودة التعليم العالي، وتشجيع البحث العلمي، وتعزيز الابتكار وربط الجامعة بالمحيط الاقتصادي والاجتماعي بما يساهم في التنمية المستدامة للمملكة.',NULL,'https://www.enssup.gov.ma/ar',5,19,3,'2026-06-08 08:34:58','2026-06-08 08:51:35'),(117,'Photos_MinistriesHigherEducationScientificResearch/eS1RU1LYriBAbOuY5i81s6l31V8LZlC8KyCg9KwH.png','وزارة الصناعة والتجارة','mcinet','وزارة الصناعة والتجارة بالمملكة المغربية هي مؤسسة حكومية أُنشئت سنة 1955، وتتولى إعداد وتنفيذ السياسات العمومية في مجالات الصناعة والتجارة، بما يسهم في تعزيز التنمية الاقتصادية ورفع تنافسية الاقتصاد الوطني. وتضطلع الوزارة بدور محوري في تطوير النسيج الصناعي، ودعم المقاولات، وتشجيع الاستثمار المنتج، وتنمية المبادلات التجارية على المستويين الوطني والدولي. كما تعمل على مواكبة التحول الصناعي والابتكار، وتحسين مناخ الأعمال، وتعزيز اندماج الاقتصاد المغربي في سلاسل القيمة العالمية. ويقع مقرها بمدينة الرباط.',NULL,'https://www.mcinet.gov.ma/',5,19,3,'2026-06-08 08:37:26','2026-06-08 08:51:18'),(118,'Photos_MinistriesHigherEducationScientificResearch/NxLu2hAnzO2qXwom1sDK6bV58WWPZLN5cZoVRuLH.png','وزارة الانتقال الرقمي وإصلاح الإدارة','mmsp','وزارة الانتقال الرقمي وإصلاح الإدارة هي مؤسسة حكومية مغربية تُعنى بقيادة التحول الرقمي للإدارة العمومية وتطوير الخدمات الرقمية الموجهة للمواطنين والمقاولات، إلى جانب تحديث الإدارة العمومية وتحسين جودة الخدمات العمومية. كما تعمل على إعداد وتنفيذ الاستراتيجيات الوطنية في مجال الرقمنة، وتعزيز الحكومة الإلكترونية، وتبسيط المساطر الإدارية، وتطوير الكفاءات الرقمية، بما يساهم في رفع كفاءة الإدارة وتعزيز الشفافية وتحسين مناخ الأعمال.\r\nسنة التأسيس: أُحدثت الوزارة بصيغتها الحالية تحت اسم \"وزارة الانتقال الرقمي وإصلاح الإدارة\" سنة 2021 ضمن الهيكلة الحكومية الجديدة، مع تعزيز اختصاصاتها التنظيمية بموجب المراسيم الصادرة سنة 2023.',NULL,'https://www.mmsp.gov.ma/ar',5,19,3,'2026-06-08 08:42:42','2026-06-08 08:51:02'),(119,'Photos_MinistriesHigherEducationScientificResearch/p59l4wK2Z9sTwM0o0fVbEknJk3b5u3JKWj5Ju0oM.png','وزارة الإدماج الاقتصادي والمقاولة الصغرى والتشغيل والكفاءات','miepeec','وزارة الإدماج الاقتصادي والمقاولة الصغرى والتشغيل والكفاءاتهي مؤسسة حكومية مغربية أُنشئت بصيغتها الحالية سنة 2021، وتُعد من الفاعلين الرئيسيين في دعم سوق الشغل والتنمية الاقتصادية. تضطلع الوزارة بوضع وتنفيذ السياسات المتعلقة بالتشغيل وتنمية الكفاءات والتكوين المهني، مع التركيز على تأهيل الموارد البشرية بما يستجيب لاحتياجات القطاع الصناعي. كما تعمل على إدماج الشباب في سوق العمل، ودعم المقاولات الصغرى والمتوسطة، وتعزيز قابلية التشغيل والابتكار وريادة الأعمال، بما يساهم في رفع تنافسية الاقتصاد الوطني ودعم التنمية الصناعية المستدامة.',NULL,'https://miepeec.gov.ma/',5,19,3,'2026-06-08 08:44:57','2026-06-08 08:50:44'),(120,'Photos_MinistriesHigherEducationScientificResearch/9Wdzfp03gCGQ5AfCWhkX2CcZTVSK2sZ1nNNT6POv.jpg','وزارة الانتقال الطاقي والتنمية المستدامة','mtedd','وزارة الانتقال الطاقي والتنمية المستدامة هي مؤسسة حكومية مغربية أُنشئت بصيغتها الحالية سنة 2021، وتُعد من الفاعلين الرئيسيين في تحقيق التنمية المستدامة وتعزيز الأمن الطاقي بالمملكة. تتولى الوزارة إعداد وتنفيذ السياسات الوطنية في مجالات الطاقة والمعادن والبيئة والتنمية المستدامة، مع التركيز على تطوير الطاقات المتجددة، وتحسين النجاعة الطاقية، وتقليص الاعتماد على الوقود الأحفوري. كما تعمل على حماية البيئة والحد من التلوث، وتشجيع الاستثمار في مشاريع الطاقة النظيفة، ودعم البحث والابتكار في المجال الطاقي، بما يساهم في تحقيق التوازن بين النمو الاقتصادي والمحافظة على الموارد الطبيعية للأجيال القادمة.',NULL,'https://www.mtedd.gov.ma/',5,19,3,'2026-06-08 08:47:14','2026-06-08 08:50:28'),(123,'Photos_MinistriesHigherEducationScientificResearch/KdMNlF5YkW6jOGceBoMa4ruZ34YiR56Z9RiZpkzX.png','وزارة الصناعة والتجارة والتموين','mit','وزارة الصناعة والتجارة والتموين هي الجهة المسؤولة عن تعزيز موقع المنتج الأردني في الأسواق العالمية ودخول الصناعة الأردنية لأسواق جديدة، وتعزيز تنافسية الصناعات الأردنية والقطاعات الخدمية وتحسين انتاجها وتنظيم التجارة الداخلية والخارجية ومراقبتها، بالإضافة في تنظيم قطاع التأمين ، ومن مهامها أيضاً تشجيع القطاعات الصناعية على الأبداع والابتكار، وتوفير التشريعات الجاذبة لبيئة الأعمال، كذلك تتولى الوزارة إدارة المؤسسات الاستهلاكية المدنية في الأردن.',NULL,'http://www.mit.gov.jo/',5,1,3,'2026-06-08 09:34:07','2026-06-08 09:35:48'),(124,'Photos_MinistriesHigherEducationScientificResearch/wGxVVwgdWVM9GwvTa8MCl3DKJiu9DV4fOqJ0uN0p.jpg','وزارة الاقتصاد الرقمي والريادة','modee','تُعدّ وزارة الاقتصاد الرقمي والريادة (سابقًا: وزارة الاتصالات وتكنولوجيا المعلومات) الجهة الحكومية المسؤولة عن وضع السياسات والتشريعات المنظمة لقطاعات تكنولوجيا المعلومات والاتصالات والبريد في الأردن، كما تتولى الإشراف على استكمال وتطوير وإدامة شبكة الحكومة الإلكترونية، ودعم المبادرات الوطنية في مجالات التحول الرقمي والابتكار وريادة الأعمال.\r\nوفي مايو 2019، تم تغيير اسم الوزارة رسميًا إلى «وزارة الاقتصاد الرقمي والريادة»، وذلك بهدف دعم التحول الرقمي في المملكة، وتعزيز تبني مفاهيم الاقتصاد الرقمي، إلى جانب تطوير منظومة ريادة الأعمال والابتكار في الأردن.',NULL,'https://www.modee.gov.jo/',5,1,3,'2026-06-08 09:35:10','2026-06-08 09:35:10'),(125,'Photos_MinistriesHigherEducationScientificResearch/jRw8ZsG3nRQFBtYfIn0ThMY77FOIVNyLRdrCvrCS.png','وزارة التعليم العالي والبحث العلمي','moe','تُعد وزارة التعليم العالي والبحث العلمي إحدى الوزارات الحكومية في دولة الإمارات العربية المتحدة، وقد أُسست سنة 1976. وكانت تضم عدة قطاعات وأقسام، من بينها مفوضية الاعتماد الأكاديمي (CAA) التي كانت تتولى منح التراخيص المؤسسية والاعتماد الأكاديمي لبرامج الجامعات الخاصة بالدولة. كما كانت تشرف على المكتب الوطني للقبول والتنسيب (NAPO)، المسؤول عن تقديم خدمات القبول والتنسيب لمؤسسات التعليم العالي الاتحادية',NULL,'https://moe.gov.ae/ar/Pages/Default.aspx',5,2,3,'2026-06-08 09:36:56','2026-06-08 09:37:10'),(126,'Photos_MinistriesHigherEducationScientificResearch/METZjiBXUPspjOEvI71Mw1VBh671jsmrfI7rDX0m.png','وزارة الصناعة والتكنولوجيا المتقدمة','moiat','تُعدّ وزارة الصناعة والتكنولوجيا المتقدمة إحدى الجهات الحكومية الاستراتيجية في الإمارات العربية المتحدة، وقد أُنشئت سنة 2020 بهدف تطوير القطاع الصناعي الوطني وتعزيز مكانة الدولة كمركز عالمي للصناعة المتقدمة والتكنولوجيا والابتكار.\r\nتتولى الوزارة وضع السياسات والاستراتيجيات الخاصة بالصناعة والتكنولوجيا المتقدمة، كما تعمل على دعم التحول الصناعي الرقمي، وتبني تقنيات الثورة الصناعية الرابعة، ورفع تنافسية المنتجات الوطنية، إضافة إلى تعزيز البحث والتطوير والابتكار الصناعي.',NULL,'https://moiat.gov.ae/',5,2,3,'2026-06-08 09:38:06','2026-06-08 09:38:06'),(127,'Photos_MinistriesHigherEducationScientificResearch/BNCvANGr4pyOiw0UsXfNPWnJAoAU3EQibb5gxsbS.png','وزارة الصناعة   والتجارة','moic','وزارة الصناعة والتجارة هي الجهة الحكومية المسؤولة عن تنظيم وتطوير القطاعين الصناعي والتجاري في مملكة البحرين. أُنشئت بصيغتها الحالية سنة 2022 ضمن إعادة هيكلة الجهاز الحكومي، وتعمل على إعداد وتنفيذ السياسات والاستراتيجيات الرامية إلى تعزيز النمو الاقتصادي المستدام، وتنمية الصناعات الوطنية، ورفع تنافسية القطاع الخاص. كما تضطلع الوزارة بدعم بيئة الأعمال والاستثمار، وتطوير الأنشطة التجارية والصناعية، وتشجيع الابتكار وريادة الأعمال، بما ينسجم مع رؤية البحرين الاقتصادية 2030 ويسهم في تحقيق التنمية الاقتصادية الشاملة.',NULL,'https://www.moic.gov.bh/',5,3,3,'2026-06-08 09:43:49','2026-06-08 09:44:11'),(130,'Photos_MinistriesHigherEducationScientificResearch/IPOZZAfW5wD2Maj4AdP6UU7mzeTLPkGNkwCzJpAQ.png','وزارة التربية والتعليم','moe','تعود بدايات التعليم في مملكة البحرين إلى الكتاتيب التي كانت تُعنى بتعليم القرآن الكريم والقراءة والكتابة ومبادئ الحساب. ومع مطلع القرن العشرين، شهد التعليم تحولًا مهمًا نحو النظامية، حيث تأسست أول مدرسة نظامية حكومية سنة 1919م في المحرق، وهي الهداية الخليفية.\r\nثم توسع التعليم تدريجيًا، فتم إنشاء أول مدرسة للبنات سنة 1928م، وأول مدرسة صناعية سنة 1938م لتلبية احتياجات سوق العمل. كما بدأ التعليم الثانوي في التطور منذ عام 1940م، وتلاه إنشاء مؤسسات للتعليم العالي مثل معاهد إعداد المعلمين والتمريض في خمسينيات وستينيات القرن الماضي.\r\nومع بداية الألفية الجديدة، شهد التعليم العالي والبحث العلمي تطورًا كبيرًا في البحرين، خاصة بعد تنظيمه بقوانين حديثة وتوسيع مؤسسات الجامعات والبرامج الأكاديمية، إلى جانب دعم تعليم الكبار ومحو الأمية والتعليم المستمر.',NULL,'https://moe.gov.bh/',5,3,3,'2026-06-08 10:27:25','2026-06-08 10:27:25'),(131,'Photos_MinistriesHigherEducationScientificResearch/C7R35DE8clDx93XS2d1khzOEPJJaQxrBpYYLhTT1.png','وزارة التعليم العالي والبحث العلمي','mes','وزارة التعليم العالي والبحث العلمي في تونس هي مؤسسة حكومية مسؤولة عن تنظيم وتطوير التعليم العالي والبحث العلمي في البلاد، وتشرف على الجامعات ومراكز البحث وتضع السياسات الوطنية للبحث العلمي وتشجع الابتكار وربط الجامعة بالتنمية.\r\n تم إحداثها سنة1987    \r\n بعد إعادة تنظيم قطاع التعليم العالي والبحث العلمي في تونس.',NULL,'http://www.mes.tn/',5,4,3,'2026-06-08 10:29:16','2026-06-08 10:29:16'),(132,'Photos_MinistriesHigherEducationScientificResearch/DiXttVicOvVgjgbUrGr1NbcZYe5d2HLi8dUxykbR.jpg','وزارة الصناعة والمناجم والطاقة','energiemines','وزارة الصناعة والمناجم والطاقة  هي وزارة حكومية في الجمهورية التونسية تُعنى بوضع وتنفيذ السياسات العمومية المتعلقة بقطاعات الصناعة والمناجم والطاقة. وتضطلع بدور محوري في تطوير القطاع الصناعي، وتنظيم واستغلال الموارد المنجمية، وتنمية مصادر الطاقة التقليدية والمتجددة، بما يساهم في دعم النمو الاقتصادي وتعزيز التنافسية الوطنية.\r\nكما تعمل الوزارة على تشجيع الاستثمار الصناعي، ودعم الابتكار والتجديد التكنولوجي في المجالات الإنتاجية، وتعزيز الأمن الطاقي للبلاد، إلى جانب دعم الانتقال نحو الطاقات النظيفة والحد من الاعتماد على المصادر الأحفورية، بما ينسجم مع أهداف التنمية المستدامة.\r\nوتعود جذور هذه الوزارة إلى تطور تدريجي في الهيكلة الحكومية التونسية المرتبطة بقطاعات الصناعة والطاقة والمناجم، حيث تم توحيدها بصيغتها الحالية عبر مراحل تنظيمية مختلفة لمواكبة التحولات الاقتصادية والطاقية في البلاد.',NULL,'https://www.energiemines.gov.tn/',5,4,3,'2026-06-08 10:35:09','2026-06-08 10:35:09'),(133,'Photos_MinistriesHigherEducationScientificResearch/K8LwhFTnSp0IYqfFzrkwZhDSlo10OF4hLMZFS9Eu.png','وزارة تكنولوجيا الاتصال','mtc','وزارة تكنولوجيات الاتصال هي وزارة حكومية تتولى اقتراح السياسة العامة في مجال تكنولوجيا المعلومات والاتصال والإشراف على تنفيذها، بهدف تعزيز دور هذا القطاع في دعم التنمية الاقتصادية والاجتماعية.\r\nوتعمل الوزارة على وضع الاستراتيجية الوطنية لقطاع تكنولوجيات الاتصال ومتابعة تنفيذها، إلى جانب إعداد البرامج والإجراءات الرامية إلى تطوير هذا القطاع ودعمه. كما تسعى إلى تعزيز البنية التحتية الرقمية، وتحفيز الاستثمار في مجالات التكنولوجيا والابتكار، ودعم التحول الرقمي بما يساهم في رفع تنافسية الاقتصاد الوطني وتحسين جودة الخدمات الرقمية.',NULL,'https://www.mtc.gov.tn/',5,4,3,'2026-06-08 10:37:23','2026-06-08 10:37:23'),(134,'Photos_MinistriesHigherEducationScientificResearch/WsSR1zArhZURvnvzcnA3w60VPH6RWC1VCxHFFxrl.png','وزارة التعليم العالي والبحث العلمي','mesrs','وزارة التعليم العالي والبحث العلمي الجزائرية هي أحد وزارات الحكومة الجزائرية تشرف هذه الوزارة على قطاع التعليم العالي والجامعات والبحث العلمي في الجزائر. استحدثت هذه الوزارة لأول مرة سنة 1970، في بعض الأوقات، كانت مقسمة إلى قطاعين أو تحت وصاية وزير منتدب.',NULL,'https://www.mesrs.dz/ar',5,5,3,'2026-06-08 10:42:47','2026-06-08 10:43:01'),(135,'Photos_MinistriesHigherEducationScientificResearch/H56BbMwxRRoRjlJZMUJq10Fwia7rWMjJmQldplil.jpg','وزارة الصناعة',NULL,'وزارة الصناعة هي الجهة الحكومية المسؤولة عن تطوير القطاع الصناعي في الجزائر، حيث تشرف على إعداد وتنفيذ السياسات الصناعية الوطنية، ودعم الإنتاج المحلي، وتشجيع الاستثمار الصناعي، إلى جانب تطوير المؤسسات الصغيرة والمتوسطة.\r\n\r\nكما تعمل الوزارة على تنويع الاقتصاد الوطني وتقليل الاعتماد على قطاع المحروقات، من خلال تعزيز التصنيع، وتحسين القدرة التنافسية للمؤسسات، ودعم الابتكار والتحديث التكنولوجي داخل القطاع الصناعي.',NULL,'https://www.industrie.gov.dz/',5,5,3,'2026-06-08 11:18:48','2026-06-08 11:18:48'),(136,'Photos_MinistriesHigherEducationScientificResearch/AvNp1plQbb59GFtJnZL6IGQgkpMv0vC3hkqdv2dT.png','وزارة الطاقة والمناجم',NULL,'وزارة الطاقة والمناجم هي وزارة حكومية في الجزائر تُعنى بوضع وتنفيذ السياسات الوطنية في مجالي الطاقة والمناجم. وتشرف على استغلال وتطوير الموارد الطاقية والمعدنية، بما في ذلك المحروقات والكهرباء والغاز والموارد المنجمية، مع العمل على ضمان الأمن الطاقي وتثمين الثروات الطبيعية.\r\nكما تعمل الوزارة على تطوير قطاع الطاقة، ودعم الاستثمارات في مجالات البحث والاستكشاف والإنتاج، وتحسين كفاءة استغلال الموارد المنجمية، إضافة إلى مواكبة التحولات العالمية نحو الطاقات النظيفة وتعزيز الاستدامة الطاقية، بما يخدم التنمية الاقتصادية الوطنية.',NULL,'https://www.energy.gov.dz',5,5,3,'2026-06-08 11:26:57','2026-06-08 11:26:57'),(137,'Photos_MinistriesHigherEducationScientificResearch/TCPkbT4mcYroEWBrMll2uoryYVn0PHpk7Sra8yh1.jpg','وزارة البريد والمواصلات السلكية واللاسلكية',NULL,'وزارة البريد والمواصلات السلكية واللاسلكية هي هيئة وزارية تابعة لحكومة الجزائر تُعنى بتطوير وتنظيم قطاعات البريد والاتصالات السلكية واللاسلكية، والرقمنة. \r\nتمثل المحرك المركزي لسياسات التحول الرقمي الوطني والبنية التحتية للاتصال في البلاد.',NULL,'https://www.mpt.gov.dz/',5,5,3,'2026-06-08 11:27:58','2026-06-08 11:27:58'),(138,'Photos_MinistriesHigherEducationScientificResearch/1ttl1IKJfN2rw6iBIT6KIsgzNKqoJsYECR55wWGI.jpg','وزارة التربية الوطنية والتكوين المهني',NULL,'وزارة التربية الوطنية والتكوين المهني \r\nهي وزارة حكومية في جمهورية جيبوتي تتولى الإشراف على قطاع التربية الوطنية والتكوين المهني، وتُعد الجهة المسؤولة عن وضع وتنفيذ السياسات التعليمية في البلاد.\r\nتعمل الوزارة على تطوير منظومة التعليم الأساسي والثانوي، وتحسين جودة التعليم، وتوسيع فرص الولوج إلى التعليم لجميع الفئات، إضافة إلى الإشراف على برامج التكوين المهني بهدف إعداد وتأهيل الشباب لسوق العمل. كما تسعى إلى مواءمة مخرجات التعليم مع حاجيات التنمية الاقتصادية والاجتماعية، وتعزيز الكفاءات والمهارات المهنية بما يدعم الإدماج المهني والتشغيل.\r\nسنة التأسيس:\r\nأُنشئت الوزارة بصيغتها الحديثة بعد استقلال جيبوتي، حيث تعود بداياتها إلى سنة 1977 مع تأسيس الدولة، مع تطور مستمر في بنيتها واختصاصاتها لاحقاً.',NULL,'http://www.education.gov.dj/',5,6,3,'2026-06-08 12:52:06','2026-06-08 12:52:06'),(139,'Photos_MinistriesHigherEducationScientificResearch/4OjbLlF4PCzxfKANumCc9kSjZHWYOwnom44oV8GI.png','وزارة التعليم العالي والبحث العلمي',NULL,'وزارة التعليم العالي والبحث العلمي هي وزارة حكومية في جمهورية جيبوتي تتولى الإشراف على قطاع التعليم العالي والبحث العلمي، وتعمل على وضع السياسات الوطنية الخاصة بتطوير الجامعات ومؤسسات التعليم العالي، وتحسين جودة التكوين الجامعي، وتعزيز البحث العلمي والابتكار.\r\nكما تسعى الوزارة إلى ربط التعليم العالي بحاجيات التنمية الاقتصادية والاجتماعية، ودعم الكفاءات الوطنية، وتطوير الشراكات الأكاديمية مع المؤسسات الدولية، بما يساهم في رفع مستوى التعليم العالي في البلاد وتعزيز القدرات البحثية.',NULL,'http://www.enseignementsup.gouv.dj/',5,6,3,'2026-06-08 12:52:56','2026-06-08 12:52:56'),(140,'Photos_MinistriesHigherEducationScientificResearch/jInYobekruOR8JXkoQW14AnXdTEpAj9X9aEKgbRk.png','وزارة الاقتصاد والمالية والصناعة',NULL,'هي مؤسسة حكومية في جمهورية جيبوتي تتولى مسؤولية إعداد وتنفيذ السياسة الاقتصادية والمالية للدولة، إضافة إلى الإشراف على القطاع الصناعي وتشجيع الاستثمار.\r\n كما تلعب دورًا مهمًا في تعزيز التنمية الاقتصادية المستدامة وتنويع مصادر الدخل الوطني. وقد تم إرساء أسس هذه الوزارة منذ مرحلة ما بعد استقلال جيبوتي سنة 1977 مع تطور هيكلتها عبر الزمن لتشمل الاقتصاد والمالية والصناعة.',NULL,'https://www.economie.gouv.dj/',5,6,3,'2026-06-08 12:53:58','2026-06-08 12:53:58'),(141,'Photos_MinistriesHigherEducationScientificResearch/7VnbfJD4WZwN9wFAR6SEZ92AjPTQB2kIHWdE6Gca.png','وزارة البيئة والتنمية المستدامة',NULL,'هي وزارة حكومية مسؤولة عن حماية البيئة والحفاظ على الموارد الطبيعية في جمهورية جيبوتي، إضافة إلى وضع وتنفيذ السياسات المتعلقة بالتنمية المستدامة. تعمل الوزارة على مكافحة التصحر، وحماية التنوع البيولوجي، وإدارة التحديات البيئية مثل التغير المناخي ونقص المياه. كما تسعى إلى تحقيق توازن بين التنمية الاقتصادية والحفاظ على البيئة لضمان مستقبل مستدام للأجيال القادمة.',NULL,'https://www.environnement.gouv.dj/',5,6,3,'2026-06-08 12:54:48','2026-06-08 12:54:48'),(142,'Photos_MinistriesHigherEducationScientificResearch/XU34T2PrWzb9G96MhVwfQt7D4lyfPjBGG1pymOEz.png','وزارة الاقتصاد والمالية والصناعة في جمهورية جيبوتي',NULL,'تعمل وزارة الاقتصاد والمالية والصناعة في جمهورية جيبوتي على تنفيذ وتنسيق السياسات الاقتصادية والمالية للدولة، من خلال إدارة الموارد والأصول العامة، وضمان الاستخدام الأمثل للميزانية بما يخدم التنمية الوطنية. كما تشرف على توجيه السياسات الاقتصادية والاستراتيجيات الوطنية المتعلقة بالنمو والتنافسية والتكامل الإقليمي، إضافة إلى دعم القطاع الصناعي وتحسين مناخ الاستثمار',NULL,'https://www.ministere-finances.dj/',5,6,3,'2026-06-08 12:55:55','2026-06-08 12:55:55'),(143,'Photos_MinistriesHigherEducationScientificResearch/Yu6o7BXmVYC2q5KWc5A26eW8bDoAlUWyEe9mDoGT.jpg','وزارة التعليم العالي والبحث العلمي',NULL,'أُنشئت وزارة التعليم العالي بالمرسوم الملكي رقم 236/1 بتاريخ 8/5/1395هـ (1975م) لتتولى تنفيذ سياسة المملكة في مجال التعليم العالي، وبموجب هذا القرار أصبح وزير التعليم العالي مسؤولًا عن تنفيذ سياسة الدولة في التعليم الجامعي.\r\nوقد حظي التعليم الجامعي في المملكة بدعم كبير تمثل في إنشاء جامعات جديدة وكليات تطبيقية، إلى جانب تخصيص اعتمادات مالية كبيرة في الميزانيات، مما أسهم في توسع منظومة التعليم العالي. وقد بلغ عدد الجامعات الحكومية نحو 27 جامعة حكومية، إضافة إلى 36 جامعة وكلية أهلية، ونحو 25 معهداً موزعة على مختلف مناطق المملكة، وتضم تخصصات علمية وتطبيقية متعددة.\r\nكما تبنّت وزارة التعليم العالي توجهات حديثة في مجالات البحث العلمي والتخطيط الاستراتيجي المستقبلي، بما يواكب متطلبات التنمية الوطنية وسوق العمل.',NULL,'https://www.moe.gov.sa/',5,7,3,'2026-06-08 13:02:36','2026-06-08 13:02:36'),(144,'Photos_MinistriesHigherEducationScientificResearch/l2BxpvHXeEE6P8xO2Apv7y2lgimFWjSPDUNw45bZ.jpg','وزارة الصناعة والثروة المعدنية',NULL,'وزارة الصناعة والثروة المعدنية هي وزارة سعودية أُنشئت بأمر ملكي في 30 أغسطس 2019م، بعد أن كانت ضمن هيكلة وزارة الطاقة والصناعة والثروة المعدنية، ويشغل منصب وزيرها بندر بن إبراهيم الخريف.\r\nوتهدف الوزارة إلى تطوير قطاعي الصناعة والتعدين في المملكة، وتعزيز تنافسيتهما محليًا وعالميًا، والمساهمة في تنويع الاقتصاد الوطني ورفع مساهمتهما في الناتج المحلي الإجمالي، تماشيًا مع رؤية السعودية 2030، من خلال تنفيذ برامج ومبادرات برنامج تطوير الصناعة الوطنية والخدمات اللوجستية، إضافة إلى تنظيم وترخيص الأنشطة الصناعية والتعدينية.',NULL,'https://www.mim.gov.sa/',5,7,3,'2026-06-08 13:28:12','2026-06-08 13:28:12'),(145,'Photos_MinistriesHigherEducationScientificResearch/nr6nYCeBCpJO0pFVWQb3BN0T9jnxAu8Oq3wXE1DU.jpg','وزارة الطاقة',NULL,'وزارة الطاقة هي وزارة سعودية مسؤولة عن إدارة وتنظيم قطاع الطاقة في المملكة، وقد أعيد تنظيمها بصيغتها الحالية عام 2019م ضمن إطار إعادة هيكلة قطاع الطاقة، ويشرف عليها وزير الطاقة الأمير عبد العزيز بن سلمان بنعبد العزيز آل سعود.\r\nوتهدف الوزارة إلى تأمين واستدامة إمدادات الطاقة في المملكة، وتعزيز كفاءة إنتاج واستهلاك مصادر الطاقة المختلفة بما فيها النفط والغاز والطاقة المتجددة، كما تعمل على تنويع مزيج الطاقة ودعم التحول نحو مصادر أكثر استدامة، بما يتوافق مع مستهدفات رؤية السعودية 2030.',NULL,'https://www.moenergy.gov.sa/',5,7,3,'2026-06-08 13:29:02','2026-06-08 13:29:02'),(146,'Photos_MinistriesHigherEducationScientificResearch/IyHDzsGGlLUIZVibRZi9h8CUULUGbTNgUFTWucL0.jpg','وزارة الاقتصاد والتخطيط',NULL,'وزارة الاقتصاد والتخطيط هي وزارة سعودية أُنشئت في ستينيات القرن العشرين، وتُعد الجهة المسؤولة عن وضع السياسات الاقتصادية العامة والتخطيط التنموي الشامل في المملكة، ويشرف عليها وزير الاقتصاد والتخطيط فيصل بن فاضل الإبراهيم.\r\nوتهدف الوزارة إلى رفع كفاءة الاقتصاد الوطني وتنويعه وتقليل الاعتماد على النفط، من خلال وضع الخطط الاستراتيجية ومتابعة الأداء الاقتصادي والتنموي، ودعم تحقيق أهداف رؤية السعودية 2030، إضافة إلى تحسين مؤشرات النمو والاستدامة الاقتصادية على المدى الطويل.',NULL,'https://www.mep.gov.sa/',5,7,3,'2026-06-08 13:30:02','2026-06-08 13:30:02'),(147,'Photos_MinistriesHigherEducationScientificResearch/keg5O8IrJp7mjveUKL3V38Lygq3eYRpkXh43rnDR.png','وزارة الاتصالات وتقنية المعلومات',NULL,'تعود البدايات التأسيسية لوزارة الاتصالات وتقنية المعلومات في المملكة العربية السعودية إلى عام 1345هـ الموافق 1926م، حين أُنشئت مديرية البرق والبريد والهاتف في عهد الملك المؤسس الملك عبد العزيز بن عبد الرحمن آل سعود، لتكون اللبنة الأولى لقطاع الاتصالات والبريد في المملكة والانطلاقة المؤسسية لتنظيم خدمات الاتصال الحديثة آنذاك.',NULL,'https://mcit.gov.sa/',5,7,3,'2026-06-08 13:40:30','2026-06-08 13:40:30'),(148,'Photos_MinistriesHigherEducationScientificResearch/hmmcXeuvlSfbfA9sqd4a2hoFylQWJfKawOZ8MeRN.jpg','وزارة التعليم العالي والبحث العلمي',NULL,'وزارة التعليم العالي والبحث العلمي هي وزارة سودانية أُنشئت سنة 1992، وهي الجهة الحكومية المسؤولة عن الإشراف على قطاع التعليم العالي والبحث العلمي في السودان، بما في ذلك تنظيم الجامعات والكليات ومراكز البحث العلمي، ووضع السياسات العامة للتعليم الجامعي والدراسات العليا.\r\nوتهدف الوزارة إلى تطوير جودة التعليم العالي والارتقاء بمنظومة البحث العلمي داخل البلاد، ودعم الابتكار والإنتاج العلمي بما يخدم التنمية الاقتصادية والاجتماعية، إضافة إلى تعزيز التعاون العلمي مع المؤسسات الإقليمية والدولية، وتشجيع البحث التطبيقي وربطه باحتياجات سوق العمل في مجالات مثل الزراعة، والصناعة، والصحة، والتكنولوجيا.',NULL,'http://www.mohe.gov.sd/',5,8,3,'2026-06-08 13:46:58','2026-06-08 13:46:58'),(149,'Photos_MinistriesHigherEducationScientificResearch/Kh2i7y6ZK4ld6Rfa7LRF2mh7vUmrNCKqkBPpgXyN.jpg','وزارة الصناعة والتجارة',NULL,'وزارة الصناعة والتجارة هي وزارة سودانية مسؤولة عن تنظيم وتطوير القطاعين الصناعي والتجاري في البلاد، حيث تعمل على وضع السياسات والخطط الهادفة إلى تنمية الصناعات الوطنية وتعزيز حركة التجارة الداخلية والخارجية.\r\nوتهدف الوزارة إلى دعم الإنتاج الصناعي ورفع تنافسية المنتجات السودانية، وتشجيع الاستثمار في القطاع الصناعي، إضافة إلى تنظيم الأسواق وحماية المستهلك وتطوير الصادرات الوطنية، بما يساهم في تحقيق التنمية الاقتصادية وتنويع مصادر الدخل في السودان.',NULL,'http://www.mtic.gov.sd/',5,8,3,'2026-06-08 13:48:40','2026-06-08 13:48:40'),(150,'Photos_MinistriesHigherEducationScientificResearch/ZhTHhzk61mOOSEvz50i58He8nb2Vc6ClqIrpboaG.jpg','وزارة الطاقة والنفط',NULL,'وزارة الطاقة والنفط هي وزارة سودانية مسؤولة عن إدارة وتنظيم قطاعي الطاقة والنفط في البلاد، وتشرف على استكشاف وإنتاج وتطوير الموارد النفطية، إضافة إلى وضع السياسات المتعلقة بالطاقة والكهرباء والوقود.\r\nوتهدف الوزارة إلى تعزيز أمن الطاقة وتحقيق الاستغلال الأمثل للموارد الطبيعية، ودعم التنمية الاقتصادية من خلال تطوير الصناعات النفطية والطاقة الكهربائية والطاقة المتجددة، إلى جانب جذب الاستثمارات المحلية والأجنبية في قطاع الطاقة، وتحسين البنية التحتية المرتبطة بالإنتاج والتوزيع.',NULL,'https://www.mop.gov.sd/',5,8,3,'2026-06-08 13:50:18','2026-06-08 13:50:18'),(151,'Photos_MinistriesHigherEducationScientificResearch/7eu6yVyxH7AUtUYBjaoKHP5HKoOPYhYqzvgegqGC.png','وزارة الاتصالات والتحول الرقمي',NULL,'وزارة الاتصالات والتحول الرقمي هي الجهة الحكومية المسؤولة عن تطوير قطاع الاتصالات والتكنولوجيا الرقمية بالمغرب، وقيادة مشاريع التحول الرقمي وتحديث الإدارة العمومية والخدمات الإلكترونية.\r\n تعمل الوزارة على تعزيز البنية التحتية الرقمية، وتوسيع استخدام التقنيات الحديثة، ودعم الابتكار وريادة الأعمال الرقمية، إلى جانب تطوير الاقتصاد الرقمي وتحسين الولوج إلى الخدمات الإلكترونية لفائدة المواطنين والمقاولات. كما تسعى إلى تعزيز الأمن السيبراني وتكوين الكفاءات الرقمية بما يواكب التحولات التكنولوجية العالمية.',NULL,'http://www.mohe.gov.sy/',5,8,3,'2026-06-08 13:51:05','2026-06-08 13:51:05'),(152,'Photos_MinistriesHigherEducationScientificResearch/ueEJKVJ2q3QTgncJzLYy0UysfZbckndSwxES74MT.jpg','وزارة التعليم العالي والبحث العلمي السورية',NULL,'تُعد وزارة التعليم العالي والبحث العلمي السورية الجهة الحكومية المسؤولة عن تنظيم وتطوير التعليم الجامعي والبحث العلمي في الجمهورية العربية السورية، وقد أُنشئت عام 1966 بهدف الإشراف على الجامعات والمعاهد العليا والمشافي التعليمية ومراكز البحث العلمي. تعمل الوزارة على وضع السياسات التعليمية وتطوير البرامج الأكاديمية ودعم الابتكار والبحث العلمي، إضافة إلى تعزيز التعاون العلمي مع المؤسسات التعليمية العربية والدولية بما يسهم في إعداد الكفاءات الوطنية وخدمة التنمية في البلاد.',NULL,'http://www.mohe.gov.sy/',5,9,3,'2026-06-08 13:52:02','2026-06-08 13:52:02'),(153,'Photos_MinistriesHigherEducationScientificResearch/QjhOqE52etJRAqANs6yUe1oCJheNJKnOldq4UjmS.png','وزارة الاقتصاد والصناعة',NULL,'كما تُعد وزارة الاقتصاد والصناعة من الوزارات الاقتصادية الرئيسية في سوريا، وهي وزارة حديثة التشكيل أُنشئت عام 2025 نتيجة دمج وزارات الاقتصاد والتجارة الخارجية والصناعة والتجارة الداخلية وحماية المستهلك. تهدف الوزارة إلى إدارة السياسات الاقتصادية والصناعية والتجارية، ودعم الاستثمار والإنتاج الوطني، وتعزيز التنمية الصناعية والتحول الرقمي وتحسين بيئة الأعمال، بما يسهم في تنشيط الاقتصاد السوري ورفع القدرة التنافسية للقطاع الصناعي والتجاري.',NULL,'https://mitcp.gov.sy/',5,9,3,'2026-06-08 13:54:27','2026-06-08 13:54:27'),(154,'Photos_MinistriesHigherEducationScientificResearch/j4SRlXt5CjuQniG6vHNRwcAMBvc4oATLruITXq84.png','وزارة الكهرباء السورية الجهة الحكومية',NULL,'تُعد وزارة الكهرباء السورية الجهة الحكومية المسؤولة عن إدارة وتطوير قطاع الكهرباء في الجمهورية العربية السورية، حيث تتولى الإشراف على إنتاج ونقل وتوزيع الطاقة الكهربائية في مختلف المحافظات. تعمل الوزارة على تنفيذ مشاريع البنية التحتية الكهربائية، وصيانة الشبكات ومحطات التوليد، إضافة إلى دعم خطط التوسع في الطاقة وتحسين كفاءة الخدمات الكهربائية لتلبية احتياجات التنمية الاقتصادية والخدمية في البلاد. كما تسعى إلى تعزيز استخدام مصادر الطاقة المتجددة وتطوير التعاون الفني والاستثماري في قطاع الطاقة الكهربائية.',NULL,'https://moe.gov.sy/',5,9,3,'2026-06-08 13:55:24','2026-06-08 13:55:24'),(155,'Photos_MinistriesHigherEducationScientificResearch/7RKw5PqHc0B0iKD8WtDLzn6rqrm7Dj7FqcNuCd2h.jpg','وزارة التربية والثقافة والتعليم العالي',NULL,'وزارة التربية والثقافة والتعليم العالي في جمهورية الصومال هي وزارة حكومية تتولى الإشراف على قطاع التعليم بمختلف مستوياته، من التعليم الأساسي إلى التعليم العالي، إضافة إلى دعم الشأن الثقافي وحماية التراث الوطني. تعمل الوزارة على وضع السياسات التعليمية وتطوير المناهج وتحسين جودة التعليم في المدارس والمعاهد والجامعات، كما تسعى إلى تأهيل الكفاءات البشرية ورفع مستوى التعليم بما يخدم احتياجات سوق العمل. وتضطلع أيضاً بدور في تعزيز الهوية الثقافية ونشر المعرفة ودعم البحث العلمي.',NULL,'https://moe.gov.so/en/',5,10,3,'2026-06-08 13:56:30','2026-06-08 13:56:30'),(156,'Photos_MinistriesHigherEducationScientificResearch/kAhFTtCdQneYOTrS2iW418OyAPUkhr6QKtobYCso.png','وزارة الاتصالات والتكنولوجيا','Ministry of Communications and Technologie','وزارة الاتصالات وتكنولوجيا المعلومات في جمهورية أرض الصومال هي جهة حكومية مسؤولة عن وضع السياسات وتنظيم وتطوير قطاع الاتصالات والتقنيات الحديثة في البلاد، بهدف تعزيز البنية التحتية الرقمية وتحسين خدمات الهاتف والإنترنت ودعم التحول الرقمي. تأسست الوزارة سنة 1993 تحت اسم وزارة البريد والاتصالات، ثم تم تغيير تسميتها لاحقاً لتشمل مجالات التكنولوجيا الحديثة. وتعمل الوزارة على مواكبة التطور التقني وتشجيع الاستثمار في قطاع الاتصالات بما يساهم في تنمية الاقتصاد الوطني وتسهيل الخدمات الرقمية للمواطنين.',NULL,'https://moct.gov.so/',5,10,3,'2026-06-08 13:57:27','2026-06-08 13:59:55'),(157,'Photos_MinistriesHigherEducationScientificResearch/96vnX80sTfGFHcUkhqhxCAmFRjw3iVgCnk5A1LQ9.png','وزارة التجارة والصناعة',NULL,'وزارة التجارة والصناعة في جمهورية الصومال هي جهة حكومية مسؤولة عن تنظيم الأنشطة التجارية والصناعية داخل البلاد، ووضع السياسات والتشريعات التي تنظم الأسواق وتعزز بيئة الأعمال. تعمل الوزارة على دعم القطاع الخاص وتشجيع الاستثمارات المحلية والأجنبية، وتطوير الصناعة الوطنية لزيادة الإنتاج وتحسين الجودة. كما تسهر على مراقبة حركة الاستيراد والتصدير وحماية المستهلك من الممارسات غير القانونية. وتهدف بشكل عام إلى تنشيط الاقتصاد الوطني وتحقيق التنمية المستدامة من خلال تقوية القطاعين التجاري والصناعي.',NULL,'https://ebusiness.gov.so',5,10,3,'2026-06-08 13:59:07','2026-06-08 13:59:07'),(158,'Photos_MinistriesHigherEducationScientificResearch/8cuTqitJe146Jk47MLOLeOXjzimLFrx5CW8AWxqc.png','وزارة التعليم العالي والبحث العلمي','mohesr','إن وزارة التعليم العالي والبحث العلمي تهدف إلى إجراء تغييرات كمية ونوعية في الحركة العلمية والتقنية والثقافية في العراق، وتقوم بتوجيه المؤسسات العلمية والبحثية لتتولى عملية خلق جيل جديد مزود بالعلم والمعرفة، لتكون هذه المؤسسات قوة فاعلة ومؤثرة في المجتمع العراقي.\r\n كما تهدف الوزارة إلى تطوير العلاقات العلمية والثقافية وتوسيع العلاقات الودية في هذه المجالات مع الدول الأخرى والمنظمات العلمية والأكاديمية المختلفة في جميع أنحاء العالم من. أجل تحقيق الانسجام والتكامل في مجالات العلم والمعرفة.',NULL,'https://mohesr.gov.iq/ar/',5,11,3,'2026-06-08 14:01:01','2026-06-08 14:01:01'),(159,'Photos_MinistriesHigherEducationScientificResearch/xEM3Ei1jYHlypcWDCExYjvZ5DSEOxrTWkMoDvnDa.png','وزارة الصناعة والمعادن',NULL,'وزارة الصناعة والمعادن العراقية هي وزارة حكومية في جمهورية العراق مسؤولة عن تنظيم وتطوير القطاع الصناعي والاستخراجية غير النفطي، بما يشمل إدارة الشركات العامة الصناعية، ودعم الإنتاج المحلي، وتشجيع الاستثمار الصناعي، وتطوير البنية التحتية للصناعة الوطنية.\r\nتعمل الوزارة على تعزيز التنمية الصناعية وتنويع الاقتصاد من خلال دعم الصناعات الكيمياوية والهندسية والغذائية والدوائية والإنشائية وغيرها، إضافة إلى الإشراف على الهيئات والمراكز البحثية التابعة لها، مثل هيئة البحث والتطوير الصناعي.',NULL,'https://www.industry.gov.iq/',5,11,3,'2026-06-08 14:02:06','2026-06-08 14:02:06'),(161,'Photos_MinistriesHigherEducationScientificResearch/2NAbWwEVU1Y2aYp45K6Dqp9k7EGJWOBefQPrkbxo.png','وزارة التعليم العالي والبحث العلمي والابتكار','moheri','هي الجهة الحكومية المسؤولة عن تنظيم وتطوير منظومة التعليم العالي والبحث العلمي والابتكار في سلطنة عُمان. تعمل الوزارة على وضع السياسات والخطط التي تهدف إلى تعزيز جودة التعليم الجامعي، ودعم الأبحاث العلمية، وتشجيع الابتكار وريادة الأعمال، بما يساهم في بناء اقتصاد قائم على المعرفة.\r\nكما تسعى إلى ربط البحث العلمي باحتياجات المجتمع وسوق العمل، وتطوير الكفاءات الوطنية، وتعزيز التعاون بين الجامعات والمؤسسات البحثية والقطاعين العام والخاص، بما ينسجم مع رؤية عُمان 2040 في بناء مجتمع معرفي مبتكر ومستدام.',NULL,'https://www.moheri.gov.om/',5,12,3,'2026-06-08 14:04:29','2026-06-08 14:04:29'),(162,'Photos_MinistriesHigherEducationScientificResearch/J49UWA29I7p9TaPSUNKmKA6AbZCdQATwxfTQv3m6.png','وزارة النقل والاتصالات وتقنية المعلومات',NULL,'هي وزارة حكومية تأسست عام 2019، وتعد الجهة المسؤولة عن النقل، والاتصالات، وتقنية المعلومات، والتحول الرقمي في سلطنة عُمان. تعمل على تطوير البنية الأساسية الرقمية واللوجستية في الدولة، بما يشمل الطرق والموانئ والاتصالات، إضافة إلى قيادة برامج الحكومة الرقمية.\r\nكما تتولى الوزارة تنفيذ برنامج التحول الرقمي الحكومي، الذي يهدف إلى تحويل الخدمات الحكومية إلى خدمات إلكترونية ذكية، وتحسين كفاءة الأداء الحكومي، وتعزيز الابتكار في استخدام التقنيات الحديثة مثل الذكاء الاصطناعي والخدمات الرقمية، بما يساهم في بناء اقتصاد رقمي متطور يتماشى مع رؤية عُمان 2040.',NULL,'https://www.mtcit.gov.om/',5,12,3,'2026-06-08 14:13:50','2026-06-08 14:13:50'),(163,'Photos_MinistriesHigherEducationScientificResearch/fr2WKaW0dVTc2tsSyIlqTjUkWNVAOOsDpxD8qbe7.jpg','وزارة التجارة والصناعة وترويج الاستثمار','mociip','هي وزارة مسؤولة عن تنظيم التجارة والصناعة وجذب الاستثمارات في سلطنة عُمان، وتهدف إلى تطوير بيئة الأعمال، وتسهيل إجراءات تأسيس الشركات، ودعم القطاع الخاص، وترويج الاستثمار المحلي والأجنبي، إضافة إلى تعزيز التنافسية وتنويع الاقتصاد',NULL,'https://www.mociip.gov.om/',5,12,3,'2026-06-08 14:15:01','2026-06-08 14:16:11'),(164,'Photos_MinistriesHigherEducationScientificResearch/wr6NSBnW6idwPQk5cu8ZLsMSN6GLNjLXm6WOLi1j.png','وزارة الطاقة والمعادن','mem','تعمل الوزارة على تنظيم وتطوير قطاع الطاقة والمعادن في سلطنة عُمان، بهدف تحقيق الاستغلال الأمثل للموارد الطبيعية ضمن إطار يراعي الصحة والسلامة المهنية وحماية البيئة. كما تسعى إلى تطوير مصادر الطاقة المختلفة مثل النفط والغاز والطاقة المتجددة، إضافة إلى قطاع المعادن، بكفاءة عالية وابتكار، بما يدعم الاقتصاد الوطني ويعزز استدامته.\r\nوترتكز رؤية الوزارة على تطوير واستغلال مصادر الطاقة والمعادن بطرق حديثة وفعالة تسهم في دعم النمو الاقتصادي. أما رسالتها فتركز على تنظيم وتنمية هذا القطاع الحيوي بما يضمن الاستخدام الأمثل للثروات الوطنية.',NULL,'https://www.mem.gov.om/',5,12,3,'2026-06-08 14:15:56','2026-06-08 14:16:21'),(165,'Photos_MinistriesHigherEducationScientificResearch/2B2lP5wohXH5YNgiA9nHgqMV4Sz8ePOQDAoU8iZ3.jpg','وزارة التربية والتعليم العالي','moe','نشأت وزارة التربية والتعليم العالي بعد تسلم السلطة الوطنية الفلسطينية، مهام التعليم في فلسطين عام 1994.\r\n وفي عام 1996 أنيطت صلاحيات التعليم العالي بوزارة جديدة حملت اسم وزارة التعليم العالي والبحث العلمي، فيما ظلت الوزارة الأم تحمل اسم وزارة التربية والتعليم. وفي تعديل وزاري على الحكومة الفلسطينية عام 2002 تم إعادة دمج الوزارتين في وزارة واحدة حملت اسم وزارة التربية والتعليم العالي.',NULL,'https://www.moe.edu.ps/',5,13,3,'2026-06-08 14:17:36','2026-06-08 14:17:52'),(167,'Photos_MinistriesHigherEducationScientificResearch/JIIXfW8RmyjwwW7ez89oCjd2m9ozt7NVEcu8K8HT.png','وزارة الصناعة – دولة فلسطين','palgov','تُعد وزارة الصناعة الجهة الحكومية المسؤولة عن تطوير وتنظيم القطاع الصناعي في دولة فلسطين، حيث تعمل على تعزيز القدرة التنافسية للصناعات الوطنية، ودعم الاستثمار الصناعي، وتحسين جودة المنتجات الفلسطينية بما يتوافق مع المعايير الدولية. كما تسعى الوزارة إلى تشجيع الابتكار والتكنولوجيا الصناعية، وتوفير بيئة أعمال ملائمة لنمو المنشآت الصناعية، بما يساهم في تحقيق التنمية الاقتصادية المستدامة وخلق فرص العمل.',NULL,'https://www.mind.gov.ps/',5,13,3,'2026-06-08 14:20:06','2026-06-08 14:22:13'),(168,'Photos_MinistriesHigherEducationScientificResearch/bxH9V0E0Mq0GPZ1H3GrQXwerr8RvJuUpNrnFVtIP.png','وزارة التربية والتعليم والتعليم العالي',NULL,'تُشرف الوزارة على تطوير منظومة التعليم والتعليم العالي في دولة قطر، وتعمل على رفع جودة التعليم والبحث العلمي، وتعزيز الابتكار وتنمية الكفاءات الوطنية. كما تسعى إلى بناء نظام تعليمي متطور يدعم الاقتصاد القائم على المعرفة ويواكب متطلبات التنمية المستدامة ورؤية قطر الوطنية 2030.',NULL,'https://www.edu.gov.qa/ar/',5,14,3,'2026-06-08 14:23:57','2026-06-08 14:23:57'),(169,'Photos_MinistriesHigherEducationScientificResearch/yKj2BamGFn9g6vdM0i1azvnV0AIsY0Plmcpzvv5Q.png','وزارة التجارة والصناعة',NULL,'تُعد وزارة التجارة والصناعة الجهة الحكومية المسؤولة عن تنظيم وتطوير الأنشطة التجارية والصناعية في دولة قطر، وتهدف إلى تعزيز بيئة الأعمال وجذب الاستثمارات المحلية والأجنبية بما يدعم النمو الاقتصادي المستدام. تعمل الوزارة على وضع وتنفيذ السياسات والتشريعات المتعلقة بالتجارة والصناعة، وتطوير القطاع الخاص، وحماية المستهلك، وتعزيز التنافسية والابتكار في مختلف القطاعات الاقتصادية. كما تسهم في دعم التنويع الاقتصادي وتشجيع الصناعات الوطنية وريادة الأعمال، بما ينسجم مع أهداف رؤية قطر الوطنية 2030 الرامية إلى بناء اقتصاد متنوع قائم على المعرفة والاستدامة.',NULL,'https://www.moci.gov.qa/',5,14,3,'2026-06-08 14:25:11','2026-06-08 14:25:11'),(170,'Photos_MinistriesHigherEducationScientificResearch/wdOqOaps9xjbrZwWVQWWLqhuWvWZqDbQq41SdJDc.png','وزارة الاتصالات وتكنولوجيا المعلومات',NULL,'تُعد الوزارة الجهة المسؤولة عن قيادة التحول الرقمي في دولة قطر، وتطوير البنية التحتية الرقمية، وتعزيز الأمن السيبراني، وتمكين الاقتصاد الرقمي. كما تعمل على تسريع تبني التقنيات الحديثة والذكاء الاصطناعي، وتطوير الخدمات الحكومية الرقمية، ودعم الابتكار التكنولوجي بما يعزز مكانة قطر كمركز رقمي متقدم في المنطقة.',NULL,'https://www.mcit.gov.qa/',5,14,3,'2026-06-08 14:26:02','2026-06-08 14:26:02'),(172,'Photos_MinistriesHigherEducationScientificResearch/HW4LCkDcYckEYcObUoMWdz7QJpIqfITpHveVho4a.png','وزارة التعليم العالي',NULL,'وزارة التعليم العالي – دولة الكويت هي الجهة الحكومية المسؤولة عن الإشراف على التعليم العالي والابتعاث وتنمية الكفاءات الوطنية، وقد تأسست عام 1988.\r\nوتعمل الوزارة على توفير فرص التعليم والتخصص في مختلف المجالات العلمية والإنسانية، ودعم البحث العلمي وإعداد الموارد البشرية المؤهلة بما يخدم التنمية الوطنية.',NULL,'https://www.mohe.edu.kw/',5,15,3,'2026-06-08 14:28:05','2026-06-08 14:28:05'),(173,'Photos_MinistriesHigherEducationScientificResearch/jAfiVAospcGNU8NTxGpn1YWZoydbGixyvurf5s4O.jpg','وزارة التجارة والصناعة',NULL,'وزارة التجارة والصناعة – دولة الكويت هي الجهة الحكومية المسؤولة عن تنظيم ودعم الأنشطة التجارية والصناعية والاقتصادية في الدولة. \r\nتعود نشأتها الى عام 1963\r\nتحت اسم وزارة التجارة، ثم أصبحت وزارة التجارة والصناعة عام1965.\r\n تعمل الوزارة على تطوير\r\n بيئة الأعمال، وتشجيع الاستثمار، وتوفير السلع والخدمات، وتعزيز النمو الاقتصادي والتنافسية بما يدعم التنمية المستدامة في دولة الكويت.',NULL,'https://www.moci.gov.kw/',5,15,3,'2026-06-08 14:29:00','2026-06-08 14:29:00'),(177,'Photos_MinistriesHigherEducationScientificResearch/Lzm12kbTqyVSTfEDJtaWfJQBWl0tnBjS4APciaSy.jpg','وزارة الصــناعة',NULL,'تأسست وزارة الصناعة عام 1993، وتُعنى بتطوير القطاع الصناعي اللبناني وتعزيز تنافسيته، ودعم الاستثمار والإنتاج الصناعي، وتشجيع الابتكار والتكنولوجيا الصناعية بما يساهم في النمو الاقتصادي وخلق فرص العمل.',NULL,'https://www.industry.gov.lb/',5,16,3,'2026-06-08 14:34:34','2026-06-08 14:34:34'),(179,'Photos_MinistriesHigherEducationScientificResearch/bHnKK45rDv2MHdtKHF29a70Nz613itpYfDC82SIE.png','وزارة التعليم العالي والبحث العلمي','mhesr','استُحدِثت وزارة التعليم العالي والبحث العلمي بقرار من مجلس وزراء حكومة الوحدة الوطنية رقم (39) لسنة 2021م بشأن اعتماد الهيكل التنظيمي وتحديد اختصاصات وزارة التعليم العالي والبحث العلمي، لتتولى تنفيذ سياسة الدولة في التعليم العالي. وبموجب القرار المذكور تمت تسمية السيد/ د. عمران محمد القيب كوزيرٍ للتعليم العالي والبحث العلمي.',NULL,'https://mhesr.gov.ly/',5,17,3,'2026-06-08 14:41:11','2026-06-08 14:41:11'),(180,'Photos_MinistriesHigherEducationScientificResearch/osvlyVpn5JiBhQNjGXGJwnlL0ZnSFLAziO49fQJ2.png','وزارة الصناعة والمعادن',NULL,'وزارة الصناعة والمعادن إحدى الوزارات التابعة لحكومة الوحدة الوطنية، والمسؤولة عن تطوير وتنظيم القطاع الصناعي في ليبيا، حيث تقوم بتحديد السياسات والاستراتيجيات الصناعية، ووضع الأهداف وتطوير التشريعات اللازمة لرفع كفاءة القطاع وتحقيق التنمية المستدامة.\r\n تسعى الوزارة إلى تعزيز الاقتصاد الوطني من خلال دعم المشروعات الصناعية الصغرى والمتوسطة، وتوفير بيئة تشجع على الابتكار والإبداع، مما يساهم في خلق فرص العمل وزيادة الإنتاج المحلي.',NULL,'https://www.industry.gov.ly/',5,17,3,'2026-06-08 14:42:04','2026-06-08 14:42:04'),(182,'Photos_MinistriesHigherEducationScientificResearch/7JELUEQFh5MdVX0RwdVaMOCnjjVj32esurXgLIkJ.png','وزارة الاتصالات والمعلوماتية',NULL,'وزارة الاتصالات والمعلوماتية تعنى بشؤون الاتصالات وتقنية المعلومات وتمثل أعلى سلطة مسؤولة عن قطاع الاتصالات في ليبيا. نسعى إلى تحقيق التحول الرقمي في جميع قطاعات الدولة، وتطوير البنية التحتية الرقمية، وتعزيز الابتكار في مجال الاتصالات وتقنية المعلومات، وتوفير خدمات رقمية متقدمة للمواطنين والمقيمين.',NULL,'https://www.gacily.com/',5,17,3,'2026-06-08 14:43:46','2026-06-08 14:43:46'),(183,'Photos_MinistriesHigherEducationScientificResearch/PatYN6LGesJq37W4zaZvMuHEok0W2UzvacxFBtOR.png','وزارة التعليم العالي والبحث العلمي','mohesr','وزارة التعليم العالي والبحث العلمي هي الجهة الحكومية المسؤولة عن تطوير منظومة التعليم العالي والبحث العلمي في مصر، وقد تأسست عام 1961.\r\n تعمل الوزارة على دعم الجامعات والمراكز البحثية، وتعزيز الابتكار والتطوير التكنولوجي، وإعداد الكوادر العلمية المؤهلة بما يواكب متطلبات التنمية الوطنية.',NULL,'https://mohesr.gov.eg/ar/',5,18,3,'2026-06-08 14:44:58','2026-06-08 14:44:58'),(184,'Photos_MinistriesHigherEducationScientificResearch/8YuQk9pkXkzjRNxPeujJSjRlt7OPUYLwQ871LNXl.png','وزارة الصناعة المصرية',NULL,'وزارة الصناعة هي الجهة الحكومية المسؤولة عن تنمية وتطوير القطاع الصناعي في جمهورية مصر العربية، من خلال إعداد وتنفيذ السياسات والاستراتيجيات الصناعية الهادفة إلى تعزيز الإنتاج والتصنيع المحلي ورفع القدرة التنافسية للصناعة المصرية.\r\nوتعمل الوزارة على تشجيع الاستثمار الصناعي، وتوطين التكنولوجيا الحديثة، وتطوير المناطق الصناعية، ودعم المشروعات الصغيرة والمتوسطة، بما يسهم في زيادة الصادرات الصناعية وتوفير فرص العمل وتحقيق التنمية الاقتصادية المستدامة. كما تضطلع بدور محوري في تعزيز الابتكار الصناعي وتحسين بيئة الأعمال، بما يدعم رؤية مصر للتنمية الاقتصادية الشاملة.\r\nسنة التأسيس: تعود جذور الوزارة إلى بدايات التنظيم الحكومي للقطاع الصناعي بعد ثورة 1952، بينما تشكلت الوزارة بمسمياتها واختصاصاتها الحالية عبر عدة عمليات إعادة هيكلة حكومية متعاقبة.',NULL,'https://mind.gov.eg/',5,18,3,'2026-06-08 14:47:20','2026-06-08 14:47:20'),(186,'Photos_MinistriesHigherEducationScientificResearch/X44K3sXcN1qwZfIcXW3FD05wmpUsG3Fa1h30Olzk.png','وزارة الاتصالات وتكنولوجيا المعلومات',NULL,'هيئة تنمية صناعة تكنولوجيا المعلومات (إيتيدا) هي هيئة حكومية تأسست عام 2004 وتتبع وزارة الاتصالات وتكنولوجيا المعلومات.\r\n تعمل على تنمية قطاع تكنولوجيا المعلومات والاتصالات، ودعم الابتكار وريادة الأعمال الرقمية، وتعزيز صادرات الخدمات التكنولوجية، وبناء القدرات الرقمية للشباب والشركات.',NULL,'https://mcit.gov.eg/',5,18,3,'2026-06-08 14:49:52','2026-06-08 14:49:52'),(187,'Photos_MinistriesHigherEducationScientificResearch/Po8Ncq2zA68aKJp1v8hWHhdGcNgqhVWipjmZPG1X.png','وزارة التعليم العالي والبحث العلمي',NULL,'وزارة التعليم العالي والبحث العلمي هي الجهة الحكومية المسؤولة عن تطوير منظومة التعليم العالي والبحث العلمي في موريتانيا. وتعمل الوزارة على إعداد وتنفيذ السياسات الوطنية المتعلقة بالتعليم الجامعي والبحث العلمي، بما يسهم في الارتقاء بجودة التكوين الأكاديمي وتعزيز مساهمة الجامعات في التنمية الوطنية.\r\nكما تسعى الوزارة إلى دعم البحث العلمي والابتكار، وتطوير مؤسسات التعليم العالي، وتشجيع التعاون العلمي والأكاديمي، وإعداد الكفاءات الوطنية المؤهلة القادرة على الاستجابة لمتطلبات التنمية الاقتصادية والاجتماعية، وتعزيز اقتصاد المعرفة وبناء مجتمع قائم على العلم والتكنولوجيا.\r\nسنة التأسيس: تعود جذور الإشراف الحكومي على التعليم العالي في موريتانيا إلى سبعينيات القرن العشرين، بينما تشكلت الوزارة بمسمياتها واختصاصاتها الحالية عبر عدة عمليات إعادة هيكلة حكومية متعاقبة.',NULL,'https://www.mesrs.gov.mr/',5,20,3,'2026-06-08 14:53:29','2026-06-08 14:53:29'),(188,'Photos_MinistriesHigherEducationScientificResearch/t1QkXbMpjpEmk4xQ4k20nt82MLI57DmSDgokfONF.png','وزارة التحول الرقمي وعصرنة الإدارة',NULL,'وزارة التحول الرقمي وعصرنة الإدارة هي الجهة الحكومية المسؤولة عن قيادة التحول الرقمي في موريتانيا، وقد أُنشئت عام 2022. تعمل الوزارة على تطوير البنية التحتية الرقمية، وتحديث الإدارة العمومية، وتعزيز الحكومة الإلكترونية، وتحسين جودة الخدمات الرقمية المقدمة للمواطنين والمؤسسات.',NULL,'https://mtnima.gov.mr/',5,20,3,'2026-06-08 14:54:36','2026-06-08 14:54:36'),(189,'Photos_MinistriesHigherEducationScientificResearch/c7HuyGSenuk5cHqV1xvoFeGPDBpBhWxmEkrslCQY.png','وزارة المعادن والصناعة',NULL,'وزارة المعادن والصناعة (موريتانيا) هي وزارة حكومية موريتانية تعود جذورها إلى مرحلة ما بعد الاستقلال سنة 1960، وتتولى تطوير وتنظيم القطاعين الصناعي والتعديني. تعمل على تشجيع الاستثمار، وتعزيز القيمة المضافة للموارد الطبيعية، وتطوير الصناعات الوطنية، ودعم الاستغلال المستدام للثروات المعدنية بما يسهم في تحقيق النمو الاقتصادي والتنمية المستدامة.',NULL,'https://www.mines.gov.mr/',5,20,3,'2026-06-08 14:56:12','2026-06-08 14:56:12'),(191,'Photos_MinistriesHigherEducationScientificResearch/oDFqWilTWBDRE6p91T3LvLvLGgWPsCFnag0Fspkn.jpg','وزارة التعليم العالي والبحث العلمي والتعليم الفني والتدريب المهني',NULL,'وزارة التعليم العالي والبحث العلمي والتعليم الفني والتدريب المهني (اليمن) هي وزارة حكومية يمنية تعود جذورها إلى إنشاء وزارة التعليم العالي والبحث العلمي عام 1990م، بينما أُنشئت وزارة التعليم الفني والتدريب المهني عام 2001م، وتم جمع اختصاصاتهما ضمن الهيكلة الحكومية الحالية. وتتولى الوزارة الإشراف على مؤسسات التعليم العالي والبحث العلمي والتعليم الفني والتدريب المهني، وتعمل على تطوير جودة التعليم، ودعم البحث العلمي والابتكار، وتأهيل الكفاءات الوطنية، ومواءمة مخرجات التعليم مع احتياجات سوق العمل بما يسهم في تحقيق التنمية المستدامة.',NULL,'https://www.mohe-ye.org/',5,21,3,'2026-06-08 14:59:05','2026-06-08 14:59:05'),(192,'Photos_MinistriesHigherEducationScientificResearch/dibQ6huOoEhd0Nb8A9717VBzo3bzmRQJmXKoq1Dv.jpg','وزارة الاتصالات وتقنية المعلومات',NULL,'وزارة الاتصالات وتقنية المعلومات (اليمن) هي وزارة حكومية يمنية أُنشئت سنة 2001م، وتتولى الإشراف على قطاع الاتصالات وتقنية المعلومات وتطويره. وتعمل الوزارة على تعزيز البنية التحتية الرقمية، وتطوير خدمات الاتصالات والإنترنت، ودعم مشاريع التحول الرقمي والحكومة الإلكترونية، وتشجيع استخدام التقنيات الحديثة في مختلف القطاعات، بما يسهم في تحسين الخدمات وتعزيز التنمية الاقتصادية والاجتماعية في الجمهورية اليمنية.',NULL,'https://www.moit.gov.ye/',5,21,3,'2026-06-08 15:00:26','2026-06-08 15:00:26'),(193,NULL,'وزارة الصناعة والتجارة',NULL,'وزارة الصناعة والتجارة (اليمن) هي وزارة حكومية يمنية تعود جذورها إلى قيام الجمهورية اليمنية سنة 1990م، وتتولى وضع وتنفيذ السياسات المتعلقة بالصناعة والتجارة. وتعمل على تطوير القطاع الصناعي، وتشجيع الاستثمار والإنتاج المحلي، وتنظيم الأنشطة التجارية، وحماية المستهلك، وتعزيز الصادرات، بما يسهم في دعم النمو الاقتصادي وتحقيق التنمية المستدامة في الجمهورية اليمنية.',NULL,NULL,5,21,3,'2026-06-08 15:03:00','2026-06-08 15:03:00'),(194,'Photos_IndustrialPropertyPatentOffices/bs92g1BjHrgKaCRmo0yQ5aPg86iQ0HU7nXPLU8O7.jpg','وزارة الصناعة و التجارة /مديرية الملكية الفكرية','null','براءات الاختراع و العلامات التجارية و حق التصاميم الصناعية.\r\nالمقر :عمان',NULL,'https://www.mit.gov.jo',6,1,4,'2026-06-09 10:59:14','2026-06-09 11:18:34'),(196,'Photos_IndustrialPropertyPatentOffices/g0Q0LiL1ohl0DCUVavIGjHpSp0jVgoPBUWiUwzFh.png','وزارة الاقتصاد /ادارة تنمية الابتكار و الملكية الصناعية',NULL,'براءات الاختراع و النماذج الصناعية و العلامات التجارية.\r\nالمقر : ابو ظبي',NULL,'https://www.economy.gov.ae',6,2,4,'2026-06-09 11:42:04','2026-06-09 11:42:04'),(197,'Photos_IndustrialPropertyPatentOffices/9TElacZhzK78lyshHEDmTnKXZA1muq2uNpeehSVT.jpg','وزارة الصناعة والتجارة /وحدة الملكية الفكرية.',NULL,'وزارة الصناعة والتجارة /وحدة الملكية الفكرية.\r\nالمقر :المنامة.\r\nالاهداف :حماية حقوق الملكية الفكرية و براءات الاختراع و حق الملكية و العلامات التجارية و حق التصاميم',NULL,': https://www.moic.gov.bh',6,3,4,'2026-06-09 12:25:53','2026-06-09 12:25:53'),(198,'Photos_IndustrialPropertyPatentOffices/cYF5hOgP98g2yMoa2XKEw7qPVTIzYgYS1Jb4KI0j.jpg','المعهد الوطني للتقيس و الملكية الصناعية','null','الجهة المختصة :المعهد الوطني للتقيس و الملكية الصناعية وهو موسسة عمومية ذات طابع صناعي و تجاري.\r\nالمقر : تونس\r\nالخدمات: حماية براءات الاختراع والعلامات التجارية و التصاميم الصناعية و التقيس و الجودة.',NULL,': https://www.innorpi.tn',6,4,4,'2026-06-09 12:33:21','2026-06-09 12:38:06'),(199,'Photos_IndustrialPropertyPatentOffices/BE2zlJGQAEokpZlIJKc7MLF6lxr5nVNFaJ6tTKqY.png','المعهد الوطني الجزائري للملكية الصناعية','null','المعهد الوطني الجزائري للملكية الصناعية هو مؤسسة عمومية تحت وصاية وزارة الصناعة .\r\nالمقر : العاصمة الجزائر .\r\nالخدمات :حماية الملكية الصناعية و براءات الاختراع و النماذج الصناعية و العلامات التجارية',NULL,'https://www.inapi.org',6,5,4,'2026-06-09 12:44:35','2026-06-09 12:47:35'),(200,'Photos_IndustrialPropertyPatentOffices/73hAlIwVv0JhLmGZj8WZutxrys6b3g8yyNGpUPlF.png','وزارة التجارة والصناعة /المكتب الجيبوتي للملكية الصناعية والتجارية (ODPIC)','null','المكتب الجيبوتي للملكية الصناعية والتجارية (ODPIC)\r\nالمقر :جيبوتي .\r\nالخدمات : حماية براءات الاختراع و العلامات التجارية و الملكية .',NULL,'https://odpic.dj/',6,6,4,'2026-06-09 13:25:06','2026-06-09 13:25:15'),(201,'Photos_IndustrialPropertyPatentOffices/44GplGRB7UxrDK08xm6kTPJpqfTIluYK9kVhE7Di.jpg','الهيئة السعودية للملكية الفكرية (SAIP)','null','الهيئة السعودية للملكية الفكرية (SAIP) مرتبطة  تنظيمياً بـ رئيس مجلس الوزراء. وهي تتمتع بالشخصية الاعتبارية العامة والاستقلال المالي والإداري.\r\nالمقر : الرياض- المملكة السعودية.\r\nالخدمات :تسجيل و متابعة وحماية العلامات التجارية و الملكية الفكرية و النمازج الصناعية.',NULL,'https://www.saip.gov.sa',6,7,4,'2026-06-09 13:36:59','2026-06-09 13:38:23'),(202,'Photos_IndustrialPropertyPatentOffices/CjlH5119DKVx5APMxMG3T5ZnubwMVwk8vWf0GCz1.png','المسجل العام لإدارة الملكية الصناعية',NULL,'المسجل العام لإدارة الملكية الفكرية تُدار الملكية الصناعية في السودان عبر المسجل العام لإدارة الملكية الفكرية التابع لـ وزارة العدل السودانية.\r\nالمقر :العاصمة السودانية الخرطوم.\r\nالخدمات :تسجيل و متابعة و حماية العلامات التجارية وبراءات الاختراع والنماذج الصناعية .',NULL,'https://www.moj.gov.sd/posts/post/224',6,8,4,'2026-06-09 13:52:54','2026-06-09 13:52:54'),(203,'Photos_IndustrialPropertyPatentOffices/yveT1JlQPl7DYaTSrdjzFN4X2QRQMVG9lAaTquoX.png','مكتب الملكية الصناعية','null','مديرية حماية الملكية التجارية والصناعية، والتي تتبع إدارياً لـ وزارة التجارة الداخلية وحماية المستهلك.\r\nالمقر :العاصمة دمشق، سوريا.\r\nالخدمات :تسجيل و متابعة و حماية براءات الاختراع والعلامات التجارية و النماذج الصناعية و النشر الرسمي في جريدة حماية الملكية الصناعية و التجارية .',NULL,'http://dcip.gov.sy/disarticle.php?id=96',6,9,4,'2026-06-09 14:06:28','2026-06-09 14:13:26'),(204,'Photos_ScientificResearchInnovationCenters/uFPT8QSpSNuzNZ5Ymg6WsiJGaxV9YwfstPm2lQLe.png','أكاديمية البحث العلمي والتكنولوجيا',NULL,'أكاديمية البحث العلمي والتكنولوجيا هي الهيئة الوطنية المعنية بدعم وتمويل البحث العلمي والابتكار في مصر، وقد تأسست عام 1971.\r\n تعمل الأكاديمية على رعاية الباحثين والمبتكرين، وتمويل المشروعات البحثية، وتعزيز التعاون العلمي والتكنولوجي، وربط البحث العلمي باحتياجات التنمية والاقتصاد الوطني.',NULL,'http://www.asrt.sci.eg/',5,18,1,'2026-06-09 14:08:43','2026-06-09 14:08:43'),(205,'Photos_ScientificResearchInnovationCenters/NFyZvtTGSnIIdA44Hs0Mo19ib9DvzY7PoSn128yH.png','الهيئة الليبية للبحث العلمي',NULL,'أسست الهيئة سنة 1978م لغرض تنفيذ مخططات الدولة الاستراتيجية من خلال اتّباع منهجية البحث العلمي، وتعبئة جهود العلماء والباحثين والخبراء والمخترعين في مختلف المجالات.\r\n     وتقوم الهيئة بمتابعة واجباتها المتمثلة في إدارة ومتابعة البحوث والدراسات في المراكز البحثية التابعة لها ذات الاختصاصات في شتى مجالات البحث العلمي، وذلك من خلال اعتماد الخطط والبرامج البحثية، وتقديم الدعم المادي، وإعداد وتوثيق التقارير العلمية، والمتابعة الدورية للأبحاث والدراسات والتطوير العلمي.',NULL,'https://www.aonsrt.ly/',5,17,1,'2026-06-09 14:10:40','2026-06-09 14:10:40'),(206,'Photos_ScientificResearchInnovationCenters/CakwW3rQeOOW2QqNbJdvoT4PBW5TeYAF4r5zBnum.png','مؤسسة الكويت للتقدم العلمي',NULL,'مؤسسة وطنية تدعم البحث العلمي والابتكار والتطوير التكنولوجي في دولة الكويت، من خلال تمويل المشاريع البحثية، وتشجيع الإبداع العلمي، وبناء القدرات الوطنية في مجالات العلوم والتكنولوجيا.\r\n كما تعمل على نشر الثقافة العلمية وتعزيز اقتصاد المعرفة والتنمية المستدامة.',NULL,'https://www.kfas.org/',5,15,1,'2026-06-09 14:12:01','2026-06-09 14:12:01'),(207,'Photos_ScientificResearchInnovationCenters/xzhYyncZUBtVCxxlTcY1gblTyPHXs0ulMdwGWBUm.png','معهد الكويت للأبحاث العلمية',NULL,'يُعد من أبرز المؤسسات البحثية في دولة الكويت، ويختص بإجراء الدراسات والأبحاث العلمية والتطبيقية في مجالات الطاقة والمياه والبيئة والتكنولوجيا. ويسهم المعهد في دعم الابتكار ونقل المعرفة العلمية وتطوير الحلول التقنية التي تخدم التنمية الاقتصادية والاجتماعية في الدولة.',NULL,'https://www.kisr.edu.kw/',5,15,1,'2026-06-09 14:13:15','2026-06-09 14:13:15'),(208,'Photos_ScientificResearchInnovationCenters/D9Ob3cHeo4vI1Doty0SpjXQed15JQUhg4YZFjGxD.png','المجلس الوطني للبحوث العلمية',NULL,'المجلس الوطني للبحوث العلمية هو المؤسسة الوطنية الرئيسية المعنية بدعم وتطوير البحث العلمي والابتكار في لبنان، وقد تأسس عام 1962.\r\nيتمتع المجلس باستقلالية إدارية ومالية ويعمل تحت إشراف رئاسة مجلس الوزراء، حيث يتولى وضع السياسات الوطنية للبحث العلمي وتنسيق البرامج البحثية وتمويل المشاريع العلمية، إضافة إلى دعم الابتكار وتعزيز التعاون بين المؤسسات الأكاديمية والبحثية بما يخدم التنمية المستدامة والاقتصاد القائم على المعرفة.',NULL,'https://cnrs.edu.lb/',5,16,1,'2026-06-09 14:14:11','2026-06-09 14:14:11'),(209,NULL,'مجلس قطر للبحوث والتطوير والابتكار',NULL,'مجلس قطر للبحوث والتطوير والابتكار هو هيئة وطنية تأسست عام 2018 بهدف تعزيز منظومة البحث العلمي والتطوير والابتكار في دولة قطر. يعمل المجلس على وضع وتنفيذ الاستراتيجيات والسياسات التي تدعم الابتكار وتطوير المعرفة، وتسهم في تحقيق أهداف التنمية الاقتصادية والاجتماعية للدولة. كما أطلق استراتيجية قطر للبحوث والتطوير والابتكار 2030 بهدف بناء اقتصاد قائم على المعرفة وتعزيز التعاون بين الجهات الحكومية والمؤسسات الأكاديمية وقطاع الأعمال، بما يدعم التقدم العلمي والتكنولوجي ويواكب رؤية قطر الوطنية 2030.',NULL,'https://www.qrdi.org.qa/',5,14,1,'2026-06-09 14:16:29','2026-06-09 14:16:29'),(211,'Photos_ScientificResearchInnovationCenters/uHkdq2ClDbCFZv4gKJJo7PKTl0IH6sVClsfC3BGE.png','هيئة البحث والتطوير الصناعي',NULL,'تأسست هيئة البحث والتطوير الصناعي في العراق عام 1994 ضمن وزارة الصناعة والمعادن، وهي جهة مختصة بدعم البحث العلمي والتطوير الصناعي في مختلف القطاعات مثل الصناعات الكيمياوية والهندسية، والغذائية، والدوائية، وغيرها.\r\n تهدف إلى تعزيز الابتكار وتطوير التكنولوجيا وبناء شراكات تدعم توطين الصناعة وتحقيق التنمية المستدامة، وقد حصلت على عدة شهادات جودة دولية مثل ISO 9001 وISO/IEC 17025 وGMP لمراكزها البحثية',NULL,'https://www.crid.industry.gov.iq/',5,11,1,'2026-06-09 14:19:55','2026-06-09 14:19:55'),(212,'Photos_ScientificResearchInnovationCenters/ucuQjnnW9ddb4DTds3YlUuHz5ZGTjkYlNBTisGzz.png','هيئة المعلومات والحكومة الإلكترونية',NULL,'هيئة المعلومات والحكومة الإلكترونية هي الجهة الحكومية المسؤولة عن قيادة التحول الرقمي في مملكة البحرين. وتتمثل مهامها في وضع وتنفيذ استراتيجيات التحول الرقمي للخدمات الحكومية، واقتراح التشريعات والسياسات والمعايير الرقمية. وتقوم الهيئة بتطوير الخدمات الحكومية والأنظمة الوطنية بالتعاون مع الجهات الحكومية المختلفة. بالإضافة إلى ذلك، تعمل الهيئة على تطوير البنية التحتية الرقمية، وقيادة انتقال المملكة إلى الحوسبة السحابية، وإدارة العمليات المتعلقة بالشبكة الحكومية، وحوكمة تقنية المعلومات في القطاع الحكومي.	\r\n\r\n\r\nhttps://www.iga.gov.bh/\r\n	هيئة المعلومات والحكومة الإلكترونية',NULL,'https://www.iga.gov.bh/',5,3,1,'2026-06-09 14:21:52','2026-06-09 14:21:52'),(214,'Photos_ScientificResearchInnovationCenters/MMhJpcvsZRLZDrsNZGnPxeQ866RSXh4qFC2T7Zqt.png','الجمعية العلمية الملكية','Royal Scientific Society - RSS','الجمعية العلمية الملكية مؤسسة بحثية وطنية رائدة في المملكة الأردنية الهاشمية، تُعنى بتطوير العلوم والتكنولوجيا وتقديم الاستشارات والخدمات الفنية والصناعية للقطاعين العام والخاص. وقد تأسست سنة 1970 بمبادرة من المغفور له الملك الحسين بن طلال، وتُعتبر اليوم أكبر مركز للبحوث التطبيقية والدعم التقني في الأردن.',NULL,'https://www.rss.jo/Default/En',5,1,1,'2026-06-09 14:24:00','2026-06-09 14:24:00'),(215,'Photos_ScientificResearchInnovationCenters/yueK1xl43aK7jmYeQPFjvtAIs0krlIzj0c5z0FSB.png','المجلس الأعلى للعلوم والتكنولوجيا',NULL,'أنشئ “المجلس الأعلى للعلوم والتكنولوجيا” في عام 1987 بموجب القانون رقم (30) كمؤسسة عامة مستقلة، تعمل كمظلة وطنية لجميع انشطة العلوم والتكنولوجيا في الأردن. \r\nتم إنشاء المجلس بهدف بناء قاعدة علمية وتكنولوجية وطنية تسهم في تحقيق الأهداف التنموية، وذلك من خلال زيادة الوعي بأهمية البحث العلمي والتطوير، وتقديم الدعم المالي المناسب له، وتوجيه النشاط العلمي والبحثي ضمن أولويات وطنية تنسجم مع التوجهات التنموية.',NULL,'https://www.hcst.gov.jo/?q=ar',5,1,1,'2026-06-09 14:25:08','2026-06-09 14:25:08'),(216,'Photos_IndustrialPropertyPatentOffices/VwNfCjQseT4MUbnDRvlu4PZYz7HkLdbuqBYyeiN1.png','مكتب الملكية الصناعية الصومال',NULL,'المكتب المسؤول عن الملكية الصناعية في الصومال هو قسم التطوير الصناعي (إدارة العلامات التجارية وبراءات الاختراع) التابع لـ وزارة التجارة والصناعة بجمهورية الصومال الفيدرالية.\r\nالمقر : مقديشو\r\nالخدمات:تسجيل و متابعة و حماية العلامات التجارية و الملكية الصناعية و الفكرية و فحص وتوثيق وحماية الشعارات والأسماء التجارية والرموز الخاصة بالشركات المحلية والأجنبيةنشر وتلقي الاعتراضات .',NULL,'https://moci.gov.so/',6,10,4,'2026-06-09 14:35:04','2026-06-09 14:35:04'),(217,'Photos_IndustrialPropertyPatentOffices/J1pyLCOMHd6TfMZq0aRDc1SUPBKLHj8UMGyIdarC.jpg','مديرية براءات الاختراع والنماذج الصناعية','null','مديرية براءات الاختراع والنماذج الصناعية : تقع ضمن الجهاز المركزي للتقييس والسيطرة النوعية (التابع لوزارة التخطيط)، وهي الجهة المسؤولة عن تسجيل الابتكارات، براءات الاختراع، والرسوم والنماذج الصناعية.\r\nالمقر:بغداد\r\nالخدمات :تسجيل و متابعة و حماية براءات الاختراع و حماية المستهلك و النماذج الصناعية حماية الشكل الخارجي أو الهيكل الجمالي والتصميمي للمنتجات و  تسجيل وحماية الابتكارات المصممة داخل العراق.',NULL,'https://www.cosqc.gov.iq/',6,11,4,'2026-06-10 07:57:20','2026-06-10 08:23:36'),(218,'Photos_IndustrialPropertyPatentOffices/u6qSQy6lb0o46w7lS4JXZNvABjJc29P4jQlxUFRJ.jpg','المكتب الوطني للملكية الفكرية',NULL,'تتم إدارة شؤون الملكية الصناعية في سلطنة عُمان من خلال المكتب الوطني للملكية الفكرية التابع لـ وزارة التجارة والصناعة وترويج الاستثمار. يتولى هذا المكتب تسجيل وحماية كافة حقوق الملكية الصناعية، والتي تشمل براءات الاختراع، العلامات التجارية، والرسوم والنماذج الصناعية.\r\nالمقر :مسقط، سلطنة عمان.\r\nالخدمات :يقوم المكتب بتقديم خدمات التسجيل والحماية القانونية لعدة مجالات رئيسية تشمل:لعلامات التجارية: تسجيل الشعارات، والأسماء التجارية، وعلامات الخدمة لتمييز المنتجات والمنشآت.براءات الاختراع: حماية الابتكارات التقنية والميكانيكية الجديدة ونماذج المنفعة.الرسوم والنماذج الصناعية: حماية المظهر الخارجي أو التصميم الجمالي للمنتجات الصناعية.المؤشرات الجغرافية: حماية وتوثيق المنتجات المرتبطة بمنشأ جغرافي عماني.',NULL,'https://www.tejarah.gov.om/ar',6,12,4,'2026-06-10 08:38:55','2026-06-10 08:38:55'),(219,'Photos_IndustrialPropertyPatentOffices/q7nxssaGdBDqe0heNHaR0F7KCMge8EUIjIgvuKl3.png','الإدارة العامة لحقوق الملكية الفكرية',NULL,'جهة الرسمية المسؤولة عن مكتب الملكية الصناعية في فلسطين هي الإدارة العامة لحقوق الملكية الفكرية التابعة لـ وزارة الاقتصاد الوطني الفلسطيني. يتولى هذا المكتب تنظيم وحماية عناصر الملكية الصناعية، والتي تشمل بشكل أساسي العلامات التجارية، وبراءات الاختراع، والرسوم والنماذج الصناعية.\r\nالمقر : رام الله، فلسطين.',NULL,'https://trademarks.mne.gov.ps/page.aspx?page_key=key_about_inner&lang=ar',6,13,4,'2026-06-10 08:47:20','2026-06-10 08:47:20'),(220,'Photos_IndustrialPropertyPatentOffices/NoIX4z46bBL1WviWUGI5xJ2AmdeeRqkPhPHJDkLj.jpg','إدارة حماية حقوق الملكية الفكرية',NULL,'تتولى إدارة حماية حقوق الملكية الفكرية التابعة لـ وزارة التجارة والصناعة القطرية مهام \"مكتب الملكية الصناعية\" في دولة قطر. وتقوم هذه الإدارة باستقبال وفحص طلبات براءات الاختراع، الرسوم والنماذج الصناعية، والعلامات التجارية.\r\nالمقر :مدينة لوسيل، قطر\r\nالخدمات :تسجيل براءات الاختراع: إيداع الطلبات وفحصها لحماية الابتكارات تقنياً.الرسوم والنماذج الصناعية: حماية المظهر الخارجي أو التصاميم الجمالية للمنتجات.تسجيل العلامات التجارية: قيد الأسماء، والشعارات، والبيانات التجارية الخاصة بالشركات.تجديد براءات الاختراع السنوي: دفع الرسوم السنوية للحفاظ على الحماية القانونية',NULL,'https://www.moci.gov.qa/',6,14,4,'2026-06-10 09:02:36','2026-06-10 09:02:36'),(221,'Photos_IndustrialPropertyPatentOffices/PczLs9YPWScDT8YBlJyrAkEqvvVQpeyB6DdjBLSX.jpg','إدارة براءات الاختراع والعلامات التجارية',NULL,'تتولى إدارة العلاقات التجارية وبراءة الاختراع (المعروفة بـ إدارة براءات الاختراع والعلامات التجارية) التابعة لـ وزارة التجارة والصناعة الكويتية، كامل المسؤولية عن تنظيم وحماية حقوق الملكية الصناعية في دولة الكويت.\r\nالاختصاصات:تشرف الادارة على العلامات التجارية: إصدار شهادات تسجيل العلامات، تجديدها، تعديلها، أو شطبها، بالإضافة إلى البت في طلبات المعارضة.براءات الاختراع: توثيق وإيداع براءات الاختراع، ونشرها في الجريدة الرسمية وفق القوانين المعمول بها.الرسوم والنماذج الصناعية: حماية وتوثيق النماذج والرسوم الصناعية والدوائر المتكاملة.التعاون الخليجي: التنسيق مع الأمانة العامة لمجلس التعاون لدول الخليج العربية لمتابعة تطبيق نظام براءات الاختراع الخليجي.',NULL,'https://www.moci.gov.kw/ar/',6,15,4,'2026-06-10 09:28:42','2026-06-10 09:28:42'),(222,'Photos_IndustrialPropertyPatentOffices/aWfItndGnnfqWOCPusAAtOf17d8WthWvyEuIWEoF.png','مصلحة حماية الملكية الفكرية',NULL,'تعرف الجهة الرسمية المسؤولة عن الملكية الصناعية والتجارية باسم مصلحة حماية الملكية الفكرية، وتتبع مباشرة لـ وزارة الاقتصاد والتجارة اللبنانية. يتولى هذا المكتب تسجيل براءات الاختراع، العلامات التجارية، والرسوم والنماذج الصناعية.\r\nالمقر : بيروت\r\nالخدمات :العلامات التجارية: حماية وتصديق الأسماء والشعارات التجارية لمنع التباسها مع علامات أخرى.براءات الاختراع: إيداع وفحص طلبات الاختراعات الجديدة وإصدار الشهادات الخاصة بها.الرسوم والنماذج الصناعية: تسجيل المظاهر الخارجية المبتكرة للمنتجات الصناعية.',NULL,'https://www.economy.gov.lb/ar/services/intellectual-property-right',6,16,4,'2026-06-10 09:36:34','2026-06-10 09:36:34'),(223,'Photos_IndustrialPropertyPatentOffices/eZ5Hpn5YEGML2CBVluTFSy6Rdd4vsjyBuTnrlJgV.jpg','مكتب الملكية الصناعية',NULL,'يتولى مكتب الملكية الصناعية في ليبيا تنظيم وحماية حقوق الملكية الفكرية والصناعية، وينقسم الاختصاص الإداري فيه إلى جهتين رئيسيتين بحسب نوع المعاملة:\r\nبراءات الاختراع والرسوم والنماذج الصناعية: تتبع إدارياً لـ مركز البحوث الصناعية التابع لوزارة التعليم العالي والبحث العلمي.العلامات التجارية والأسماء التجارية: تتبع لـ وزارة الاقتصاد والتجارة من خلال مصلحة السجل التجاري.\r\nالمقر :طرابلس، ليبيا.\r\nالخدمات:يقدم المكتب بـ مركز البحوث الصناعية الخدمات التالية:استقبال وفحص طلبات براءات الاختراع المحلية والدولية.تسجيل الرسوم والنماذج الصناعية وحمايتها.إصدار شهادات براءات الاختراع بعد استيفاء الشروط القانونية والفنية.',NULL,'https://irc.ly/',6,17,4,'2026-06-10 09:44:27','2026-06-10 09:44:27'),(224,'Photos_IndustrialPropertyPatentOffices/dQK6Wf2Cv0m14otC1YcnoAUwRoRmwG9tUeZXLozY.jpg','الجهاز المصري للملكية الفكرية.',NULL,'تم توحيد مكاتب وإدارات الملكية الصناعية والفكرية في مصر رسميًا تحت مظلة جهة موحدة تسمى الجهاز المصري للملكية الفكرية. حيث نُقلت إليه اختصاصات كل من مكتب براءات الاختراع المصري، وإدارة العلامات التجارية والنماذج الصناعية التابعة لـ جهاز تنمية التجارة الداخلية.\r\nالمقر : القاهرة\r\nالخدمات:',NULL,'https://www.itda.gov.eg/',6,18,4,'2026-06-10 09:55:48','2026-06-10 09:55:48'),(225,'Photos_IndustrialPropertyPatentOffices/oMr8BrV7fN58S61kLiG0pnBhrZElZTe9lEF8APK2.png','المكتب المغربي للملكية الصناعية والتجارية (OMPIC)',NULL,'المكتب المغربي للملكية الصناعية والتجارية (OMPIC)، وهو مؤسسة عمومية تخضع لوصاية وزارة الصناعة والتجارة المغربية. يتولى المكتب حماية حقوق الملكية الصناعية (كبراءات الاختراع والعلامات التجارية) وإدارة السجل التجاري المركزي.\r\nالمقر : الدار البيضاء.\r\nالخدمات :حماية الإبداعات الابتكارية: إصدار براءات الاختراع وحماية الرسوم والنماذج الصناعية.حماية الإشارات المميزة: تسجيل العلامات التجارية وعلامات الخدمة والأسماء التجارية.السجل التجاري المركزي: مسك السجل المركزي وتقديم الشهادات السلبية لتأسيس الشركات.',NULL,'http://www.ompic.ma/ar/content/dwr-lmktb-w-lmhm-lmnwt-bh',6,19,4,'2026-06-10 10:04:20','2026-06-10 10:04:20'),(226,'Photos_IndustrialPropertyPatentOffices/eIwRuOOrGQqPvAUdMfbQcBBy2QBYTuS1e6b62ONM.png','مديرية الملكية الصناعية',NULL,'تتولى مديرية الملكية الصناعية التابعة لـ وزارة المعادن والصناعة الموريتانية مسؤولية حماية حقوق الملكية الفكرية والصناعية داخل البلاد. ونظراً لأن موريتانيا عضو في المنظمة الأفريقية للملكية الفكرية (OAPI)، فإن تسجيل السندات يتبع نظاماً إقليمياً موحداً يمتد أثره القانوني تلقائياً إلى جميع الدول الأعضاء.\r\nالمقر: نواكشوط\r\nالخدمات: تسجيل السندات: تشمل براءات الاختراع والعلامات التجارية والأسماء التجارية، الرسوم والنماذج الصناعية، والمؤشرات الجغرافية.التوثيق: يدعم مركز توثيق الملكية الفكرية بنواكشوط الباحثين والمخترعين والمصنعين عبر توفير المراجع العلمية والقانونية.الربط الإقليمي: تعمل المديرية كـ هيئة وطنية للربط وتنسيق الطلبات مع المكاتب المركزية لـ منظمة OAPI .',NULL,'https://www.commerce.gov.mr/?q=node/1545',6,20,4,'2026-06-10 10:10:44','2026-06-10 10:10:44'),(227,'Photos_CentersExcellenceArtificialIntelligence/uDSOklpnu3gS1L115dhgaMWcdhDwbJv4DV1XyWEj.jpg','جامعة محمد بن زايد للذكاء الاصطناعي','MBZUAI','جامعة محمد بن زايد للذكاء الاصطناعي هي جامعة بحثية للدراسات العليا مكرسة لتعزيز الذكاء الاصطناعي وتسخيره لمصلحة الإنسانية.\r\nوهي تهدف إلى تعليم طلاب من أصحاب المواهب وتطوير قدراتهم، فضلاً عن تعزيز بيئة تشجع الابتكار، وتوفير مؤسسة بحثية استراتيجية داعمة للقطاعين الحكومي والخاص.\r\nوتؤدي الجامعة دوراً جوهرياً في تحقيق العديد من الأهداف الاستراتيجية لدولة الإمارات العربية المتحدة، لاسيما وأن الذكاء الاصطناعي يشكل عنصراً بالغ الأهمية لتحقيق النمو والازدهار مستقبلاً. وتسعى رؤية الجامعة ورسالتها الاستراتيجيتان في آنٍ لترسيخ مكانة أبوظبي كقطب من أقطاب مجتمع الذكاء الاصطناعي الدولي..',NULL,'https://mbzuai.ac.ae/',5,2,2,'2026-06-10 10:12:21','2026-06-10 10:12:21'),(228,'Photos_IndustrialPropertyPatentOffices/oDoEBQEuLM9glgQBIkmvjHOh46LxtyIUmJB5y6xD.jpg','الإدارة العامة لحماية الملكية الفكرية التجارية والصناعية وبراءات الاختراع',NULL,'الإدارة العامة لحماية الملكية الفكرية التجارية والصناعية وبراءات الاختراع تابع وزارة الصناعة والتجارة (المكتب المستقل) - عدن.\r\nالمقر : عدن .\r\nالخدمات :يمتلك مكتبًا مستقلًا لحماية الملكية الفكرية والعلامات التجارية يتطلب إجراءات وتوثيقات منفصلة لضمان حماية العلامات والنماذج في المناطق التابعة لسيطرته.',NULL,'https://moit-ye.com/?page_id=9573',6,21,4,'2026-06-10 10:29:18','2026-06-10 10:29:18'),(229,'Photos_CentersExcellenceArtificialIntelligence/bq8tb8Rh6bvAfpOzZcphCoqrkoL00RaDoPijDGC0.png','المركز المصري للذكاء الاصطناعي',NULL,'أصبح الذكاء الاصطناعي ركيزة أساسية في مسار التحول الرقمي في مصر. ومن هذا المنطلق، تقود وزارة الاتصالات وتكنولوجيا المعلومات الجهود الوطنية لوضع إطار وطني شامل يدمج بين الحوكمة والبنية التحتية وتنمية الكفاءات والبحث العلمي والابتكار في هذا المجال، بما يضمن تبنّي تقنيات الذكاء الاصطناعي على نحو مسؤول ومستدام.\r\n\r\nويرتكز هذا النهج على قناعة راسخة بأن استخدام الذكاء الاصطناعي ينبغي أن يهدف إلى خدمة المجتمع، والارتقاء بجودة الخدمات العامة، ورفع القدرة التنافسية، والمساهمة في تحقيق التنمية المستدامة. ولهذا تحرص مصر على وضع سياسات قائمة على هيكل واضح، والتنسيق بين مؤسسات الدولة، وتعزيز التعاون الدولي، للمساهمة في بناء منظومة داعمة للابتكار، مع ضمان الالتزام بالمعايير الأخلاقية، وترسيخ مبدأ الشفافية، والحفاظ على القيم التي تراعي مصلحة الإنسان.',NULL,'https://mcit.gov.eg/',5,18,2,'2026-06-10 10:29:48','2026-06-10 10:29:48'),(230,'Photos_CentersExcellenceArtificialIntelligence/YDmpJatrvlvHozHvKomyCQ52gZPIx2xGNC6qGvjT.png','مركز الرقمنة من أجل التنمية المستدامة','D4SD','مركز الرقمنة من أجل التنمية المستدامة (D4SD) في المغرب هو مبادرة وطنية وإقليمية أُطلقت سنة 2025 بالشراكة مع برنامج الأمم المتحدة الإنمائي، ويهدف إلى جعل الرقمنة والذكاء الاصطناعي رافعة للتنمية المستدامة، مع التركيز على الصحة، التعليم، المناخ، والحوكمة.',NULL,'https://www.undp.org/fr/morocco',5,19,2,'2026-06-10 11:10:11','2026-06-12 09:01:15'),(231,'Photos_CentersExcellenceArtificialIntelligence/l5Cu9eQvD8RliBSfzOmw1eCpvLLJDys904TifO6f.png','مركز قطر للذكاء الاصطناعي','Qatar Center for Artificial Intelligence (QCAI)','مركز قطر للذكاء الاصطناعي (QCAI)\r\n\r\nتعمل مجموعة مركز قطر للذكاء الاصطناعي (QCAI) التابعة لـ Qatar Computing Research Institute على تطوير الأبحاث في مختلف مجالات الذكاء الاصطناعي، بدءًا من فهم البيانات وتطوير النماذج، وصولًا إلى الاستدلال والتنبؤ واتخاذ القرار.\r\n\r\nيسهم المركز في تعزيز الأسس العلمية للذكاء الاصطناعي من خلال الابتكارات في الخوارزميات، والتعلم متعدد الوسائط، والأنظمة الذكية، كما يقود إنجازات رائدة في مجال الطب الدقيق ويعزز استخدام الذكاء الاصطناعي لخدمة المجتمع وتحقيق المنفعة العامة.\r\n\r\nينشر باحثو المركز أبحاثهم في أبرز المؤتمرات والمجلات العلمية الدولية، ويطوّرون نماذج وأنظمة أولية مبتكرة تسهم في دعم الاكتشاف العلمي، وتحسين الرعاية الصحية، وخدمة المجتمعات حول العالم.',NULL,'https://qcai.qcri.org/',5,14,2,'2026-06-10 11:15:43','2026-06-10 11:15:43'),(232,'Photos_CentersExcellenceArtificialIntelligence/iPw02hBy82CiHF4pI3tQLrq2XMEd7yyvGpbJ8Djn.png','الهيئة السعودية للبيانات والذكاء الاصطناعي','(SDAIA)','الهيئة السعودية للبيانات والذكاء الاصطناعي (SDAIA) هي الجهة الوطنية المسؤولة عن قيادة استراتيجية المملكة في مجال البيانات والذكاء الاصطناعي، تأسست سنة 2019 وتُعد من أبرز المؤسسات الإقليمية في هذا المجال، حيث تشرف على المركز الوطني للذكاء الاصطناعي، مكتب إدارة البيانات الوطنية، ومركز المعلومات الوطني.',NULL,'https://sdaia.gov.sa/',5,7,2,'2026-06-10 11:20:51','2026-06-10 11:20:51'),(233,'Photos_CentersExcellenceArtificialIntelligence/0EQAIukeiAiBFtt3lji8CBNIJaGiRZaQSxwAe0r3.png','مركز ذكاء العربية','Arabic AL Center','مركز ذكاء العربية هو أول مركز متخصص في توظيف تقنيات الذكاء الاصطناعي لخدمة اللغة العربية، أطلقه مجمع الملك سلمان العالمي للغة العربية في أبريل 2024 بالرياض، ويهدف إلى تطوير أدوات حاسوبية ومعايير لغوية تعزز حضور العربية في العالم الرقمي.\r\n\r\nويقدم مركز ذكاء العربية مجموعةً من الخدمات المتكاملة والمجانية؛ لتمكين الباحثين والمطورين من أنحاء العالم كله من توظيف تقنيات الذكاء الاصطناعي في المعالجة الآلية للغة العربية، وبناء التطبيقات، والأدوات، والبرامج التي تكفل المحافظة على اللغة العربية.',NULL,'https://arai.ksaa.gov.sa/',5,7,2,'2026-06-10 11:26:00','2026-06-10 11:26:00'),(235,'Photos_CentersExcellenceArtificialIntelligence/2D6UBV6Z6zXzuifUnWXIaDH7G0Gf0NRuLJowD7FF.webp','مدرسة الهندسة الرقمية والذكاء الاصطناعي',NULL,'مدرسة الهندسة الرقمية والذكاء الاصطناعي (EIDIA) هي مدرسة رائدة بجامعة اليوروميد بفاس، مُتخصصة في مجال التقنيات الرقمية وعلوم الذكاء الاصطناعي.\r\n\r\nتتبوأ المركز مكانةً رفيعة كمحور للتميز عند تقاطع هندسة الحاسوب والرياضيات التطبيقية وعلوم البيانات والذكاء الاصطناعي والأنظمة المدمجة الذكية والتقنيات التحويلية (سلسلة الكتل، إنترنت الأشياء، الواقع الممتد...).\r\n\r\nطموحه ثلاثي الأبعاد:\r\n\r\nغير محدد\r\n\r\nغير محدد\r\n\r\nغير محدد\r\n\r\nبفضل منهجية تعليمية قائمة على المشروع، والتطوير الرشيق، وأساليب التعلم عن طريق الممارسة، وارتباط قوي بالنظام البيئي التكنولوجي، فإن طلاب إيديا مُهيأون للعمل في أكثر البيئات ديناميكية وابتكاراً.',NULL,'https://ueuromed.org/ar/etablissements/ecole-d-ingenierie-digitale-et-d-intelligence-artificielle',5,19,2,'2026-06-10 14:36:21','2026-06-10 14:36:21'),(236,'Photos_CentersExcellenceArtificialIntelligence/0gFmLmPTXLMe8aW0e8H2m24T85NAruo8Q4zARCIG.png','AI Movement',NULL,'يُعد المركز الدولي المغربي للذكاء الاصطناعي التابع لـ Mohammed VI Polytechnic University من أهم مراكز البحث في الذكاء الاصطناعي بالمغرب. يهدف إلى تطوير الخبرات المغربية والإفريقية في الذكاء الاصطناعي وعلوم البيانات، وإيجاد حلول للتحديات الاقتصادية والاجتماعية والبيئية مع التركيز على الجوانب الأخلاقية والتطبيقية للذكاء الاصطناعي.',NULL,'https://aim.um6p.ma/',5,19,2,'2026-06-10 14:44:58','2026-06-10 14:44:58'),(238,'Photos_CentersExcellenceArtificialIntelligence/5dsIhnzmstioAnNrMXutCGm10dIGfbdTiwodqGKI.jpg','مركز الاستشراف و الذكاء الاصطناعي التابع لمنظمة الايسيسكو','Center of Foresight and Artificial intelligence','يعتبر مركز الإيسيسكو للاستشراف الاستراتيجي مركز الأبحاث الأول من نوعه في إفريقيا والعالم الإسلامي الذي يتبنى نهجا استشرافيا واستباقيا يستهدف المستويات المحلية والإقليمية والدولية، مما يرسخ مكانته كمركز بارز للخبرة',NULL,'https://icesco.org/ar/areas_of_expertise/the-strategic-foresight-center/',5,19,2,'2026-06-12 09:24:01','2026-06-12 09:25:47'),(239,'Photos_CentersExcellenceArtificialIntelligence/XpMbIBbvK6OeN4AK2LiO4kkQcShG22riqNfGTCyI.png','مركز بحوث العلوم الرقمية والذكاء الاصطناعي',NULL,'يقود مركز بحوث العلوم الرقمية والذكاء الاصطناعي جهود التحول الرقمي من خلال ترسيخ اعتماد الأنظمة والتطبيقات المستقلة والمترابطة، مع الحرص على أن تكون هذه التطبيقات والأنظمة آمنة ومستدامة وعلى قدر عال من الثقة. ويتعاون خبراؤنا اللامعين في مجالات الذكاء الاصطناعي والأمن السيبراني والاتصالات اللاسلكية عن كثب مع مجموعة من المنظمات الدولية، مثل الاتحاد الدولي للاتصالات ومنظمة 3GPP، لإيجاد الحلول العملية المناسبة للتحديات الرئيسية وترك الأثر الإيجابي العميق على المجتمع.',NULL,'https://www.tii.ae/ar/ai-and-digital-science',5,2,2,'2026-06-16 08:03:33','2026-06-16 08:03:33');
